local function switchItem(tool, delayTime)
	delayTime = delayTime or 0.05
	local check = lplr.Character and lplr.Character:FindFirstChild('HandInvItem') or nil
	if check and check.Value ~= tool and tool.Parent ~= nil then
		store._equipPending = true
		store._equipSince = tick()
		task.spawn(function()
			pcall(function()
				bedwars.Client:Get(remotes.EquipItem):CallServerAsync({hand = tool})
			end)
			store._equipPending = false
		end)
		check.Value = tool
		if delayTime > 0 then
			task.wait(delayTime)
		end
		return true
	end
end

local function liveHandTool()
	local check = lplr.Character and lplr.Character:FindFirstChild('HandInvItem')
	return check and check.Value or nil
end

local function projectileToolName(name)
	if not name then return false end
	local n = name:lower()
	return n:find('bow') ~= nil or n:find('headhunter') ~= nil or n:find('snowball') ~= nil
		or n:find('fireball') ~= nil or n:find('gloop') ~= nil or n:find('glue') ~= nil
		or n:find('chakram') ~= nil or n:find('slingshot') ~= nil
end

local function isProjectileTool(tool)
	if not tool then return false end
	local meta = bedwars.ItemMeta and bedwars.ItemMeta[tool.Name]
	if meta and meta.projectileSource then return true end
	return projectileToolName(tool.Name)
end

local function handIsProjectile()
	local serverTool = store.hand and store.hand.tool
	if serverTool then return isProjectileTool(serverTool) end
	return isProjectileTool(liveHandTool())
end

local handDesyncAt = 0
local function syncHandDesync()
	local check = lplr.Character and lplr.Character:FindFirstChild('HandInvItem')
	if not check or not check.Value then return end
	local serverTool = store.hand and store.hand.tool
	if not serverTool or serverTool == check.Value or store._equipPending then
		handDesyncAt = 0
		return
	end
	local now = tick()
	if handDesyncAt == 0 then
		handDesyncAt = now
		return
	end
	if now - handDesyncAt < 0.35 then return end
	handDesyncAt = 0
	local tool = check.Value
	store._equipPending = true
	store._equipSince = tick()
	task.spawn(function()
		pcall(function()
			bedwars.Client:Get(remotes.EquipItem):CallServerAsync({hand = tool})
		end)
		store._equipPending = false
	end)
end

local function netPing()
	local p = store.ping and store.ping.total
	if type(p) == 'number' and p > 0 then
		return math.clamp(p, 0.01, 1)
	end
	local ok, v = pcall(function() return lplr:GetNetworkPing() end)
	if ok and type(v) == 'number' and v > 0 then
		return math.clamp(v, 0.01, 1)
	end
	return 0.02
end

local function wallBetween(ent)
	local root = entitylib.character and entitylib.character.RootPart
	if not root or not ent or not ent.RootPart then return false end
	return entitylib.Wallcheck(root.Position, ent.RootPart.Position, nil, ent) ~= nil
end

local function waitForChildOfType(obj, name, timeout, prop)
	local check, returned = tick() + timeout
	repeat
		returned = prop and obj[name] or obj:FindFirstChildOfClass(name)
		if (returned and returned.Name ~= 'UpperTorso') or check < tick() then
			break
		end
		task.wait()
	until false
	return returned
end

local frictionTable, oldfrict = {}, setmetatable({}, {__mode = 'k'})
local lastUpdate = setmetatable({}, {__mode = 'k'})
local lagConnections = {}
local frictionConnection
local frictionState

local function modifyVelocity(v)
	if v:IsA('BasePart') and v.Name ~= 'HumanoidRootPart' and not oldfrict[v] then
		oldfrict[v] = v.CustomPhysicalProperties or 'none'
		v.CustomPhysicalProperties = PhysicalProperties.new(0.0001, 0.2, 0.5, 1, 1)
	end
end

local function updateVelocity(force)
	local newState = getTableSize(frictionTable) > 0
	if frictionState ~= newState or force then
		if frictionConnection then
			frictionConnection:Disconnect()
		end
		if newState then
			if entitylib.isAlive then
				for _, v in entitylib.character.Character:GetDescendants() do
					modifyVelocity(v)
				end
				frictionConnection = entitylib.character.Character.DescendantAdded:Connect(modifyVelocity)
			end
		else
			for i, v in oldfrict do
				i.CustomPhysicalProperties = v ~= 'none' and v or nil
			end
			table.clear(oldfrict)
		end
	end
	frictionState = newState
end

local function isEveryoneDead()
	return #bedwars.Store:getState().Party.members <= 0
end
	
local function joinQueue()
	if not bedwars.Store:getState().Game.customMatch and bedwars.Store:getState().Party.leader.userId == lplr.UserId and bedwars.Store:getState().Party.queueState == 0 then
		bedwars.QueueController:joinQueue(store.queueType)
	end
end

local function lobby()
    bedwars.Client:Get(remotes.TeleportToLobby):FireServer()
end

local kitorder = {
	hannah = 5,
	spirit_assassin = 4,
	dasher = 3,
	jade = 2,
	regent = 1
}

local function HasSeed(character)
    if not character then return false end
    return character:FindFirstChild("Seed", true) ~= nil
end

local kitOrder = {
	hannah = 5,
	spirit_assassin = 4,
	dasher = 3,
	jade = 2,
	regent = 1
}

local sortmethods = {
	Damage = function(a, b)
		if not a.Entity or not a.Entity.Character then return false end
		if not b.Entity or not b.Entity.Character then return true end
		return (a.Entity.Character:GetAttribute('LastDamageTakenTime') or 0) < (b.Entity.Character:GetAttribute('LastDamageTakenTime') or 0)
	end,
	Threat = function(a, b)
		if not a.Entity then return false end
		if not b.Entity then return true end
		return getStrength(a.Entity) > getStrength(b.Entity)
	end,
	Health = function(a, b)
		if not a.Entity then return false end
		if not b.Entity then return true end
		return a.Entity.Health < b.Entity.Health
	end,
	Angle = function(a, b)
		if not a.Entity or not a.Entity.RootPart then return false end
		if not b.Entity or not b.Entity.RootPart then return true end
		local selfrootpos = entitylib.character.RootPart.Position
		local rawFacing = (getgenv().ViewMode and getgenv().ViewMode.Value == 'Third Person') and gameCamera.CFrame.LookVector or entitylib.character.RootPart.CFrame.LookVector
		local flatFacing = Vector3.new(rawFacing.X, 0, rawFacing.Z)
		if flatFacing.Magnitude < 0.001 then return false end
		local localFacing = flatFacing.Unit
		local deltaA = Vector3.new(a.Entity.RootPart.Position.X - selfrootpos.X, 0, a.Entity.RootPart.Position.Z - selfrootpos.Z)
		local deltaB = Vector3.new(b.Entity.RootPart.Position.X - selfrootpos.X, 0, b.Entity.RootPart.Position.Z - selfrootpos.Z)
		if deltaA.Magnitude < 0.001 or deltaB.Magnitude < 0.001 then return deltaA.Magnitude < deltaB.Magnitude end
		local angle = math.acos(math.clamp(localFacing:Dot(deltaA.Unit), -1, 1))
		local angle2 = math.acos(math.clamp(localFacing:Dot(deltaB.Unit), -1, 1))
		return angle < angle2
	end,
	Distance = function(a, b)
		if not a.Entity or not a.Entity.RootPart then return false end
		if not b.Entity or not b.Entity.RootPart then return true end
		local selfpos = entitylib.character.RootPart.Position
		local distA = (a.Entity.RootPart.Position - selfpos).Magnitude
		local distB = (b.Entity.RootPart.Position - selfpos).Magnitude
		return distA < distB
	end,
	Cursor = function(a, b)
		if not a.Entity or not a.Entity.RootPart then return false end
		if not b.Entity or not b.Entity.RootPart then return true end
		local camera = gameCamera
		local mousePos = inputService:GetMouseLocation()
		local function screenDist(ent)
			local rootPart = ent.RootPart
			if not rootPart then return math.huge end
			local screenPos, onScreen = camera:WorldToScreenPoint(rootPart.Position)
			if not onScreen then return math.huge end
			return (Vector2.new(screenPos.X, screenPos.Y) - mousePos).Magnitude
		end
		local distA = screenDist(a.Entity)
		local distB = screenDist(b.Entity)
		if distA == math.huge and distB == math.huge then
			local selfpos = entitylib.character.RootPart.Position
			local worldA = (a.Entity.RootPart.Position - selfpos).Magnitude
			local worldB = (b.Entity.RootPart.Position - selfpos).Magnitude
			return worldA < worldB
		end
		return distA < distB
	end,
	Kit = function(a, b)
		if not a.Entity or not a.Entity.Player then return false end
		if not b.Entity or not b.Entity.Player then return true end
		return (kitOrder[a.Entity.Player:GetAttribute('PlayingAsKits')] or 0) > (kitOrder[b.Entity.Player:GetAttribute('PlayingAsKits')] or 0)
	end,
	Mouse = function(a, b)
		if not a.Entity or not a.Entity.RootPart then return false end
		if not b.Entity or not b.Entity.RootPart then return true end
		local mouse = lplr:GetMouse()
		local origin = Vector2.new(mouse.X, mouse.Y)
		local posA, visA = gameCamera:WorldToViewportPoint(a.Entity.RootPart.Position)
		local posB, visB = gameCamera:WorldToViewportPoint(b.Entity.RootPart.Position)
		local distA = visA and (Vector2.new(posA.X, posA.Y) - origin).Magnitude or math.huge
		local distB = visB and (Vector2.new(posB.X, posB.Y) - origin).Magnitude or math.huge
		return (distA == distA and distA or math.huge) < (distB == distB and distB or math.huge)
	end,
	Forest = function(a, b)
		if not a.Entity then return false end
		if not b.Entity then return true end
		local aHasSeed = HasSeed(a.Entity.Character)
		local bHasSeed = HasSeed(b.Entity.Character)
		if aHasSeed and not bHasSeed then return true end
		if not aHasSeed and bHasSeed then return false end
		if not a.Entity.RootPart then return false end
		if not b.Entity.RootPart then return true end
		local selfpos = entitylib.character.RootPart.Position
		local distA = (a.Entity.RootPart.Position - selfpos).Magnitude
		local distB = (b.Entity.RootPart.Position - selfpos).Magnitude
		return distA < distB
	end
}

local function getSortList(priority)
	local methods = {}
	for _, v in ipairs(priority or {}) do
		table.insert(methods, v)
	end
	for i in sortmethods do
		if not table.find(methods, i) then
			table.insert(methods, i)
		end
	end
	return methods
end

run(function()
	local oldstart = entitylib.start
	local function customEntity(ent)
		if ent:HasTag('inventory-entity') and not ent:HasTag('Monster') then
			return
		end

		entitylib.addEntity(ent, nil, ent:HasTag('Drone') and function(self)
			local droneplr = playersService:GetPlayerByUserId(self.Character:GetAttribute('PlayerUserId'))
			return not droneplr or lplr:GetAttribute('Team') ~= droneplr:GetAttribute('Team')
		end or function(self)
			return lplr:GetAttribute('Team') ~= self.Character:GetAttribute('Team')
		end)
	end

	entitylib.start = function()
		if entitylib.Running then entitylib.stop() end

		local function customEntity(ent)
			if playersService:GetPlayerFromCharacter(ent) then return end
			if collectionService:HasTag(ent.Parent, 'entity') then return end
			local teamFunc = function(self)
				local npcTeam = self.Character:GetAttribute('Team')
				if not npcTeam then return true end
				return lplr:GetAttribute('Team') ~= npcTeam
			end
			entitylib.addEntity(ent, nil, teamFunc)
		end

		table.insert(entitylib.Connections, playersService.PlayerAdded:Connect(function(v)
			entitylib.addPlayer(v)
		end))
		table.insert(entitylib.Connections, playersService.PlayerRemoving:Connect(function(v)
			entitylib.removePlayer(v)
		end))

		for _, v in playersService:GetPlayers() do
			entitylib.addPlayer(v)
		end

		for _, ent in collectionService:GetTagged('entity') do
			customEntity(ent)
		end

		table.insert(entitylib.Connections, collectionService:GetInstanceAddedSignal('entity'):Connect(customEntity))
		table.insert(entitylib.Connections, collectionService:GetInstanceRemovedSignal('entity'):Connect(function(ent)
			entitylib.removeEntity(ent)
		end))

		local function addDesertPot(pot)
			if not pot:IsA('Model') then return end
			entitylib.addEntity(pot, nil, function() return true end)
		end
		for _, v in collectionService:GetTagged('desert_pot') do
			addDesertPot(v)
		end
		table.insert(entitylib.Connections, collectionService:GetInstanceAddedSignal('desert_pot'):Connect(addDesertPot))
		table.insert(entitylib.Connections, collectionService:GetInstanceRemovedSignal('desert_pot'):Connect(function(v)
			entitylib.removeEntity(v)
		end))

		table.insert(entitylib.Connections, workspace:GetPropertyChangedSignal('CurrentCamera'):Connect(function()
			gameCamera = workspace.CurrentCamera or workspace:FindFirstChildWhichIsA('Camera')
		end))

		entitylib.Running = true
	end

	entitylib.addPlayer = function(plr)
		if entitylib.PlayerConnections[plr] then
			for _, conn in ipairs(entitylib.PlayerConnections[plr]) do
				if conn and typeof(conn) == "RBXScriptConnection" then
					conn:Disconnect()
				end
			end
		end

		if plr.Character then
			entitylib.refreshEntity(plr.Character, plr)
		end
		entitylib.PlayerConnections[plr] = {
			plr.CharacterAdded:Connect(function(char)
				entitylib.refreshEntity(char, plr)
			end),
			plr.CharacterRemoving:Connect(function(char)
				entitylib.removeEntity(char, plr == lplr)
			end),
			plr:GetAttributeChangedSignal('Team'):Connect(function()
				if plr == lplr then
					for _, v in entitylib.List do
						local newTargetable = entitylib.targetCheck(v)
						if v.Targetable ~= newTargetable then
							v.Targetable = newTargetable
							entitylib.Events.EntityUpdated:Fire(v)
						end
					end
				else
					entitylib.refreshEntity(plr.Character, plr)
					for _, v in entitylib.List do
						if v.Player ~= plr and v.Targetable ~= entitylib.targetCheck(v) then
							local newTargetable = entitylib.targetCheck(v)
							v.Targetable = newTargetable
							entitylib.Events.EntityUpdated:Fire(v)
						end
					end
				end
			end)
		}
	end

	entitylib.addEntity = function(char, plr, teamfunc)
		if not char then return end
		entitylib.EntityThreads[char] = task.spawn(function()
			local hum, humrootpart, head
			if plr then
				hum = waitForChildOfType(char, 'Humanoid', 10)
				humrootpart = hum and waitForChildOfType(hum, 'RootPart', workspace.StreamingEnabled and 9e9 or 10, true)
				head = char:WaitForChild('Head', 10) or humrootpart
			else
				hum = {HipHeight = 0.5}
				humrootpart = waitForChildOfType(char, 'PrimaryPart', 10, true)
				head = humrootpart
			end
			local updateobjects = {}
			if plr and plr ~= lplr then
				local names = {'ArmorInvItem_0', 'ArmorInvItem_1', 'ArmorInvItem_2', 'HandInvItem'}
				for _, name in names do
					local found = char:FindFirstChild(name)
					if found then
						table.insert(updateobjects, found)
					end
				end
			end

			if hum and humrootpart then
				local entity = {
					Connections = {},
					Character = char,
					Health = (char:GetAttribute('Health') or 100) + getShieldAttribute(char),
					Head = head,
					Humanoid = hum,
					HumanoidRootPart = humrootpart,
					HipHeight = hum.HipHeight + (humrootpart.Size.Y / 2) + (hum.RigType == Enum.HumanoidRigType.R6 and 2 or 0),
					Jumps = 0,
					JumpTick = tick(),
					Jumping = false,
					LandTick = tick(),
					MaxHealth = char:GetAttribute('MaxHealth') or 100,
					NPC = plr == nil,
					Player = plr,
					RootPart = humrootpart,
					TeamCheck = teamfunc
				}

				if plr == lplr then
					entity.AirTime = tick()
					entitylib.character = entity
					entitylib.isAlive = true
					entitylib.Events.LocalAdded:Fire(entity)
					table.insert(entity.Connections, char.AttributeChanged:Connect(function(attr)
						vapeEvents.AttributeChanged:Fire(attr)
					end))
				else
					entity.Targetable = entitylib.targetCheck(entity)

					if not plr then
						table.insert(entity.Connections, char.AttributeChanged:Connect(function(attr)
							if attr == 'Team' then
								entity.Targetable = entitylib.targetCheck(entity)
								entitylib.Events.EntityUpdated:Fire(entity)
							end
						end))
					end

					for _, v in entitylib.getUpdateConnections(entity) do
						table.insert(entity.Connections, v:Connect(function()
							entity.Health = (char:GetAttribute('Health') or 100) + getShieldAttribute(char)
							entity.MaxHealth = char:GetAttribute('MaxHealth') or 100
							entitylib.Events.EntityUpdated:Fire(entity)
						end))
					end

					local invUpdatePending = {}

					for _, v in updateobjects do
						table.insert(entity.Connections, v:GetPropertyChangedSignal('Value'):Connect(function()
							if invUpdatePending[entity] then return end
							invUpdatePending[entity] = true
							task.delay(0.1, function()
								invUpdatePending[entity] = nil
								if bedwars.getInventory then
									store.inventories[plr] = bedwars.getInventory(plr)
									entitylib.Events.EntityUpdated:Fire(entity)
								end
							end)
						end))
					end

					if plr then
						local anim = char:FindFirstChild('Animate')
						if anim then
							pcall(function()
								local jumpAnimId = anim.jump:FindFirstChildWhichIsA('Animation').AnimationId
								table.insert(entity.Connections, hum.StateChanged:Connect(function(old, new)
									if new == Enum.HumanoidStateType.Jumping then
										entity.JumpTick = tick()
										entity.Jumps += 1
										entity.LandTick = tick() + 1
										entity.Jumping = entity.Jumps > 1
									elseif new == Enum.HumanoidStateType.Landed or new == Enum.HumanoidStateType.Running or new == Enum.HumanoidStateType.Freefall then
										entity.Jumping = false
									end
								end))
							end)
						end

						local inventoryThread
						inventoryThread = task.spawn(function()
							local waitTime = 0.3
							while plr and plr.Parent and entity.Character and entity.Character.Parent do
								if bedwars.getInventory then
									local inv = bedwars.getInventory(plr)
									if inv then
										local old = store.inventories[plr]
										store.inventories[plr] = inv
										local changed = true
										if old then
											local oh = old.hand and old.hand.itemType or ''
											local nh = inv.hand and inv.hand.itemType or ''
											local oa = ''
											local na = ''
											for i = 4, 6 do
												oa = oa .. '|' .. tostring(old.armor and old.armor[i] and old.armor[i].itemType or '')
												na = na .. '|' .. tostring(inv.armor and inv.armor[i] and inv.armor[i].itemType or '')
											end
											changed = (oh ~= nh) or (oa ~= na)
										end
										if changed then
											entitylib.Events.EntityUpdated:Fire(entity)
										end
									end
								end
								task.wait(waitTime)
								if waitTime < 1.2 then
									waitTime = math.min(1.2, waitTime + 0.15)
								end
							end
							inventoryThread = nil
						end)
						table.insert(entity.Connections, {
							Disconnect = function()
								if inventoryThread then
									pcall(task.cancel, inventoryThread)
									inventoryThread = nil
								end
							end
						})
					end
					table.insert(entitylib.List, entity)
					if entitylib.InvalidateWallcheck then entitylib.InvalidateWallcheck() end
					entitylib.Events.EntityAdded:Fire(entity)
				end

				table.insert(entity.Connections, char.ChildRemoved:Connect(function(part)
					if part == humrootpart or part == hum or part == head then
						if part == humrootpart and hum.RootPart then
							humrootpart = hum.RootPart
							entity.RootPart = hum.RootPart
							entity.HumanoidRootPart = hum.RootPart
							return
						end
						entitylib.removeEntity(char, plr == lplr)
					end
				end))
			end
			entitylib.EntityThreads[char] = nil
		end)
	end

	entitylib.getUpdateConnections = function(ent)
		local char = ent.Character
		local tab = {
			char:GetAttributeChangedSignal('Health'),
			char:GetAttributeChangedSignal('MaxHealth'),
			{
				Connect = function()
					ent.Friend = ent.Player and isFriend(ent.Player) or nil
					ent.Target = ent.Player and isTarget(ent.Player) or nil
					return {Disconnect = function() end}
				end
			}
		}

		if ent.Player then
			table.insert(tab, ent.Player:GetAttributeChangedSignal('PlayingAsKit'))
			table.insert(tab, ent.Player:GetAttributeChangedSignal('PlayingAsKits'))

			local vkSignal = {
				Connect = function(_, func)
					local conn = ent.Player:GetAttributeChangedSignal('VoidKnightTier'):Connect(function()
						lastUpdate[ent] = 0
						func()
					end)
					return conn
				end
			}
			table.insert(tab, vkSignal)
		end

		local blockKickerSignal = {
			Connect = function(_, func)
				local conn = char.AttributeChanged:Connect(function(attr)
					if attr == 'BlockKickerKit_BlockCount' then
						lastUpdate[ent] = 0
						func()
					end
				end)
				return conn
			end
		}
		table.insert(tab, blockKickerSignal)

		local shieldSignal = {
			Connect = function(_, func)
				local conn = char.AttributeChanged:Connect(function(attr)
					if attr:find('Shield') then
						func()
					end
				end)
				return conn
			end
		}
		table.insert(tab, shieldSignal)

		return tab
	end

	entitylib.targetCheck = function(ent)
		if ent.Character and ent.Character:HasTag('petrified-player') then return false end
		if ent.TeamCheck then
			return ent:TeamCheck()
		end
		if ent.NPC then
			local npcTeam = ent.Character and ent.Character:GetAttribute('Team')
			if not npcTeam then return true end
			return lplr:GetAttribute('Team') ~= npcTeam
		end
		if isFriend(ent.Player) then return false end
		return lplr:GetAttribute('Team') ~= ent.Player:GetAttribute('Team')
	end
	vape:Clean(entitylib.Events.LocalAdded:Connect(updateVelocity))
end)
entitylib.start()

run(function()
	local KnitInit, Knit
	repeat
		KnitInit, Knit = pcall(function()
			return debug.getupvalue(require(lplr.PlayerScripts.TS.knit).setup, 9)
		end)
		if KnitInit then break end
		task.wait()
	until KnitInit

	if not debug.getupvalue(Knit.Start, 1) then
		repeat task.wait() until debug.getupvalue(Knit.Start, 1)
	end

	-- A single stale require path must not zero the whole bedwars table: hand
	-- back an inert proxy for missing modules so everything else still loads.
	local _missingModule
	_missingModule = setmetatable({}, {
		__index = function() return _missingModule end,
		__call = function() return _missingModule end,
	})
	local _realRequire = require
	local require = function(module, ...)
		local ok, res = pcall(_realRequire, module, ...)
		return ok and res or _missingModule
	end

	-- Missing knit controllers get the same inert proxy as missing modules so a
	-- single renamed controller can't nil-index crash every module that loads after.
	getgenv().NYXMissingModule = _missingModule
	local _ctrls = Knit.Controllers or {}
	local KC = setmetatable({}, {
		__index = function(_, k)
			local c = _ctrls[k]
			return c == nil and _missingModule or c
		end,
	})
	-- Real controller lookup: missing controllers must read as nil so
	-- `if ctrl and ctrl.field` guards don't treat the inert proxy as present.
	local function _realCtrl(name)
		local c = Knit.Controllers or _ctrls
		return c and c[name]
	end

	local Flamework = require(replicatedStorage['rbxts_include']['node_modules']['@flamework'].core.out).Flamework or _missingModule
	local InventoryUtil = require(replicatedStorage.TS.inventory['inventory-util']).InventoryUtil
	local Client = (function()
		local okC, res = pcall(function()
			return require(replicatedStorage.TS.remotes).default.Client
		end)
		return (okC and res) or _missingModule
	end)()
	local OldGet, OldBreak = Client.Get

	local rakNet = false
	run(function()
		rakNet = typeof(raknet) == 'table'
	end)

	local _bedwarsMT = {
		__index = function(self, ind)
			local v = _realCtrl(ind)
			if v ~= nil then
				rawset(self, ind, v)
				return v
			end
			if ind == 'KnitClient' then
				rawset(self, ind, Knit)
				return Knit
			end
			-- Missing *Controller fields read as nil so presence guards work;
			-- other missing fields keep the inert proxy for chained access.
			if type(ind) == 'string' and ind:sub(-10) == 'Controller' then
				return nil
			end
			local p = _missingModule
			rawset(self, ind, p)
			return p
		end
	}
