run(function()
	local Velocity
	local Vertical
	local Horizontal
	local Mode
	local DelayGround
	local DelayAir
	local Targetting
	local Chance
	local KiteMode
	local KiteHorizontal
	local KiteVertical
	local AlwaysKite
	local old = nil
	local rand = Random.new()

	local function hitterPosition(hitFrom)
		local ok, ids = pcall(function()
			return bedwars.KnockbackController.recentlyReceivedKnockback:getValues()
		end)
		if ok and type(ids) == 'table' then
			for i = #ids, 1, -1 do
				local plr = playersService:GetPlayerByUserId(ids[i])
				local char = plr and plr.Character
				local part = char and char.PrimaryPart
				if part then
					return part.Position
				end
			end
		end
		return typeof(hitFrom) == 'Vector3' and hitFrom or nil
	end

	local function kiting(root, hitFrom)
		if not KiteMode.Enabled then return false end
		if AlwaysKite.Enabled then return true end
		if not root then return false end
		local from = hitterPosition(hitFrom)
		if not from or (from - root.Position).Magnitude > 20 then return false end
		local toHitter = (from - root.Position) * Vector3.new(1, 0, 1)
		local look = root.CFrame.LookVector * Vector3.new(1, 0, 1)
		if toHitter.Magnitude < 0.5 or look.Magnitude < 0.01 then return false end
		return look.Unit:Dot(toHitter.Unit) < -0.2
	end

	Velocity = vape.Categories.Combat:CreateModule({
		Name = 'Velocity',
		Tooltip = 'control you to edit ur knockback',
		Function = function(callback)
			if callback then
				old = bedwars.KnockbackUtil.applyKnockback
				Velocity:Clean(vapeEvents.TakeKnockback.Event:Connect(function(root, mass, dir, knockback, ...)
					local args = {...}
					local clone = table.clone(knockback)

					local air, ground = false, false
					task.delay(DelayAir.Value / 1000, function()
						clone.horizontal = knockback.horizontal or 1
						air = true
					end)
					task.delay(DelayGround.Value / 1000, function()
						clone.vertical = knockback.vertical or 1
						ground = true
					end)
					repeat task.wait(0.1) until air
					repeat task.wait(0.05) until ground
					old(root, mass, dir, clone, unpack(args))
				end))

				bedwars.KnockbackUtil.applyKnockback = function(root, mass, dir, knockback, ...)
					local check = (not Targetting.Enabled) or entitylib.EntityPosition({
						Range = 50,
						Part = 'RootPart',
						Players = true
					})

					if check and kiting(root, dir) then
						local boosted = table.clone(knockback or {})
						boosted.horizontal = (boosted.horizontal or 1) * (KiteHorizontal.Value / 100)
						boosted.vertical = (boosted.vertical or 1) * (KiteVertical.Value / 100)
						return old(root, mass, dir, boosted, ...)
					end

					local chance = rand:NextNumber(0, 100)
					chance = math.floor(chance)
					if Mode.Value == 'Default' then
						if chance >= Chance.Value then return old(root, mass, dir, knockback, ...) end
					end

					if check then
						knockback = knockback or {}
						if Mode.Value == 'Lag' then
							if chance < Chance.Value then
								return vapeEvents.TakeKnockback:Fire(root, mass, dir, knockback, ...)
							end
						else
							if Horizontal.Value == 0 and Vertical.Value == 0 then return end
							knockback.horizontal = (knockback.horizontal or 1) * (Horizontal.Value / 100)
							knockback.vertical = (knockback.vertical or 1) * (Vertical.Value / 100)
						end
					end

					return old(root, mass, dir, knockback, ...)
				end
			else
				bedwars.KnockbackUtil.applyKnockback = old
				old = nil
			end
		end
	})
	Mode = Velocity:CreateDropdown({
		Name = "Mode",
		List = {'Lag','Default'},
		Function = function(val)
			local isDefault = val == 'Default'
			if Horizontal then Horizontal.Object.Visible = isDefault end
			if Vertical then Vertical.Object.Visible = isDefault end
			if DelayGround then DelayGround.Object.Visible = not isDefault end
			if DelayAir then DelayAir.Object.Visible = not isDefault end
		end
	})
	Vertical = Velocity:CreateSlider({
		Name = "Vertical",
		Min = 0,
		Max = 100,
		Default = 100,
		Decimal = 1,
		Visible = (Mode.Value == 'Default')
	})
	Horizontal = Velocity:CreateSlider({
		Name = "Horizontal",
		Min = 0,
		Max = 100,
		Default = 100,
		Decimal = 1,
		Visible = (Mode.Value == 'Default')
	})
	DelayGround = Velocity:CreateSlider({
		Name = "Delay Ground",
		Min = 0,
		Max = 3000,
		Default = 1000,
		Suffix = 'ms',
		Decimal = 1,
		Visible = (Mode.Value == 'Lag')
	})
	DelayAir = Velocity:CreateSlider({
		Name = "Delay Air",
		Min = 0,
		Max = 3000,
		Default = 1000,
		Suffix = 'ms',
		Decimal = 1,
		Visible = (Mode.Value == 'Lag')
	})
	Targetting = Velocity:CreateToggle({
		Name = 'Only when targetting',
		Default = false
	})
	Chance = Velocity:CreateSlider({
		Name = "Chance",
		Min = 0,
		Max = 100,
		Default = 100,
		Decimal = 1,
		Suffix = '%',
		Tooltip = 'how often it actually changes ur knockback, 100 means every hit'
	})
	KiteMode = Velocity:CreateToggle({
		Name = 'Kite Mode',
		Tooltip = 'boosts ur knockback when ur not facing them so u fly further away when runnin',
		Function = function(callback)
			if KiteHorizontal then KiteHorizontal.Object.Visible = callback end
			if KiteVertical then KiteVertical.Object.Visible = callback end
			if AlwaysKite then AlwaysKite.Object.Visible = callback end
		end
	})
	KiteHorizontal = Velocity:CreateSlider({
		Name = 'Kite Horizontal',
		Min = 100,
		Max = 200,
		Default = 120,
		Suffix = '%',
		Darker = true,
		Visible = false
	})
	KiteVertical = Velocity:CreateSlider({
		Name = 'Kite Vertical',
		Min = 100,
		Max = 200,
		Default = 120,
		Suffix = '%',
		Darker = true,
		Visible = false
	})
	AlwaysKite = Velocity:CreateToggle({
		Name = 'Always Kite',
		Tooltip = 'boosts ur knockback on every hit even when ur facin them',
		Darker = true,
		Visible = false
	})
end)

--[[
	Blatant Modules
]]

run(function()
	local SilentAim
	local Targets
	local TargetPart
	local Sort
	local PredictionScale
	local FOV
	local HitChance
	local HeadshotChance
	local OtherProjectiles
	local Blacklist
	local MiloCheck

	local RayCheck = RaycastParams.new()
	RayCheck.FilterType = Enum.RaycastFilterType.Include

	local RandomGenerator = Random.new()

	local TargetLimbs = {
		Torso = {'UpperTorso', 'LowerTorso'},
		['Left arm'] = {'LeftUpperArm', 'LeftLowerArm', 'LeftHand'},
		['Right arm'] = {'RightUpperArm', 'RightLowerArm', 'RightHand'},
		['Left leg'] = {'LeftUpperLeg', 'LeftLowerLeg', 'LeftFoot'},
		['Right leg'] = {'RightUpperLeg', 'RightLowerLeg', 'RightFoot'}
	}
	local LimbOrder = {'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg'}
	local RandomLimb = setmetatable({}, {__mode = 'k'})

	local function isHeadshotProjectile(itemType)
		if not itemType then return false end
		local lower = tostring(itemType):lower()
		if lower:find('headhunter', 1, true) or lower:find('tactical', 1, true) then
			return true
		end
		return store.equippedKit == 'archer'
	end

	local function isDisguised(ent)
		if not ent.Player then return false end
		local controller = bedwars.BlockDisguiseController
		if controller and controller.getPlayerBlockModel then
			return controller:getPlayerBlockModel(ent.Player) ~= nil
		end
		return workspace:FindFirstChild('DisguisedPlayerBlock_' .. ent.Player.UserId) ~= nil
	end

	local function getTargetPart(ent, mode)
		if mode == 'Random' and ent.Character then
			local pick = RandomLimb[ent.Character]
			if not pick or tick() > pick.Clock then
				pick = {Value = LimbOrder[math.random(1, #LimbOrder)], Clock = tick() + 1}
				RandomLimb[ent.Character] = pick
			end
			mode = pick.Value
		end

		if mode == 'Head' then
			return (ent.Character and ent.Character:FindFirstChild('Head')) or ent.Head or ent.RootPart
		end

		local limbs = TargetLimbs[mode]
		if limbs and ent.Character then
			for _, v in limbs do
				local part = ent.Character:FindFirstChild(v)
				if part then
					return part
				end
			end
		end

		return ent.RootPart
	end

	local Motion = setmetatable({}, {__mode = 'k'})
	local function getHitChance(ent, flight)
		if not flight or flight ~= flight or flight <= 0 then
			return 0
		end

		local root = ent.RootPart
		local velocity = root.AssemblyLinearVelocity * Vector3.new(1, 0, 1)
		local sample = Motion[root]
		if not sample then
			sample = {velocity = velocity, clock = os.clock(), accel = 0, speed = velocity.Magnitude}
			Motion[root] = sample
		end

		local step = os.clock() - sample.clock
		if step >= 0.05 then
			local blend = math.min(step * 5, 1)
			sample.accel += (((velocity - sample.velocity).Magnitude / step) - sample.accel) * blend
			sample.speed += (velocity.Magnitude - sample.speed) * blend
			sample.velocity, sample.clock = velocity, os.clock()
		end

		local drift = math.max(sample.speed, velocity.Magnitude) * math.min(flight, 0.4) * math.clamp(sample.accel / 120, 0, 1)
		return 1 / (1 + ((drift / 3) ^ 2))
	end

	local function solveSilent(arguments)
		local origin, velocity, projType = arguments[4], arguments[6], arguments[3]
		if typeof(origin) ~= 'Vector3' or typeof(velocity) ~= 'Vector3' or type(projType) ~= 'string' then
			return
		end

		if (not OtherProjectiles.Enabled) and not projType:find('arrow') then
			return
		end

		if table.find(Blacklist.ListEnabled or {}, ((projType == 'glue_trap' or projType == 'glue_projectile') and 'gloop' or projType)) then
			return
		end

		local meta = bedwars.ProjectileMeta[projType]
		if not meta then
			return
		end

		local speed = velocity.Magnitude
		if speed <= 0 then
			return
		end

		if RandomGenerator:NextNumber(0, 100) > HitChance:GetRandomValue() then
			return
		end

		local map = workspace:FindFirstChild('Map')
		if map ~= RayCheck.FilterDescendantsInstances[1] then
			RayCheck.FilterDescendantsInstances = map and {map} or {}
		end
		local gravity = meta.gravitationalAcceleration or 196.2

		local target = entitylib.EntityMouse({
			Part = 'RootPart',
			Range = FOV.Value,
			Players = Targets.Players.Enabled,
			NPCs = (Targets.NPCs and Targets.NPCs.Enabled) or false,
			Priority = Targets.Priority.Value,
			Wallcheck = Targets.Walls.Enabled,
			Sort = Sort.Value ~= 'Distance' and sortmethods[Sort.Value] or nil,
			MouseOrigin = gameCamera.ViewportSize / 2,
			Origin = origin,
			Check = function(candidate)
				return not (MiloCheck.Enabled and isDisguised(candidate))
			end
		})
		if not target then
			return
		end

		local partName = RandomGenerator:NextNumber(0, 100) < HeadshotChance:GetRandomValue() and 'Head' or TargetPart.Value
		local selectedPart = getTargetPart(target, partName)
		local targetPosition
		if partName == 'Closest' then
			local center, closestDistance = gameCamera.ViewportSize / 2, 9e9
			for _, v in target.Character:GetChildren() do
				if v:IsA('BasePart') then
					local screenPosition, visible = gameCamera:WorldToViewportPoint(v.Position)
					if visible then
						local partDistance = (center - Vector2.new(screenPosition.X, screenPosition.Y)).Magnitude
						if partDistance < closestDistance then
							closestDistance, targetPosition = partDistance, v.Position
						end
					end
				end
			end
			targetPosition = targetPosition or target.Character.PrimaryPart and target.Character.PrimaryPart.Position
		elseif partName == 'Dynamic' then
			local tool = store.hand.tool
			if isHeadshotProjectile(tool and tool.Name) and target.Character:FindFirstChild('Head') then
				targetPosition = target.Character.Head.Position
			else
				targetPosition = target.Character.PrimaryPart and target.Character.PrimaryPart.Position
			end
		end

		targetPosition = targetPosition or selectedPart and selectedPart.Position
		if not targetPosition then
			return
		end
		local playerGravity = workspace.Gravity
		local balloons = target.Character:GetAttribute('InflatedBalloons')
		if balloons and balloons > 0 then
			playerGravity = workspace.Gravity * (1 - (balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975))
		end

		if target.Character.PrimaryPart and target.Character.PrimaryPart:FindFirstChild('rbxassetid://8200754399') then
			playerGravity = 6
		end

		if target.Player and target.Player:GetAttribute('IsOwlTarget') then
			for _, v in collectionService:GetTagged('Owl') do
				if v:GetAttribute('Target') == target.Player.UserId and v:GetAttribute('Status') == 2 then
					playerGravity = 0
				end
			end
		end

		local isPearl = projType == 'telepearl'
		local targetVelocity = isPearl and Vector3.zero or target.RootPart.AssemblyLinearVelocity
		local targetAirborne = (not isPearl and target.Humanoid and target.Humanoid.FloorMaterial == Enum.Material.Air) or math.abs(targetVelocity.Y) > 0.01
		local aimPosition, _, travelTime = prediction.SolveTrajectory(origin, speed * PredictionScale.Value, gravity, targetPosition, targetVelocity, playerGravity, target.HipHeight, target.Jumping and 42.6 or nil, RayCheck, targetAirborne, target.RootPart.Position, target.RootPart, nil, true)
		if not aimPosition or not travelTime or travelTime > (meta.lifetimeSec or 3) then
			return
		end

		if targetinfo and targetinfo.Targets then
			targetinfo.Targets[target] = tick() + 1
		end
		store.hitchance = store.hitchance or {}
		store.hitchance.SilentAim = {Value = getHitChance(target, travelTime), Clock = tick()}
		return CFrame.lookAt(origin, aimPosition).LookVector * speed
	end

	local projectileAim = {Shots = {}, Solvers = {}, Active = true}
	vape.Libraries.projectileaim = projectileAim
	projectileAim.Solvers.SilentAim = solveSilent

	function projectileAim.Resolve(args, side)
		local id = args[7]
		if not projectileAim.Active or type(id) ~= 'string' or id == ''
			or typeof(args[4]) ~= 'Vector3' or typeof(args[6]) ~= 'Vector3' or args[6].Magnitude <= 0 then return end
		local now = os.clock()
		for key, entry in projectileAim.Shots do
			if now - entry.At > 2 then projectileAim.Shots[key] = nil end
		end
		local entry = projectileAim.Shots[id]
		if entry and entry.Type == args[3] and entry.Side ~= side then
			projectileAim.Shots[id] = nil
			return entry
		end
		local pa = vape.Modules.ProjectileAimbot
		local mode = SilentAim.Enabled and 'SilentAim' or pa and pa.Enabled and 'ProjectileAimbot'
		local solver = mode and projectileAim.Solvers[mode]
		local prepared = table.clone(args)
		local ok, velocity
		if solver then
			ok, velocity = pcall(solver, prepared)
		end
		local aimed = ok and typeof(velocity) == 'Vector3' and velocity.Magnitude > 0
		entry = {Type = args[3], Side = side, At = now, Velocity = aimed and velocity or nil, Data = aimed and prepared[8] or nil}
		projectileAim.Shots[id] = entry
		return entry
	end

	local function localProjectile(...)
		if not projectileAim.Active or (checkcaller and checkcaller()) then
			return projectileAim.Local(...)
		end
		local args = table.pack(...)
		local offset = typeof(args[4]) == 'Vector3' and 0 or typeof(args[5]) == 'Vector3' and 1 or nil
		if offset then
			local shot = {
				liveHandTool() or (store.hand and store.hand.tool), args[2 + offset], args[3 + offset],
				args[4 + offset], nil, args[6 + offset], args[5 + offset], args[7 + offset]
			}
			local entry = projectileAim.Resolve(shot, 'local')
			if entry and entry.Velocity then
				args[6 + offset] = entry.Velocity
				if entry.Data then args[7 + offset] = entry.Data end
			end
		end
		return projectileAim.Local(table.unpack(args, 1, args.n))
	end

	function projectileAim.Install()
		local controller = bedwars.ProjectileController
		if not projectileAim.Local and controller and type(controller.createLocalProjectile) == 'function' then
			projectileAim.Local = controller.createLocalProjectile
			controller.createLocalProjectile = localProjectile
		end
		if projectileAim.Namecall or not hookmetamethod then return end
		local wrap = newcclosure or function(func) return func end
		projectileAim.Namecall = hookmetamethod(game, '__namecall', wrap(function(...)
			if not projectileAim.Active or (checkcaller and checkcaller()) or getnamecallmethod() ~= 'InvokeServer' then
				return projectileAim.Namecall(...)
			end
			local remote = ...
			if typeof(remote) ~= 'Instance' or remote.Name ~= 'ProjectileFire' then
				return projectileAim.Namecall(...)
			end
			local args = table.pack(select(2, ...))
			local entry = projectileAim.Resolve(args, 'packet')
			if entry and entry.Velocity then
				args[6] = entry.Velocity
				if entry.Data then args[8] = entry.Data end
			end
			return projectileAim.Namecall(remote, table.unpack(args, 1, args.n))
		end))
	end

	vape:Clean(function()
		projectileAim.Active = false
		table.clear(projectileAim.Shots)
		local controller = bedwars.ProjectileController
		if controller and controller.createLocalProjectile == localProjectile then
			controller.createLocalProjectile = projectileAim.Local
		end
	end)

	SilentAim = vape.Categories.Blatant:CreateModule({
		Name = 'SilentAim',
		Function = function(callback)
			if callback then
				projectileAim.Install()
			end
		end,
		Tooltip = 'Redirects only the projectile values sent to the server, so enemies get hit while your shot flies exactly where you aimed on your own screen. Without native hooks (Solara, Xeno) the shot is turned at release instead and the trajectory preview is left untouched'
	})

	Targets = SilentAim:CreateTargets({
		Players = true,
		Walls = true
	})
	TargetPart = SilentAim:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg', 'Random', 'Dynamic', 'Closest'}
	})
	Sort = SilentAim:CreateDropdown({
		Name = 'Target Mode',
		List = {'Damage', 'Distance', 'Angle', 'Health', 'Kit', 'Mouse', 'Threat'},
		Default = 'Distance'
	})
	Sort:SetValue('Distance')
	PredictionScale = SilentAim:CreateSlider({
		Name = 'Prediction',
		Min = 0.1,
		Max = 2,
		Default = 1,
		Decimal = 10
	})
	FOV = SilentAim:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 1000
	})
	HitChance = SilentAim:CreateTwoSlider({
		Name = 'Hit Chance',
		Min = 0,
		Max = 100,
		DefaultMin = 100,
		DefaultMax = 100,
		Tooltip = 'Chance in % for each shot to be redirected, rolled fresh between the two values on every shot. A missed roll leaves the shot where you aimed'
	})
	HeadshotChance = SilentAim:CreateTwoSlider({
		Name = 'Headshot Chance',
		Min = 0,
		Max = 100,
		DefaultMin = 0,
		DefaultMax = 0,
		Tooltip = 'Chance in % for each redirected shot to aim at the head instead of the Part setting, rolled fresh between the two values on every shot'
	})
	OtherProjectiles = SilentAim:CreateToggle({
		Name = 'Other Projectiles',
		Function = function(callback)
			if Blacklist then
				Blacklist.Object.Visible = callback
			end
		end,
		Default = true
	})
	Blacklist = SilentAim:CreateTextList({
		Name = 'Blacklist',
		Default = {'gloop', 'telepearl'},
		Darker = true,
		Placeholder = 'projectile'
	})
	MiloCheck = SilentAim:CreateToggle({
		Name = 'Milo check',
		Default = true,
		Tooltip = 'Skips Milo players while they are disguised as a block'
	})
end)

local AntiFallDirection
run(function()
    local AntiFall
    local Mode
    local Material
    local Color
	local rayCheck = cloneRaycast()
    rayCheck.RespectCanCollide = true

    local math_huge = math.huge
    local tick = tick
    local task_wait = task.wait
    local vector3new = Vector3.new
    local vector3zero = Vector3.zero
    
    local cachedLowGround = math_huge
    local lastGroundScan = 0
    local groundScanInterval = 2 
    
    local function getLowGround()
        local now = tick()
        if now - lastGroundScan < groundScanInterval and cachedLowGround ~= math_huge then
            return cachedLowGround
        end
        
        lastGroundScan = now
        local mag = math_huge
        local blockStore = bedwars.BlockController:getStore()
        local allPositions = blockStore:getAllBlockPositions()
        
        for i = 1, #allPositions do
            local pos = allPositions[i] * 3
            if pos.Y < mag and not getPlacedBlock(pos + vector3new(0, 3, 0)) then
                mag = pos.Y
            end
        end
        
        cachedLowGround = mag
        return mag
    end

    AntiFall = vape.Categories.Blatant:CreateModule({
        Name = 'AntiFall',
        Function = function(callback)
            if callback then
                repeat task_wait() until store.matchState ~= 0 or (not AntiFall.Enabled)
                if not AntiFall.Enabled then return end

                local pos, debounce = getLowGround(), tick()
                if pos ~= math_huge then
                    AntiFallPart = Instance.new('Part')
                    AntiFallPart.Size = vector3new(10000, 1, 10000)
                    AntiFallPart.Transparency = 1 - Color.Opacity
                    AntiFallPart.Material = Enum.Material[Material.Value]
                    AntiFallPart.Color = Color3.fromHSV(Color.Hue, Color.Sat, Color.Value)
                    AntiFallPart.Position = vector3new(0, pos - 2, 0)
                    AntiFallPart.CanCollide = Mode.Value == 'Collide'
                    AntiFallPart.Anchored = true
                    AntiFallPart.CanQuery = false
                    AntiFallPart.Parent = workspace
                    AntiFall:Clean(AntiFallPart)
                    
                    AntiFall:Clean(AntiFallPart.Touched:Connect(function(touched)
                        if touched.Parent == lplr.Character and entitylib.isAlive and debounce < tick() then
                            debounce = tick() + 0.1
                            
                            if Mode.Value == 'Normal' then
                                local top = getNearGround()
                                if top then
                                    local lastTeleport = lplr:GetAttribute('LastTeleported')
                                    local connection
                                    local frameCounter = 0
                                    
                                    local vapeModules = vape.Modules
                                    local flyEnabled = vapeModules.Fly
                                    local infFlyEnabled = vapeModules.InfiniteFly
                                    local longJumpEnabled = vapeModules.LongJump
                                    
                                    local yMask = vector3new(1, 0, 1)
                                    local yOnly = vector3new(0, 1, 0)
                                    
                                    connection = runService.PreSimulation:Connect(function()
                                        frameCounter = frameCounter + 1
                                        
                                        if frameCounter % 5 == 0 then
                                            if flyEnabled.Enabled or infFlyEnabled.Enabled or longJumpEnabled.Enabled then
                                                connection:Disconnect()
                                                AntiFallDirection = nil
                                                return
                                            end
                                        end

                                        if entitylib.isAlive and lplr:GetAttribute('LastTeleported') == lastTeleport then
                                            local root = entitylib.character.RootPart
                                            local rootPos = root.Position
                                            local delta = (top - rootPos) * yMask
                                            
                                            AntiFallDirection = delta.Unit == delta.Unit and delta.Unit or vector3zero
                                            root.Velocity *= yMask
                                            
                                            if frameCounter % 3 == 0 then
                                                rayCheck.FilterDescendantsInstances = {gameCamera, lplr.Character}
                                                rayCheck.CollisionGroup = root.CollisionGroup

                                                local ray = workspace:Raycast(rootPos, AntiFallDirection, rayCheck)
                                                if ray then
                                                    for i = 1, 5 do
                                                        local dpos = roundPos(ray.Position + ray.Normal * 1.5) + vector3new(0, 3, 0)
                                                        if not getPlacedBlock(dpos) then
                                                            top = vector3new(top.X, pos.Y, top.Z)
                                                            break
                                                        end
                                                    end
                                                end
                                            end

                                            local yDiff = top.Y - rootPos.Y
                                            root.CFrame += vector3new(0, yDiff, 0)
                                            
                                            if not frictionTable.Speed then
                                                local speed = getSpeed()
                                                local newVelocity = (AntiFallDirection * speed) + vector3new(0, root.AssemblyLinearVelocity.Y, 0)
                                                root.AssemblyLinearVelocity = newVelocity
                                            end

                                            if delta.Magnitude < 1 then
                                                connection:Disconnect()
                                                AntiFallDirection = nil
                                            end
                                        else
                                            connection:Disconnect()
                                            AntiFallDirection = nil
                                        end
                                    end)
                                    AntiFall:Clean(connection)
                                end
                            elseif Mode.Value == 'Velocity' then
                                local rootVel = entitylib.character.RootPart.Velocity
                                entitylib.character.RootPart.Velocity = vector3new(rootVel.X, 100, rootVel.Z)
                            end
                        end
                    end))
                end
            else
                AntiFallDirection = nil
                cachedLowGround = math_huge
                lastGroundScan = 0
            end
        end,
        Tooltip = 'Help\'s you with your Parkinson\'s\nPrevents you from falling into the void.'
    })
    
    Mode = AntiFall:CreateDropdown({
        Name = 'Move Mode',
        List = {'Normal', 'Collide', 'Velocity'},
        Function = function(val)
            if AntiFallPart then
                AntiFallPart.CanCollide = val == 'Collide'
            end
        end,
        Tooltip = 'Normal - Smoothly moves you towards the nearest safe point\nVelocity - Launches you upward after touching\nCollide - Allows you to walk on the part'
    })
    
    local materials = {'ForceField'}
    for _, v in Enum.Material:GetEnumItems() do
        if v.Name ~= 'ForceField' then
            table.insert(materials, v.Name)
        end
    end
    
    Material = AntiFall:CreateDropdown({
        Name = 'Material',
        List = materials,
        Function = function(val)
            if AntiFallPart then
                AntiFallPart.Material = Enum.Material[val]
            end
        end
    })
    
    Color = AntiFall:CreateColorSlider({
        Name = 'Color',
        DefaultOpacity = 0.5,
        Function = function(h, s, v, o)
            if AntiFallPart then
                AntiFallPart.Color = Color3.fromHSV(h, s, v)
                AntiFallPart.Transparency = 1 - o
            end
        end
    })
end)

run(function()
    local _sharedHitBlock = nil
    local _hitBlockPatchers = {}

    getgenv().registerHitBlockPatch = function(key, fn)
        _hitBlockPatchers[key] = fn
        if not _sharedHitBlock and bedwars.BlockBreaker then
            _sharedHitBlock = bedwars.BlockBreaker.hitBlock
        end
        if not bedwars.BlockBreaker then return end
        bedwars.BlockBreaker.hitBlock = function(self, maid, raycastparams, ...)
            for _, patcher in _hitBlockPatchers do
                local result = patcher(self, maid, raycastparams, ...)
                if result ~= nil then return result end
            end
            if _sharedHitBlock then return _sharedHitBlock(self, maid, raycastparams, ...) end
        end
    end

    getgenv().unregisterHitBlockPatch = function(key)
        _hitBlockPatchers[key] = nil
        if not next(_hitBlockPatchers) then
            if bedwars.BlockBreaker then
                bedwars.BlockBreaker.hitBlock = _sharedHitBlock
            end
            _sharedHitBlock = nil
        end
    end

    local FastBreak
    local Time
    local BedCheck
    local Blacklist
    local blocks
    local string_lower = string.lower
    local string_find = string.find
    local task_wait = task.wait
    local currentBlock = nil
    local oldHitBlock = nil
    local lastHotbarSlot = nil
    local bedCache = {}
    local blacklistCache = {}
    local lastCacheClean = 0
    local cacheCleanInterval = 5 
    
    local function isBed(block)
        if not block then return false end
        local cached = bedCache[block]
        if cached ~= nil then return cached end
        
        local result = false
        pcall(function()
            if collectionService:HasTag(block, 'bed') or (block.Parent and collectionService:HasTag(block.Parent, 'bed')) then
                result = true
            elseif string_find(string_lower(block.Name), 'bed', 1, true) then
                result = true
            end
        end)
        
        if result then bedCache[block] = true end
        return result
    end
    
    local cachedBlacklistLower = {}
    local function updateBlacklistCache()
        if not blocks or not blocks.ListEnabled then return end
        
        cachedBlacklistLower = {}
        for _, v in pairs(blocks.ListEnabled) do
            table.insert(cachedBlacklistLower, string_lower(v))
        end
    end
    
    local function isBlacklisted(block)
        if not block or #cachedBlacklistLower == 0 then return false end
        local cached = blacklistCache[block]
        if cached ~= nil then return cached end
        
        local name = string_lower(block.Name)
        local result = false
        for i = 1, #cachedBlacklistLower do
            if string_find(name, cachedBlacklistLower[i], 1, true) then
                result = true
                break
            end
        end
        
        blacklistCache[block] = result
        return result
    end
    
    local function shouldSkip(block)
        if not block then return false end
        if BedCheck and BedCheck.Enabled and isBed(block) then return true end
        if Blacklist and Blacklist.Enabled and isBlacklisted(block) then return true end
        return false
    end
    
    local lastBreakUpdate = 0
    local breakUpdateCooldown = 0.05
    local pendingUpdate = false
    
    local function updateBreakSpeed()
        if not FastBreak or not FastBreak.Enabled then return end
        local now = tick()
        if now - lastBreakUpdate < breakUpdateCooldown then
            pendingUpdate = true
            return
        end
        lastBreakUpdate = now
        pendingUpdate = false
        
        pcall(function()
            local cooldown = (shouldSkip(currentBlock)) and 0.3 or Time.Value
            bedwars.BlockBreakController.blockBreaker:setCooldown(cooldown)
        end)
    end
    
    FastBreak = vape.Categories.Blatant:CreateModule({
        Name = 'FastBreak',
        Function = function(callback)
            if callback then
                lastHotbarSlot = nil

				registerHitBlockPatch('FastBreak', function(self, maid, raycastparams, ...)
					local block = nil
					pcall(function()
						local blockInfo = self.clientManager:getBlockSelector():getMouseInfo(1, {ray = raycastparams})
						if blockInfo and blockInfo.target and blockInfo.target.blockInstance then
							block = blockInfo.target.blockInstance
						end
					end)
					
					local currentSlot = store.inventory and store.inventory.hotbarSlot
					local slotChanged = currentSlot ~= lastHotbarSlot
					if slotChanged then
						lastHotbarSlot = currentSlot
					end

					if block ~= currentBlock or slotChanged then
						currentBlock = block
						updateBreakSpeed()
					end
					end)
                
                updateBlacklistCache()
                
                task.spawn(function()
                    while FastBreak.Enabled do
                        if tick() - lastCacheClean > cacheCleanInterval then
                            lastCacheClean = tick()
                            bedCache = {}
                            blacklistCache = {}
                        end
                        if pendingUpdate then updateBreakSpeed() end
                        task_wait(0.05) 
                    end
                end)
			else
				pcall(function() bedwars.BlockBreakController.blockBreaker:setCooldown(0.3) end)
				unregisterHitBlockPatch('FastBreak')
				currentBlock = nil
				lastHotbarSlot = nil
				bedCache, blacklistCache, cachedBlacklistLower = {}, {}, {}
			end
        end,
        Tooltip = 'mine faster'
    })
    
    Time = FastBreak:CreateSlider({
        Name = 'Break speed',
        Min = 0, Max = 0.3, Default = 0.25, Decimal = 100, Suffix = 'seconds',
        Function = function() updateBreakSpeed() end
    })
    
    BedCheck = FastBreak:CreateToggle({
        Name = 'Bed Check',
        Default = false,
        Tooltip = 'mining is normal when breaking beds',
        Function = function() bedCache = {}; updateBreakSpeed() end
    })
    
    Blacklist = FastBreak:CreateToggle({
        Name = 'Blacklist Blocks',
        Default = false,
        Tooltip = 'mining is normal for blacklisted blocks',
        Function = function(v)
            if blocks then blocks.Object.Visible = v end
            blacklistCache = {}
            if v then updateBlacklistCache() end
            updateBreakSpeed()
        end
    })
    
    blocks = FastBreak:CreateTextList({
        Name = 'Blacklisted Blocks',
        Placeholder = 'bed',
        Visible = false,
        Function = function()
            updateBlacklistCache()
            blacklistCache = {}
            updateBreakSpeed()
        end
    })
end)

run(function()
    local Value
    local VerticalValue
    local WallCheck
    local PopBalloons
    local TP
    local lastonground = false
    local MobileButtons
    local FlyAnywayProgressBar = {Enabled = false}
    local FlyAnywayProgressBarFrame
    local BarColor
    local rayCheck = RaycastParams.new()
    rayCheck.RespectCanCollide = true
    local up, down, old = 0, 0
    local mobileControls = {}
    local groundtime = nil
    local onground = false
    local flyCooldownActive = false
    local lastGroundTouchTime = 0
    local MAX_FLY_TIME = 2.5
    local tick = tick
    local task_wait = task.wait
    local math_max = math.max
    local math_floor = math.floor
    local string_format = string.format
    local vector3new = Vector3.new
    local vector3zero = Vector3.zero
    local udim2new = UDim2.new
    local cframeLookAlong = CFrame.lookAlong
    local cachedBalloonCount = 0
    local lastBalloonCheck = 0
    local balloonCheckInterval = 0.2 
    local cachedMatchState = 0
    local lastMatchStateCheck = 0
    local lastGroundTime = tick()
    local airTime = 0
    
    local function createMobileButton(name, position, icon)
        local button = Instance.new("TextButton")
        button.Name = name
        button.Size = udim2new(0, 60, 0, 60)
        button.Position = position
        button.BackgroundTransparency = 0.2
        button.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        button.BorderSizePixel = 0
        button.Text = icon
        button.TextScaled = true
        button.TextColor3 = Color3.fromRGB(255, 255, 255)
        button.Font = Enum.Font.SourceSansBold
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 8)
        corner.Parent = button
        return button
    end

    local function cleanupMobileControls()
        for _, control in pairs(mobileControls) do
            if control then
                control:Destroy()
            end
        end
        mobileControls = {}
    end

    local progressBarFrameCounter = 0
    local MAX_FRAME_COUNTER = 600
    local function updateProgressBar()
        if not FlyAnywayProgressBarFrame then return end

        if (TP and TP.Enabled) or not entitylib.isAlive then
            FlyAnywayProgressBarFrame.Visible = false
            return
        end
        
        local now = tick()
        if now - lastBalloonCheck > balloonCheckInterval then
            lastBalloonCheck = now
            cachedBalloonCount = lplr.Character:GetAttribute('InflatedBalloons') or 0
            cachedMatchState = store.matchState
        end
        
        local flyAllowed = cachedBalloonCount > 0 or cachedMatchState == 2
        
        if flyAllowed then
            FlyAnywayProgressBarFrame.Frame.Size = udim2new(1, 0, 0, 20)
            FlyAnywayProgressBarFrame.TextLabel.Text = "∞"
            FlyAnywayProgressBarFrame.Visible = FlyAnywayProgressBar.Enabled
            return
        end
        
        progressBarFrameCounter = (progressBarFrameCounter + 1) % MAX_FRAME_COUNTER
        if progressBarFrameCounter % 3 == 0 then
            local hipHeight = entitylib.character.Humanoid.HipHeight
            local checkPos = entitylib.character.HumanoidRootPart.Position + vector3new(0, (hipHeight * -2) - 1, 0)
            local newray = getPlacedBlock(checkPos)
            onground = newray ~= nil
        end
        
        if onground then
            groundtime = nil
            flyCooldownActive = false
            lastGroundTouchTime = now
            
            FlyAnywayProgressBarFrame.Frame.Size = udim2new(1, 0, 0, 20)
            FlyAnywayProgressBarFrame.TextLabel.Text = string_format("%.1fs", MAX_FLY_TIME)
            FlyAnywayProgressBarFrame.Visible = FlyAnywayProgressBar.Enabled and Fly.Enabled
            
            local tween = FlyAnywayProgressBarFrame.Frame:FindFirstChild("Tween")
            if tween then
                tween:Destroy()
            end
        else
            if not groundtime then
                groundtime = now + MAX_FLY_TIME
                flyCooldownActive = false
            end
            
            local timeLeft = math_max(0, groundtime - now)
            local progress = timeLeft / MAX_FLY_TIME
            
            FlyAnywayProgressBarFrame.Frame.Size = udim2new(progress, 0, 0, 20)
            FlyAnywayProgressBarFrame.TextLabel.Text = string_format("%.1fs", timeLeft)
            FlyAnywayProgressBarFrame.Visible = FlyAnywayProgressBar.Enabled and Fly.Enabled
            
            if timeLeft <= 0 and not flyCooldownActive then
                flyCooldownActive = true
            end
        end
        
        lastonground = onground
    end

    Fly = vape.Categories.Blatant:CreateModule({
        Name = 'Fly',
        Function = function(callback)
            frictionTable.Fly = callback or nil
            updateVelocity()
            if callback then
                up, down, old = 0, 0, bedwars.BalloonController.deflateBalloon
                bedwars.BalloonController.deflateBalloon = function() end
                local tpTick, tpToggle, oldy = tick(), true

                if lplr.Character and (lplr.Character:GetAttribute('InflatedBalloons') or 0) == 0 and getItem('balloon') then
                    bedwars.BalloonController:inflateBalloon()
                end

                Fly:Clean(vapeEvents.AttributeChanged.Event:Connect(function(changed)
                    if changed == 'InflatedBalloons' then
                        local char = lplr.Character
                        if not char then return end
                        cachedBalloonCount = char:GetAttribute('InflatedBalloons') or 0
                        if cachedBalloonCount == 0 and getItem('balloon') then
                            bedwars.BalloonController:inflateBalloon()
                        end
                    end
                end))

                local renderFrameCounter = 0
                Fly:Clean(runService.RenderStepped:Connect(function(delta)
                    if FlyAnywayProgressBar.Enabled and Fly.Enabled then
                        renderFrameCounter = renderFrameCounter + 1
                        if renderFrameCounter % 2 == 0 then
                            updateProgressBar()
                        end
                    end
                end))

                local preSimFrameCounter = 0
                local lastWallRaycast = 0
                local wallRaycastInterval = 0.05
                
                Fly:Clean(runService.PreSimulation:Connect(function(dt)
                    if entitylib.isAlive and isnetworkowner(entitylib.character.RootPart) then
                        preSimFrameCounter = preSimFrameCounter + 1
                        local now = tick()
                        
                        if preSimFrameCounter % 12 == 0 then
                            cachedBalloonCount = lplr.Character and lplr.Character:GetAttribute('InflatedBalloons') or 0
                            cachedMatchState = store.matchState
                        end

                        local humanoid = entitylib.character.Humanoid
                        if humanoid.FloorMaterial ~= Enum.Material.Air then
                            lastGroundTime = now
                        end
                        airTime = now - lastGroundTime
                        
                        local flyAllowed = cachedBalloonCount > 0 or cachedMatchState == 2
                        
                        local oscillation = (now % 0.4 < 0.2) and -1 or 1
                        local mass = (1.95 + (flyAllowed and 6 or 0) * oscillation) + ((up + down) * VerticalValue.Value)
                        
                        local root = entitylib.character.RootPart
                        local moveDirection = entitylib.character.Humanoid.MoveDirection
                        local velo = getSpeed()
                        local destination = (moveDirection * math_max(Value.Value - velo, 0) * dt)
                        
                        if WallCheck.Enabled and (now - lastWallRaycast) > wallRaycastInterval then
                            lastWallRaycast = now
                            local filterList = {lplr.Character, gameCamera}
                            if AntiVoidPart then table.insert(filterList, AntiVoidPart) end
                            rayCheck.FilterDescendantsInstances = filterList
                            rayCheck.CollisionGroup = root.CollisionGroup

                            if destination.Magnitude > 0.001 then
                                local ray = workspace:Raycast(root.Position, destination, rayCheck)
                                if ray then
                                    destination = ((ray.Position + ray.Normal) - root.Position)
                                end
                            end
                        end

                        if not flyAllowed then
                            if tpToggle then
                                if airTime > 2 then  
                                    if not oldy then
                                        rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera, AntiVoidPart}
                                        rayCheck.CollisionGroup = root.CollisionGroup
                                        local ray = workspace:Raycast(root.Position, vector3new(0, -1000, 0), rayCheck)
                                        if ray and TP.Enabled then
                                            tpToggle = false
                                            oldy = root.Position.Y
                                            tpTick = now + 0.11
                                            root.CFrame = cframeLookAlong(vector3new(root.Position.X, ray.Position.Y + entitylib.character.HipHeight, root.Position.Z), root.CFrame.LookVector)
                                        end
                                    end
                                end
                            else
                                if oldy then
                                    if tpTick < now then
                                        local newpos = vector3new(root.Position.X, oldy, root.Position.Z)
                                        root.CFrame = cframeLookAlong(newpos, root.CFrame.LookVector)
                                        tpToggle = true
                                        oldy = nil
                                    else
                                        mass = 0
                                    end
                                end
                            end
                        end

                        root.CFrame += destination
                        root.AssemblyLinearVelocity = (moveDirection * velo) + vector3new(0, mass, 0)
                    end
                end))

                local isMobile = inputService.TouchEnabled and not inputService.KeyboardEnabled and not inputService.MouseEnabled
                local MobileEnabled = MobileButtons.Enabled or isMobile
                if MobileEnabled then
                    local gui = Instance.new("ScreenGui")
                    gui.Name = "FlyControls"
                    gui.ResetOnSpawn = false
                    gui.Parent = lplr.PlayerGui

                    local upButton = createMobileButton("UpButton", udim2new(0.9, -70, 0.7, -140), "↑")
                    local downButton = createMobileButton("DownButton", udim2new(0.9, -70, 0.7, -70), "↓")

                    mobileControls.UpButton = upButton
                    mobileControls.DownButton = downButton
                    mobileControls.ScreenGui = gui

                    upButton.Parent = gui
                    downButton.Parent = gui

                    Fly:Clean(upButton.MouseButton1Down:Connect(function()
                        up = 1
                    end))
                    Fly:Clean(upButton.MouseButton1Up:Connect(function()
                        up = 0
                    end))
                    Fly:Clean(downButton.MouseButton1Down:Connect(function()
                        down = -1
                    end))
                    Fly:Clean(downButton.MouseButton1Up:Connect(function()
                        down = 0
                    end))
                end

                Fly:Clean(inputService.InputBegan:Connect(function(input)
                    if not inputService:GetFocusedTextBox() then
                        if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
                            up = 1
                        elseif input.KeyCode == Enum.KeyCode.LeftShift or input.KeyCode == Enum.KeyCode.ButtonL2 then
                            down = -1
                        end
                    end
                end))
                Fly:Clean(inputService.InputEnded:Connect(function(input)
                    if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.ButtonA then
                        up = 0
                    elseif input.KeyCode == Enum.KeyCode.LeftShift or input.KeyCode == Enum.KeyCode.ButtonL2 then
                        down = 0
                    end
                end))
                if inputService.TouchEnabled then
                    pcall(function()
                        local jumpButton = lplr.PlayerGui.TouchGui.TouchControlFrame.JumpButton
                        Fly:Clean(jumpButton:GetPropertyChangedSignal('ImageRectOffset'):Connect(function()
                            if not mobileControls.UpButton then
                                up = jumpButton.ImageRectOffset.X == 146 and 1 or 0
                            end
                        end))
                    end)
                end
            else
                if FlyAnywayProgressBarFrame then
                    FlyAnywayProgressBarFrame.Visible = false
                end
                lastonground = nil
                groundtime = nil
                flyCooldownActive = false
                bedwars.BalloonController.deflateBalloon = old
                if PopBalloons.Enabled and entitylib.isAlive and (lplr.Character:GetAttribute('InflatedBalloons') or 0) > 0 then
                    for _ = 1, 3 do
                        bedwars.BalloonController:deflateBalloon()
                    end
                end
                cleanupMobileControls()
                cachedBalloonCount = 0
                lastBalloonCheck = 0
                cachedMatchState = 0
            end
        end,
        ExtraText = function()
            return 'Heatseeker'
        end,
        Tooltip = 'makes you go zoom!'
    })
    Value = Fly:CreateSlider({
        Name = 'Speed',
        Min = 1,
        Max = 23,
        Default = 23,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    VerticalValue = Fly:CreateSlider({
        Name = 'Vertical Speed',
        Min = 1,
        Max = 150,
        Default = 50,
        Suffix = function(val)
            return val == 1 and 'stud' or 'studs'
        end
    })
    WallCheck = Fly:CreateToggle({
        Name = 'Wall Check',
        Default = true
    })
    PopBalloons = Fly:CreateToggle({
        Name = 'Pop Balloons',
        Default = true
    })
    FlyAnywayProgressBar = Fly:CreateToggle({
        Name = "Progress Bar",
        Function = function(callback)
            if BarColor and BarColor.Object then
                BarColor.Object.Visible = callback
            end
            if callback then
                FlyAnywayProgressBarFrame = Instance.new("Frame")
                FlyAnywayProgressBarFrame.AnchorPoint = Vector2.new(0.5, 0)
                FlyAnywayProgressBarFrame.Position = udim2new(0.5, 0, 1, -200)
                FlyAnywayProgressBarFrame.Size = udim2new(0.2, 0, 0, 20)
                FlyAnywayProgressBarFrame.BackgroundTransparency = 0.5
                FlyAnywayProgressBarFrame.BorderSizePixel = 0
                FlyAnywayProgressBarFrame.BackgroundColor3 = Color3.new(0, 0, 0)
                FlyAnywayProgressBarFrame.Visible = false
                FlyAnywayProgressBarFrame.Parent = vape.gui
                
                local FlyAnywayProgressBarFrame2 = Instance.new("Frame")
                FlyAnywayProgressBarFrame2.Name = "Frame"
                FlyAnywayProgressBarFrame2.AnchorPoint = Vector2.new(0, 0)
                FlyAnywayProgressBarFrame2.Position = udim2new(0, 0, 0, 0)
                FlyAnywayProgressBarFrame2.Size = udim2new(1, 0, 0, 20)
                FlyAnywayProgressBarFrame2.BackgroundTransparency = 0
                FlyAnywayProgressBarFrame2.BorderSizePixel = 0
                FlyAnywayProgressBarFrame2.BackgroundColor3 = BarColor and Color3.fromHSV(BarColor.H, BarColor.S, BarColor.V) or Color3.fromHSV(vape.GUIColor.Hue, vape.GUIColor.Sat, vape.GUIColor.Value)
                FlyAnywayProgressBarFrame2.Visible = true
                FlyAnywayProgressBarFrame2.Parent = FlyAnywayProgressBarFrame
                
                local FlyAnywayProgressBartext = Instance.new("TextLabel")
                FlyAnywayProgressBartext.Name = "TextLabel"
                FlyAnywayProgressBartext.Text = "2.5s"
                FlyAnywayProgressBartext.Font = Enum.Font.Gotham
                FlyAnywayProgressBartext.TextStrokeTransparency = 0
                FlyAnywayProgressBartext.TextColor3 = Color3.new(0.9, 0.9, 0.9)
                FlyAnywayProgressBartext.TextSize = 20
                FlyAnywayProgressBartext.Size = udim2new(1, 0, 1, 0)
                FlyAnywayProgressBartext.BackgroundTransparency = 1
                FlyAnywayProgressBartext.Position = udim2new(0, 0, 0, 0)
                FlyAnywayProgressBartext.Parent = FlyAnywayProgressBarFrame
            else
                if FlyAnywayProgressBarFrame then 
                    FlyAnywayProgressBarFrame:Destroy() 
                    FlyAnywayProgressBarFrame = nil 
                end
            end
        end,
        Tooltip = "show amount of time for fly",
        Default = true
    })
    BarColor = Fly:CreateColorSlider({
        Name = 'Bar Color',
        Darker = true,
        Visible = false,
        Function = function(h, s, v, o)
            if FlyAnywayProgressBarFrame then
                FlyAnywayProgressBarFrame:FindFirstChild('Frame').BackgroundColor3 = Color3.fromHSV(h, s, v)
                FlyAnywayProgressBarFrame:FindFirstChild('Frame').BackgroundTransparency = 1 - o
            end
        end
    })

    TP = Fly:CreateToggle({
        Name = 'TP Down',
        Default = true,
        Function = function(callback)
            if callback and FlyAnywayProgressBarFrame then
                FlyAnywayProgressBarFrame.Visible = false
            end
        end
    })
    MobileButtons = Fly:CreateToggle({
        Name = "Mobile Buttons",
        Visible = false,
        Tooltip = 'puts up n down buttons on ur screen gng',
        Function = function() 
            if Fly.Enabled then
                Fly:Toggle()
                Fly:Toggle()
            end
        end
    })

    task.defer(function()
        if BarColor and BarColor.Object then
            BarColor.Object.Visible = FlyAnywayProgressBar.Enabled
        end
        if MobileButtons and MobileButtons.Object then
            MobileButtons.Object.Visible = inputService.TouchEnabled
        end
    end)
end)

run(function()
	local NoSlowDown
    local old
    local SophiaCheck
    local FROZEN_THRESHOLD = 10
    local cachedModifier = nil
    local nsHooked = false
    local savedSlow = setmetatable({}, {__mode = 'k'})
    local origPunch = nil
    local origGroveDisable = nil

    local function hookKitNoSlow()
        if bedwars.DragonSlayerController and not origPunch then
            origPunch = bedwars.DragonSlayerController.playPunchAnimation
            bedwars.DragonSlayerController.playPunchAnimation = function(self, arg2)
                local ok, maid = pcall(function()
                    local imp = debug.getupvalue(origPunch, 1)
                    local anim = debug.getupvalue(origPunch, 2)
                    local plrs = debug.getupvalue(origPunch, 3)
                    local atype = debug.getupvalue(origPunch, 4)
                    local rs = debug.getupvalue(origPunch, 6)
                    local m = imp.new()
                    local track = anim:playAnimation(plrs.LocalPlayer, atype.DRAGON_SLAYER_PUNCH)
                    m:GiveTask(function()
                        if track then track:Stop() end
                    end)
                    m:GiveTask(rs.Heartbeat:Connect(function()
                        local char = plrs.LocalPlayer.Character
                        if not char or not char.PrimaryPart then
                            m:DoCleaning()
                            return
                        end
                        char:PivotTo(CFrame.new(char:GetPrimaryPartCFrame().Position) * arg2)
                    end))
                    task.delay(0.46, function() m:DoCleaning() end)
                    return m
                end)
                if ok and maid then return maid end
                return origPunch(self, arg2)
            end
        end

        if bedwars.SpiritGardenerController and not origGroveDisable then
            origGroveDisable = bedwars.SpiritGardenerController.disableActionsOnCharge
            bedwars.SpiritGardenerController.disableActionsOnCharge = function(self, maid, character)
                if character ~= lplr.Character then
                    return origGroveDisable(self, maid, character)
                end
                local ok = pcall(function()
                    local KnitClient = bedwars.KnitClient
                    KnitClient.Controllers.SwordController:toggleSwordSwing(true)
                    KnitClient.Controllers.BlockPlacementController:disableBlockPlacer()
                    local ClientSyncEvents = debug.getupvalue(origGroveDisable, 3)
                    local projConn = ClientSyncEvents.BeginProjectileTargeting:connect(function(event)
                        event:setCancelled(true)
                    end)
                    local jumpMod = KnitClient.Controllers.JumpHeightController:getJumpModifier():addModifier({
                        jumpHeightMultiplier = 0
                    })
                    maid:GiveTask(function()
                        KnitClient.Controllers.SwordController:toggleSwordSwing(false)
                        KnitClient.Controllers.BlockPlacementController:enableBlockPlacer()
                        projConn:Destroy()
                        jumpMod.Destroy()
                    end)
                end)
                if not ok then
                    return origGroveDisable(self, maid, character)
                end
            end
        end
    end

    local function unhookKitNoSlow()
        if origPunch and bedwars.DragonSlayerController then
            bedwars.DragonSlayerController.playPunchAnimation = origPunch
        end
        origPunch = nil
        if origGroveDisable and bedwars.SpiritGardenerController then
            bedwars.SpiritGardenerController.disableActionsOnCharge = origGroveDisable
        end
        origGroveDisable = nil
    end
    NoSlowdown = vape.Categories.Blatant:CreateModule({
        Name = 'NoSlowdown',
        Function = function(callback)
            if not cachedModifier then
                if not bedwars.SprintController then return end
                cachedModifier = bedwars.SprintController:getMovementStatusModifier()
            end
            local modifier = cachedModifier
            if callback then
                if nsHooked then return end
                hookKitNoSlow()
                old = modifier.addModifier
                if not old then return end
                local orig = old

                local function removeSlow(tab)
                    if type(tab) ~= 'table' then
                        return false, false
                    end

                    local changed = false
                    local unblocked = false

                    if not savedSlow[tab] then
                        savedSlow[tab] = {
                            move = tab.moveSpeedMultiplier,
                            constant = tab.constantSpeedMultiplier,
                            blockSprint = tab.blockSprint
                        }
                    end

                    local move = tonumber(tab.moveSpeedMultiplier)
                    local constant = tonumber(tab.constantSpeedMultiplier)

                    if move and move < 1 then
                        tab.moveSpeedMultiplier = 1
                        changed = true
                    end

                    if constant and constant < 1 then
                        tab.constantSpeedMultiplier = 1
                        changed = true
                    end

                    if tab.blockSprint == true and not (constant and constant > 1) then
                        tab.blockSprint = false
                        changed = true
                        unblocked = true
                    end

                    return changed, unblocked
                end

                nsHooked = true
                modifier.addModifier = function(self, tab)
                    if not orig then return end

                    if SophiaCheck and SophiaCheck.Enabled and isFrozen(nil, FROZEN_THRESHOLD) then
                        return orig(self, tab)
                    end

                    removeSlow(tab)
                    return orig(self, tab)
                end

                local changed = false
                local unblocked = false

                for i, v in modifier.modifiers do
                    local mod = type(v) == 'table' and v or (type(i) == 'table' and i or nil)

                    if mod then
                        local didChange, didUnblock = removeSlow(mod)

                        if didChange then
                            changed = true
                        end

                        if didUnblock then
                            unblocked = true
                        end
                    end
                end

                if changed and modifier.updateModifiers then
                    modifier:updateModifiers()
                end

                if unblocked
                    and entitylib.isAlive
                    and entitylib.character.Humanoid.MoveDirection.Magnitude > 0 then

                    pcall(function()
                        bedwars.SprintController:startSprinting()
                    end)
                end

                NoSlowdown:Clean(runService.PreSimulation:Connect(function()
                    if not NoSlowdown.Enabled or not cachedModifier then
                        return
                    end

                    if SophiaCheck and SophiaCheck.Enabled and isFrozen(nil, FROZEN_THRESHOLD) then
                        return
                    end

                    local updated = false
                    local resumeSprint = false

                    for i, v in cachedModifier.modifiers do
                        local mod = type(v) == 'table' and v or (type(i) == 'table' and i or nil)

                        if mod then
                            local didChange, didUnblock = removeSlow(mod)

                            if didChange then
                                updated = true
                            end

                            if didUnblock then
                                resumeSprint = true
                            end
                        end
                    end

                    if updated and cachedModifier.updateModifiers then
                        cachedModifier:updateModifiers()
                    end

                    if resumeSprint
                        and entitylib.isAlive
                        and entitylib.character.Humanoid.MoveDirection.Magnitude > 0 then

                        pcall(function()
                            bedwars.SprintController:startSprinting()
                        end)
                    end
                end))
            else
                unhookKitNoSlow()
                if cachedModifier then
                    cachedModifier.addModifier = old
                    for tab, orig in savedSlow do
                        tab.moveSpeedMultiplier = orig.move
                        tab.constantSpeedMultiplier = orig.constant
                        tab.blockSprint = orig.blockSprint
                    end
                    if cachedModifier.updateModifiers then
                        pcall(cachedModifier.updateModifiers, cachedModifier)
                    end
                    cachedModifier = nil
                end
                table.clear(savedSlow)
                old = nil
                nsHooked = false
            end
        end,
        Tooltip = 'prevents slowing down when using items.'
    })

    SophiaCheck = NoSlowdown:CreateToggle({
        Name = 'Sophia Check',
        Default = false
    })
end)

run(function()
	local ProjectileAimbot
	local Targets
	local Sort
	local PartOption
	local FOV
	local Distance
	local CircleColor
	local CircleTransparency
	local CircleThickness
	local CircleFilled
	local CircleObject
	local Horizontal
	local Vertical
	local AutoCharge
	local Aim
	local OtherProjectiles
	local UseUmeko
	local Potions
	local Blacklist
	local MiloCheck
	local Old, Hook
	local ArcCheck = RaycastParams.new()
	ArcCheck.FilterType = Enum.RaycastFilterType.Include

	local TargetLimbs = {
		Torso = {'UpperTorso', 'LowerTorso'},
		['Left arm'] = {'LeftUpperArm', 'LeftLowerArm', 'LeftHand'},
		['Right arm'] = {'RightUpperArm', 'RightLowerArm', 'RightHand'},
		['Left leg'] = {'LeftUpperLeg', 'LeftLowerLeg', 'LeftFoot'},
		['Right leg'] = {'RightUpperLeg', 'RightLowerLeg', 'RightFoot'}
	}
	local LimbOrder = {'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg'}
	local RandomLimb = setmetatable({}, {__mode = 'k'})

	local function IsHeadshotProjectile(itemType)
		if not itemType then return false end
		local lower = tostring(itemType):lower()
		if lower:find('headhunter', 1, true) or lower:find('tactical', 1, true) then
			return true
		end
		return store.equippedKit == 'archer'
	end

	local function IsDisguised(Ent)
		if not Ent.Player then return false end
		return workspace:FindFirstChild('DisguisedPlayerBlock_' .. Ent.Player.UserId) ~= nil
	end

	local function GetTargetPart(Ent, Mode)
		if Mode == 'Random' and Ent.Character then
			local Pick = RandomLimb[Ent.Character]
			if not Pick or tick() > Pick.Clock then
				Pick = {Value = LimbOrder[math.random(1, #LimbOrder)], Clock = tick() + 1}
				RandomLimb[Ent.Character] = Pick
			end
			Mode = Pick.Value
		end

		if Mode == 'Head' then
			return (Ent.Character and Ent.Character:FindFirstChild('Head')) or Ent.Head or Ent.RootPart
		end

		local Limbs = TargetLimbs[Mode]
		if Limbs and Ent.Character then
			for _, v in Limbs do
				local Part = Ent.Character:FindFirstChild(v)
				if Part then
					return Part
				end
			end
		end

		return Ent.RootPart
	end

	local function GetMouseOrigin()
		if inputService.TouchEnabled then
			return gameCamera.ViewportSize / 2
		end
		return inputService:GetMouseLocation()
	end

	-- Some builds never run the launch method for a shot, so the outgoing packet is
	-- redirected as well. Only the direction is replaced: the speed, spawn position and
	-- draw the game computed stay untouched, which is the shot the server accepts.
	local paDebugAt = {}

	local function paLog(tag, text)
		if not PADebug or not PADebug.Enabled then
			return
		end
		local now = tick()
		if now - (paDebugAt[tag] or 0) < 0.5 then
			return
		end
		paDebugAt[tag] = now
		print('[ProjectileAimbot] ' .. tostring(text))
	end

	local function paSolve(Tool, ProjectileName, PositionFrom, NativeVelocity)
		if not ProjectileAimbot or not ProjectileAimbot.Enabled then
			return nil
		end
		if typeof(PositionFrom) ~= 'Vector3' or typeof(NativeVelocity) ~= 'Vector3' or type(ProjectileName) ~= 'string' then
			return nil
		end
		if ProjectileName:find('splash_potion', 1, true) then
			if not Potions.Enabled then
				return nil
			end
		elseif not OtherProjectiles.Enabled and not ProjectileName:find('arrow', 1, true)
			and not (UseUmeko.Enabled and ProjectileName:find('^ninja_chakram')) then
			return nil
		end
		local BlacklistName = (ProjectileName == 'glue_trap' or ProjectileName == 'glue_projectile') and 'gloop' or ProjectileName
		if table.find(Blacklist.ListEnabled or {}, BlacklistName) then
			return nil
		end
		local ProjectileMeta = bedwars.ProjectileMeta and bedwars.ProjectileMeta[ProjectileName]
		if type(ProjectileMeta) ~= 'table' then
			return nil
		end
		local Speed = NativeVelocity.Magnitude
		if Speed <= 0.001 or Speed > 10000 then
			return nil
		end
		local Gravity = tonumber(ProjectileMeta.gravitationalAcceleration) or 196.2
		if Gravity < 1 then Gravity = 0 end
		local Lifetime = tonumber(ProjectileMeta.predictionLifetimeSec) or tonumber(ProjectileMeta.lifetimeSec) or 3
		local BowConstants = bedwars.BowConstantsTable or {}
		local RelX, RelY, RelZ = BowConstants.RelX or 0.8, BowConstants.RelY or -0.6, BowConstants.RelZ or 0
		local ToolMeta = Tool and bedwars.ItemMeta and bedwars.ItemMeta[Tool.Name]
		local SourceMeta = ToolMeta and ToolMeta.projectileSource
		local Relative = SourceMeta and SourceMeta.relativeOverride
		if type(Relative) == 'table' then
			RelX, RelY, RelZ = Relative.relX or 0, Relative.relY or 0, Relative.relZ or 0
		end
		local map = workspace:FindFirstChild('Map')
		if map then
			ArcCheck.FilterDescendantsInstances = {map}
		end
		local PartName = PartOption.Value == 'Dynamic' and (IsHeadshotProjectile(Tool and Tool.Name) and 'Head' or 'RootPart') or PartOption.Value

		local function Solve(Ent)
			if not Ent.Character or not Ent.RootPart then
				return nil
			end
			local Balloons = Ent.Character:GetAttribute('InflatedBalloons')
			local PlayerGravity = workspace.Gravity
			if Balloons and Balloons > 0 then
				PlayerGravity = balloonGravity(Balloons, Ent.Character)
			end
			if Ent.Character.PrimaryPart and Ent.Character.PrimaryPart:FindFirstChild('rbxassetid://8200754399') then
				PlayerGravity = 6
			end
			if Ent.Player and Ent.Player:GetAttribute('IsOwlTarget') then
				for _, v in collectionService:GetTagged('Owl') do
					if v:GetAttribute('Target') == Ent.Player.UserId and v:GetAttribute('Status') == 2 then
						PlayerGravity = 0
						break
					end
				end
			end

			local AimPart = GetTargetPart(Ent, PartName)
			local Velocity = Ent.RootPart.AssemblyLinearVelocity or Vector3.zero
			if Horizontal.Value ~= 1 or Vertical.Value ~= 1 then
				Velocity = Vector3.new(Velocity.X * Horizontal.Value, Velocity.Y * Vertical.Value, Velocity.Z * Horizontal.Value)
			end
			local Airborne = (Ent.Humanoid and Ent.Humanoid.FloorMaterial == Enum.Material.Air) or math.abs(Velocity.Y) > 0.01
			local JumpVelocity = Ent.Jumping and 42.6 or nil
			local AimTarget = AimPart.Position

			local calc, flight
			calc, _, flight = prediction.SolveTrajectory(
				PositionFrom, Speed, Gravity,
				AimTarget, Velocity,
				PlayerGravity, Ent.HipHeight, JumpVelocity,
				ArcCheck, Airborne,
				Ent.RootPart.Position, Ent.RootPart,
				nil, true
			)
			for _ = 1, 2 do
				if not calc or not flight then break end
				local Spawn = prediction.GetSpawnPosition(PositionFrom, calc, RelX, RelY, RelZ)
				local corrected, _, correctedTime = prediction.SolveTrajectory(
					Spawn, Speed, Gravity,
					AimTarget, Velocity,
					PlayerGravity, Ent.HipHeight, JumpVelocity,
					ArcCheck, Airborne,
					Ent.RootPart.Position, Ent.RootPart,
					nil, true
				)
				if not corrected or not correctedTime then break end
				calc = PositionFrom + (corrected - Spawn)
				flight = correctedTime
			end
			if not calc or not flight or flight > Lifetime then
				return nil
			end

			if Targets.Walls.Enabled then
				local Spawn = prediction.GetSpawnPosition(PositionFrom, calc, RelX, RelY, RelZ)
				if not prediction.IsTrajectoryClear(Spawn, (calc - PositionFrom).Unit * Speed, Gravity, flight * 0.97, ArcCheck) then
					return nil
				end
			end

			return CFrame.lookAt(PositionFrom, calc).LookVector * Speed
		end

		local Value, Attempts, Started = nil, 0, os.clock()
		local Ent = entitylib.EntityMouse({
			Part = 'RootPart',
			Range = FOV.Value,
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs and Targets.NPCs.Enabled or false,
			Wallcheck = Targets.Walls.Enabled or nil,
			Origin = PositionFrom,
			MouseOrigin = GetMouseOrigin(),
			Sort = sortmethods[Sort.Value],
			Check = function(Candidate)
				if MiloCheck.Enabled and IsDisguised(Candidate) then
					return false
				end
				local MyRoot = entitylib.character and entitylib.character.RootPart
				if MyRoot and (Candidate.RootPart.Position - MyRoot.Position).Magnitude > Distance.Value then
					return false
				end
				if Attempts >= 10 or (Attempts > 0 and (os.clock() - Started) > 0.0015) then
					return false
				end
				Attempts += 1
				Value = Solve(Candidate)
				return Value ~= nil
			end
		})

		if (not Ent or not Value) then
			-- Point blank the root part drops below the viewport and the cursor pass skips the
			-- enemy; take the nearest body in front of the camera instead.
			local MyRoot = entitylib.character and entitylib.character.RootPart
			local look = gameCamera.CFrame.LookVector
			local MaxClose = math.min(Distance.Value or 24, 24)
			local candidates = {}
			for _, candidate in entitylib.List do
				if candidate.Player and not Targets.Players.Enabled then continue end
				if candidate.NPC and not (Targets.NPCs and Targets.NPCs.Enabled) then continue end
				if not candidate.Targetable or not candidate.RootPart or not candidate.Character then continue end
				if not entitylib.isVulnerable(candidate) then continue end
				if MiloCheck.Enabled and IsDisguised(candidate) then continue end
				local delta = candidate.RootPart.Position - PositionFrom
				local dist3 = delta.Magnitude
				if dist3 > MaxClose or dist3 < 0.01 then continue end
				if look:Dot(delta.Unit) < 0.15 then continue end
				if MyRoot and (candidate.RootPart.Position - MyRoot.Position).Magnitude > Distance.Value then continue end
				table.insert(candidates, {ent = candidate, dist = dist3})
			end
			table.sort(candidates, function(a, b)
				return a.dist < b.dist
			end)
			for i = 1, math.min(#candidates, 5) do
				local candidate = candidates[i].ent
				if not Targets.Walls.Enabled or not entitylib.Wallcheck(PositionFrom, candidate.RootPart.Position, Targets.Walls.Enabled, candidate) then
					local solved = Solve(candidate)
					if solved then
						Ent, Value = candidate, solved
						break
					end
				end
			end
		end

		if Ent and Value then
			if targetinfo and targetinfo.Targets then
				targetinfo.Targets[Ent] = tick() + 1
			end
			return Value
		end
	end

	vape.Libraries.projectileaim.Solvers.ProjectileAimbot = function(args)
		return paSolve(args[1], args[3], args[4], args[6])
	end

	ProjectileAimbot = vape.Categories.Blatant:CreateModule({
		Name = 'ProjectileAimbot',
		Function = function(callback)
			if not callback then
				local controller = bedwars.ProjectileController
				if Hook and controller and controller.calculateImportantLaunchValues == Hook then
					controller.calculateImportantLaunchValues = Old
				end
				Old, Hook = nil, nil
				if CircleObject then
					CircleObject.Visible = false
				end
				return
			end
			vape.Libraries.projectileaim.Install()

			if CircleObject then
				CircleObject.Visible = true
			end

			local function UpdateCircle()
				if CircleObject then
					CircleObject.Position = GetMouseOrigin()
				end
			end

			ProjectileAimbot:Clean(runService.RenderStepped:Connect(UpdateCircle))
			ProjectileAimbot:Clean(gameCamera:GetPropertyChangedSignal('ViewportSize'):Connect(function()
				UpdateCircle()
			end))

			local owlTagCache, owlTagAt = nil, 0
			local function getOwlTags()
				local now = tick()
				if not owlTagCache or now - owlTagAt > 0.5 then
					owlTagCache = collectionService:GetTagged('Owl')
					owlTagAt = now
				end
				return owlTagCache
			end

			local function AimLaunchValues(native, self, LaunchData, WorldMeta, Origin, ShootPosition)
				if type(native) ~= 'table' then return end

				local LaunchPosition = ShootPosition
				if typeof(LaunchPosition) ~= 'Vector3' then
					local ok, res = pcall(self.getLaunchPosition, self, Origin)
					if not (ok and typeof(res) == 'Vector3') then
						res = nil
					end
					if typeof(res) ~= 'Vector3' and entitylib.isAlive then
						res = entitylib.character.RootPart.Position + Vector3.new(0, 2, 0)
					end
					LaunchPosition = res
				end
				if typeof(LaunchPosition) ~= 'Vector3' then
					return nil
				end

				local ProjectileName = tostring(LaunchData.projectile or '')
				if ProjectileName:find('splash_potion', 1, true) then
					if not Potions.Enabled then
						return nil
					end
				elseif not OtherProjectiles.Enabled and not ProjectileName:find('arrow', 1, true) and not (UseUmeko.Enabled and ProjectileName:find('^ninja_chakram')) then
					return nil
				end

				local BlacklistName = (ProjectileName == 'glue_trap' or ProjectileName == 'glue_projectile') and 'gloop' or ProjectileName
				if table.find(Blacklist.ListEnabled or {}, BlacklistName) then
					return nil
				end

				local metaOk, metaRes = pcall(LaunchData.getProjectileMeta, LaunchData)
				local ProjectileMeta = metaOk and type(metaRes) == 'table' and metaRes or (bedwars.ProjectileMeta and bedwars.ProjectileMeta[ProjectileName])
				if not ProjectileMeta then
					return nil
				end

				local Lifetime = WorldMeta and (ProjectileMeta.predictionLifetimeSec or ProjectileMeta.lifetimeSec or 3) or (ProjectileMeta.lifetimeSec or 3)
				local Gravity = (native and tonumber(native.gravitationalAcceleration)) or ((tonumber(ProjectileMeta.gravitationalAcceleration) or 196.2) * (tonumber(LaunchData.gravityMultiplier) or 1))
				if Gravity < 1 then
					Gravity = 0
				end

				local Tool = store.hand and store.hand.tool
				local ToolMeta = Tool and bedwars.ItemMeta and bedwars.ItemMeta[Tool.Name]
				local SourceMeta = ToolMeta and ToolMeta.projectileSource
				local BaseSpeed = tonumber(ProjectileMeta.launchVelocity) or 100
				local NativeSpeed = native and typeof(native.initialVelocity) == 'Vector3' and native.initialVelocity.Magnitude or 0
				local NativeDraw = (native and tonumber(native.drawDurationSeconds)) or tonumber(LaunchData.drawDurationSeconds) or 0

				-- Bows scale with how long they were drawn. Crossbows and the other fixed-charge
				-- launchers (multiShotChargeTime plus a reload) have no strength charge, so handing
				-- the server a made-up draw and speed gets the arrow eaten. Keep every native value
				-- for those and only replace where we aim.
				local StrengthCharge = tonumber(SourceMeta and SourceMeta.maxStrengthChargeSec)
					or tonumber(SourceMeta and SourceMeta.maxDrawDurationSeconds)

				local ProjectileSpeed, DrawDuration
				if not StrengthCharge then
					if NativeSpeed <= 0 then
						return nil
					end
					ProjectileSpeed, DrawDuration = NativeSpeed, NativeDraw
				elseif AutoCharge.Enabled or not Aim.Enabled then
					ProjectileSpeed, DrawDuration = BaseSpeed, StrengthCharge
				else
					local MinScalar = tonumber(SourceMeta and SourceMeta.minStrengthScalar) or 1
					if NativeSpeed > 0 then
						ProjectileSpeed = NativeSpeed
					else
						local DrawPct = StrengthCharge > 0 and math.clamp(NativeDraw / StrengthCharge, 0, 1) or 0
						ProjectileSpeed = BaseSpeed * (MinScalar + (1 - MinScalar) * DrawPct)
					end
					DrawDuration = NativeDraw
				end
				if not ProjectileSpeed or ProjectileSpeed <= 0 then
					return nil
				end

				local SpawnOffset = ProjectileName == 'owl_projectile' and Vector3.zero or (typeof(LaunchData.fromPositionOffset) == 'Vector3' and LaunchData.fromPositionOffset or Vector3.zero)
				local OffsetPosition = (native and typeof(native.positionFrom) == 'Vector3' and native.positionFrom) or (LaunchPosition + SpawnOffset)

				local BowConstants = bedwars.BowConstantsTable or {}
				local Relative = SourceMeta and SourceMeta.relativeOverride
				local RelX, RelY, RelZ = BowConstants.RelX or 0.8, BowConstants.RelY or -0.6, BowConstants.RelZ or 0
				if type(Relative) == 'table' then
					RelX, RelY, RelZ = Relative.relX or 0, Relative.relY or 0, Relative.relZ or 0
				end

				local map = workspace:FindFirstChild('Map')
				if map then
					ArcCheck.FilterDescendantsInstances = {map}
				end

				local PartName = PartOption.Value == 'Dynamic' and (IsHeadshotProjectile(Tool and Tool.Name) and 'Head' or 'RootPart') or PartOption.Value

				local function GetLaunchValues(Ent)
					if not Ent.Character or not Ent.RootPart then
						return nil
					end

					local Balloons = Ent.Character:GetAttribute('InflatedBalloons')
					local PlayerGravity = workspace.Gravity

					if Balloons and Balloons > 0 then
						PlayerGravity = balloonGravity(Balloons, Ent.Character)
					end

					if Ent.Character.PrimaryPart and Ent.Character.PrimaryPart:FindFirstChild('rbxassetid://8200754399') then
						PlayerGravity = 6
					end

					if Ent.Player and Ent.Player:GetAttribute('IsOwlTarget') then
						for _, v in getOwlTags() do
							if v:GetAttribute('Target') == Ent.Player.UserId and v:GetAttribute('Status') == 2 then
								PlayerGravity = 0
								break
							end
						end
					end

					local AimPart = GetTargetPart(Ent, PartName)
					local Velocity = ProjectileName == 'telepearl' and Vector3.zero or AimPart.AssemblyLinearVelocity
					if Horizontal.Value ~= 1 or Vertical.Value ~= 1 then
						Velocity = Vector3.new(Velocity.X * Horizontal.Value, Velocity.Y * Vertical.Value, Velocity.Z * Horizontal.Value)
					end
					local EntRootVelocity = Ent.RootPart.AssemblyLinearVelocity
					local Airborne = (Ent.Humanoid and Ent.Humanoid.FloorMaterial == Enum.Material.Air) or math.abs(EntRootVelocity.Y) > 0.01
					local JumpVelocity = Ent.Jumping and 42.6 or nil
					local AimTarget = AimPart.Position

					-- The game spawns the projectile at the hand offset from positionFrom, not at
					-- positionFrom itself. Solve, move the origin to the real spawn point, re-solve,
					-- and shift the result back so the returned direction accounts for the offset.
					local calc, flight
					calc, _, flight = prediction.SolveTrajectory(
						OffsetPosition, ProjectileSpeed, Gravity,
						AimTarget, Velocity,
						PlayerGravity, Ent.HipHeight, JumpVelocity,
						ArcCheck, Airborne,
						Ent.RootPart.Position, Ent.RootPart,
						nil, true
					)
					for _ = 1, 2 do
						if not calc or not flight then break end
						local Spawn = prediction.GetSpawnPosition(OffsetPosition, calc, RelX, RelY, RelZ)
						local corrected, _, correctedTime = prediction.SolveTrajectory(
							Spawn, ProjectileSpeed, Gravity,
							AimTarget, Velocity,
							PlayerGravity, Ent.HipHeight, JumpVelocity,
							ArcCheck, Airborne,
							Ent.RootPart.Position, Ent.RootPart,
							nil, true
						)
						if not corrected or not correctedTime then break end
						calc = OffsetPosition + (corrected - Spawn)
						flight = correctedTime
					end

					if not calc or not flight or flight > Lifetime then
						return nil
					end

					local values = table.clone(native)
					values.initialVelocity = CFrame.lookAt(OffsetPosition, calc).LookVector * ProjectileSpeed
					values.drawDurationSeconds = DrawDuration
					return values
				end

				local Values, Attempts = nil, 0
				local Ent = entitylib.EntityMouse({
					Part = 'RootPart',
					Range = FOV.Value,
					Players = Targets.Players.Enabled,
					NPCs = Targets.NPCs and Targets.NPCs.Enabled or false,
					Wallcheck = Targets.Walls.Enabled or nil,
					Origin = entitylib.isAlive and (ShootPosition or entitylib.character.RootPart.Position) or Vector3.zero,
					MouseOrigin = GetMouseOrigin(),
					Sort = sortmethods[Sort.Value],
					Check = function(Candidate)
						if MiloCheck.Enabled and IsDisguised(Candidate) then
							return false
						end
						if (Candidate.RootPart.Position - entitylib.character.RootPart.Position).Magnitude > Distance.Value then
							return false
						end
						if Attempts >= 24 then
							return false
						end
						Attempts += 1
						Values = GetLaunchValues(Candidate)
						return Values ~= nil
					end
				})

				if Ent and Values then
					if targetinfo and targetinfo.Targets then
						targetinfo.Targets[Ent] = tick() + 1
					end
					return Values
				end
			end

			local hookErrorAt = 0
			Hook = function(self, LaunchData, WorldMeta, Origin, ShootPosition, ...)
				local native = Old(self, LaunchData, WorldMeta, Origin, ShootPosition, ...)
				if ProjectileAimbot.Enabled and not (vape.Modules.SilentAim and vape.Modules.SilentAim.Enabled) then
					local Success, Values = pcall(AimLaunchValues, native, self, LaunchData, WorldMeta, Origin, ShootPosition)
					if Success and Values then
						paLog('launch', 'launch values aimed: ' .. tostring(LaunchData and LaunchData.projectile))
						return Values
					end
					if not Success and (tick() - hookErrorAt) >= 3 then
						hookErrorAt = tick()
						warn('[ProjectileAimbot] ' .. tostring(Values))
					end
				end
				return native
			end

			-- A profile can enable this while bedwars is still loading, so keep trying for the
			-- controller instead of turning the module off on the first miss.
			local function installHook()
				local controller = bedwars.ProjectileController
				if not controller or type(controller.calculateImportantLaunchValues) ~= 'function' then
					return false
				end
				if controller.calculateImportantLaunchValues ~= Hook then
					Old = controller.calculateImportantLaunchValues
					controller.calculateImportantLaunchValues = Hook
				end
				return true
			end

			if not installHook() then
				task.spawn(function()
					local deadline = tick() + 20
					repeat
						task.wait(0.25)
						vape.Libraries.projectileaim.Install()
					until not ProjectileAimbot.Enabled or installHook() or tick() > deadline
				end)
			end
			-- The packet path works on its own; the launch hook only refines it when present.
			vape.Libraries.projectileaim.Install()
			if PADebug and PADebug.Enabled then
				task.delay(0.5, function()
					local text = 'launch ' .. tostring(Hook ~= nil)
						.. ' | packet ' .. tostring(vape.Libraries.projectileaim.Namecall ~= nil)
						.. ' | local ' .. tostring(vape.Libraries.projectileaim.Local ~= nil)
					paLog('install', text)
					-- The loader clears the console and notif() is a stub, so the GUI notification
					-- pane is the only channel that actually reaches the player.
					pcall(function() vape:CreateNotification('ProjectileAimbot', text, 8) end)
				end)
			end
		end,
		Tooltip = 'Silently adjusts your aim towards the enemy'
	})

	Targets = ProjectileAimbot:CreateTargets({
		Players = true,
		Walls = true
	})

	Sort = ProjectileAimbot:CreateDropdown({
		Name = 'Target mode',
		List = getSortList({'Distance'}),
		Default = 'Distance'
	})

	PartOption = ProjectileAimbot:CreateDropdown({
		Name = 'Part',
		List = {'RootPart', 'Head', 'Torso', 'Left arm', 'Right arm', 'Left leg', 'Right leg', 'Random', 'Dynamic'},
		Default = 'RootPart',
		Tooltip = 'Dynamic aims at the head with headshot-capable bows, including tactical bows and Archer, and at the body with everything else'
	})

	FOV = ProjectileAimbot:CreateSlider({
		Name = 'FOV',
		Min = 1,
		Max = 1000,
		Default = 1000,
		Function = function(Val)
			if CircleObject then
				CircleObject.Radius = Val
			end
		end
	})

	Distance = ProjectileAimbot:CreateSlider({
		Name = 'Distance',
		Min = 1,
		Max = 1000,
		Default = 1000,
		Suffix = 'studs',
		Tooltip = 'Maximum enemy distance from you'
	})

	PADebug = ProjectileAimbot:CreateToggle({
		Name = 'Debug',
		Tooltip = 'Prints to the console which projectile layer aimed a shot (local projectile, launch values, or packet)'
	})

	ProjectileAimbot:CreateToggle({
		Name = 'Range Circle',
		Function = function(Callback)
			if Callback then
				local ok, circle = pcall(function()
					if not Drawing then return nil end
					return Drawing.new('Circle')
				end)
				if ok and circle then
					CircleObject = circle
					CircleObject.Filled = CircleFilled.Enabled
					CircleObject.Color = Color3.fromHSV(CircleColor.Hue, CircleColor.Sat, CircleColor.Value)
					CircleObject.Position = GetMouseOrigin()
					CircleObject.Radius = FOV.Value
					CircleObject.NumSides = 100
					CircleObject.Thickness = CircleThickness.Value
					CircleObject.Transparency = 1 - CircleTransparency.Value
					CircleObject.Visible = ProjectileAimbot.Enabled
				end
			elseif CircleObject then
				pcall(function()
					CircleObject.Visible = false
					CircleObject:Remove()
				end)
				CircleObject = nil
			end

			CircleColor.Object.Visible = Callback
			CircleTransparency.Object.Visible = Callback
			CircleThickness.Object.Visible = Callback
			CircleFilled.Object.Visible = Callback
		end
	})

	CircleColor = ProjectileAimbot:CreateColorSlider({
		Name = 'Circle Color',
		Function = function(Hue, Sat, Val)
			if CircleObject then
				CircleObject.Color = Color3.fromHSV(Hue, Sat, Val)
			end
		end,
		Darker = true,
		Visible = false
	})

	CircleTransparency = ProjectileAimbot:CreateSlider({
		Name = 'Transparency',
		Min = 0,
		Max = 1,
		Decimal = 10,
		Default = 0.5,
		Function = function(Val)
			if CircleObject then
				CircleObject.Transparency = 1 - Val
			end
		end,
		Darker = true,
		Visible = false
	})

	CircleThickness = ProjectileAimbot:CreateSlider({
		Name = 'Thickness',
		Min = 1,
		Max = 10,
		Decimal = 10,
		Default = 1,
		Function = function(Val)
			if CircleObject then
				CircleObject.Thickness = Val
			end
		end,
		Darker = true,
		Visible = false,
		Tooltip = "How wide the circle's outline is, has no effect while Circle Filled is on"
	})

	CircleFilled = ProjectileAimbot:CreateToggle({
		Name = 'Circle Filled',
		Function = function(Callback)
			if CircleObject then
				CircleObject.Filled = Callback
			end
		end,
		Darker = true,
		Visible = false
	})

	Horizontal = ProjectileAimbot:CreateSlider({
		Name = 'Horizontal prediction',
		Min = 0,
		Max = 2,
		Default = 1,
		Decimal = 100,
		Tooltip = 'Scales how far ahead of the target you aim sideways'
	})

	Vertical = ProjectileAimbot:CreateSlider({
		Name = 'Vertical prediction',
		Min = 0,
		Max = 2,
		Default = 1,
		Decimal = 100,
		Tooltip = 'Scales how far ahead of the target you aim while it rises or falls'
	})

	AutoCharge = ProjectileAimbot:CreateToggle({
		Name = 'Auto Charge',
		Function = function(Callback)
			if Aim and Aim.Object then
				Aim.Object.Visible = Callback
			end
		end,
		Default = true,
		Tooltip = 'Fully charges your bow, Allowing your projectile to deal more damage'
	})

	Aim = ProjectileAimbot:CreateToggle({
		Name = 'Aim change',
		Default = true,
		Darker = true,
		Tooltip = 'Changes your trajectory to match charge percentage.'
	})

	OtherProjectiles = ProjectileAimbot:CreateToggle({
		Name = 'Other Projectiles',
		Default = true,
		Tooltip = 'Aims everything that is not an arrow or a splash potion'
	})

	UseUmeko = ProjectileAimbot:CreateToggle({
		Name = 'Use umeko',
		Tooltip = "Aims umeko's chakram even with Other Projectiles off"
	})

	Potions = ProjectileAimbot:CreateToggle({
		Name = 'Shoot pots',
		Default = true,
		Tooltip = 'Aims heal, poison and sleep splash potions, separate from Other Projectiles'
	})

	Blacklist = ProjectileAimbot:CreateTextList({
		Name = 'Blacklist',
		Default = {'telepearl'}
	})

	MiloCheck = ProjectileAimbot:CreateToggle({
		Name = 'Milo check',
		Default = true,
		Tooltip = 'Skips Milo players while they are disguised as a block'
	})
end)

run(function()
	local ProjectileHitbox
	local Targets
	local Expand
	local Visible
	local objects = {}

	local hitboxSize = Vector3.new(3, 6, 3)
	local hitboxColor = Color3.fromRGB(255, 60, 180)

	local function updateSize(val)
		hitboxSize = Vector3.new(3, 6, 3) + Vector3.one * ((val or 0) / 5)
		for _, part in pairs(objects) do
			part.Size = hitboxSize
		end
	end

	local function holdingProjectile()
		local live = liveHandTool()
		if live then return isProjectileTool(live) end
		local hand = store.hand
		return hand ~= nil and isProjectileTool(hand.tool)
	end

	local rayParams = RaycastParams.new()
	rayParams.FilterType = Enum.RaycastFilterType.Exclude

	local function behindWall(ent)
		if not Targets or not Targets.Walls or not Targets.Walls.Enabled then return false end
		if not ent.RootPart then return false end
		if not entitylib.isAlive or not entitylib.character or not entitylib.character.RootPart then return false end
		local origin = entitylib.character.RootPart.Position
		local direction = ent.RootPart.Position - origin
		rayParams.FilterDescendantsInstances = {entitylib.character, ent.Character}
		local result = workspace:Raycast(origin, direction, rayParams)
		return result ~= nil and (result.Position - origin).Magnitude < direction.Magnitude - 0.5
	end

	local function wanted(ent)
		if not ent.Targetable or not ent.Character or not ent.RootPart then return false end
		if not Targets then return false end
		if ent.Player then
			return Targets.Players ~= nil and Targets.Players.Enabled == true
		end
		return Targets.NPCs ~= nil and Targets.NPCs.Enabled == true
	end

	local function create(ent)
		if objects[ent] then return end
		if not wanted(ent) then return end
		if behindWall(ent) then return end
		local part = Instance.new('Part')
		part.Name = 'ProjectileHitbox'
		part.Archivable = false
		part.Size = hitboxSize
		part.CFrame = ent.RootPart.CFrame
		part.CanCollide = false
		part.CanTouch = false
		part.Massless = true
		part.Color = hitboxColor
		part.Material = Enum.Material.Neon
		part.Transparency = (Visible and Visible.Enabled) and 0.55 or 1
		part.LocalTransparencyModifier = (Visible and Visible.Enabled) and 0 or 1
		part.Parent = ent.Character
		local weld = Instance.new('Motor6D')
		weld.Part0 = ent.RootPart
		weld.Part1 = part
		weld.Parent = part
		objects[ent] = part
	end

	local function clear()
		for _, part in pairs(objects) do
			part:Destroy()
		end
		table.clear(objects)
		for _, plr in playersService:GetPlayers() do
			local char = plr.Character
			if char then
				for _, old in char:GetChildren() do
					if old.Name == 'ProjectileHitbox' then old:Destroy() end
				end
			end
		end
		for _, ent in entitylib.List do
			local char = ent.Character
			if char then
				for _, old in char:GetChildren() do
					if old.Name == 'ProjectileHitbox' then old:Destroy() end
				end
			end
		end
	end

	ProjectileHitbox = vape.Categories.Blatant:CreateModule({
		Name = 'Projectile Hitbox',
		Function = function(callback)
			if callback then
				if Expand then updateSize(Expand.Value) end
				local frame = 0
				ProjectileHitbox:Clean(runService.Heartbeat:Connect(function()
					frame = frame + 1
					if frame % 3 ~= 0 then return end
					if not holdingProjectile() then
						if next(objects) ~= nil then clear() end
						return
					end
					for ent, part in pairs(objects) do
						if not ent.Character or not ent.Character.Parent or not ent.RootPart then
							part:Destroy()
							objects[ent] = nil
						else
							part.Size = hitboxSize
						end
					end
					local list = entitylib.List
					for i = 1, #list do
						create(list[i])
					end
				end))
			else
				clear()
			end
		end,
		Tooltip = 'expands enemy hitboxes while a projectile is in hand'
	})

	Targets = ProjectileHitbox:CreateTargets({
		Players = true,
		NPCs = false,
		Walls = false
	})

	Expand = ProjectileHitbox:CreateSlider({
		Name = 'Expand amount',
		Min = 0,
		Max = 20,
		Default = 6,
		Decimal = 10,
		Function = function(val)
			updateSize(val)
		end,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})

	Visible = ProjectileHitbox:CreateToggle({
		Name = 'Visible',
		Default = true,
		Function = function(callback)
			local transparency = callback and 0.55 or 1
			local localMod = callback and 0 or 1
			for _, part in pairs(objects) do
				part.Transparency = transparency
				part.LocalTransparencyModifier = localMod
			end
		end
	})
end)

local Attacking
run(function()
	local Killaura
	local Targets
	local Sort
	local SwingRange
	local AttackRange
	local AngleSlider
	local Swing
	local Animation
	local AnimationMode
	local AnimationSpeed
	local AnimationTween
	local Limit
	local LegitAura
	local AttackCheck
	local kitChecks
	local SwingTime
	local SwingTimeSlider
	local AirHit
	local AirHitsChance
	local FastHits
	local LegitSwitch
	local Arrows
	local Gloops
	local GloopCooldown
	local Fireballs
	local FireballCooldown
	local FireRate
	local ArrowCharge = 100 -- Default 100% charge (full power)
	local UseKits
	local AttackRemote
	local HitregMode
	local DynamicDelaySlider
	local lastAttackTime = 0
	local lastTargetTime = 0
	local lastAnimTime = 0 -- Track when last animation was played to prevent doubling
	local anims, AnimDelay, AnimTween, armC0 = vape.Libraries.auraanims, tick()
	local FROZEN_THRESHOLD = 10
	local HIT_PERIOD = 0.285 -- Killaura hit period fallback (~35 hits/10s)
	local SERVER_FLOOR = 0.292
	local SERVER_REACH = 14.399
	local NORMAL_SWORD_SWING_SPEED = 0.35 -- Standard in-game sword swing speed, NEVER changes
	local kaPeriod = HIT_PERIOD
	local animPeriod = NORMAL_SWORD_SWING_SPEED -- Animation is ALWAYS decoupled from hit timing
	local kaNextFire = 0
	local kaSync = 0
	local kaSyncSrv = 0
	local kaLastSrv = 0
	local kaLastSend = 0
	local lastProjectileTime = 0 -- Track when last projectile was fired
	local glueRemote = {InvokeServer = function() end}
	local projectileRemote = {InvokeServer = function() end}
	local gloopTracker = {}
	local fireballTracker = {}

	-- DYNAMIC SWORD TIMING & HITSPACING SYSTEM
	local SwordTiming = {
		SafeSpacing  = 0.295, -- Stealth Mode delay
		HighSpacing  = 0.2855, -- spacing in each hits for Advanced Mode only
		HitFloor     = 0.292, --  he server's minimum allowed time between hits. Going below this will cause ghost hits.
		GapFloor     = 0.2945, -- minimum gap between con hits
		ArrivalFloor = 0.274, -- how early it can arrive b4 ghosting 
		CooldownCorrection = (0.017999999225139618 / 10) + 0.013412,
	}

	local WeaponSpacing = {
		[0.21] = 0.229,
		[0.25] = 0.249,
		[0.35] = 0.345,
		[0.4]  = 0.341,
		[0.6]  = 0.63,
	}

	-- HighMode: 'Stealth Mode' | 'Advanced Mode' | 'Dynamic'
	-- DynamicDelay: slider value (1-100) only used when HighMode == 'Dynamic'
	function SwordTiming.Calculate(Speed, HighMode, DynamicDelay, Budget, Hits)
		local Stock = Speed == 0.3
		local Normal = (HighMode == 'Advanced Mode' or HighMode == 'Dynamic') and SwordTiming.HighSpacing or SwordTiming.SafeSpacing
		local Spacing = Stock and Normal or WeaponSpacing[Speed] or Speed + 0.03

		if HighMode == 'Dynamic' and DynamicDelay then
			Spacing = math.max(Spacing * (DynamicDelay / 100), Budget or 0)
		end

		if Hits and Hits ~= 35 then Spacing = math.max(Spacing, 10 / math.max(Hits - 1, 1)) end
		Spacing = math.max(Spacing, Budget or 0)
		local Scale = Spacing / (Stock and Normal or SwordTiming.SafeSpacing)
		local Gap = (Scale < 1 and SwordTiming.GapFloor or SwordTiming.HitFloor) * Scale
		if Stock and (HighMode == 'Advanced Mode' or HighMode == 'Dynamic') then
			Gap = math.max(Gap, SwordTiming.GapFloor, Budget or 0)
		end
		return Spacing, Scale, Gap, math.max(Speed - SwordTiming.CooldownCorrection, 0), Stock
	end

	-- 240Hz Quantized Clock
	local preciseRemainder = 0
	local preciseTimestamp = tick()

	task.spawn(function()
		glueRemote = replicatedStorage:WaitForChild('rbxts_include'):WaitForChild('node_modules'):WaitForChild('@rbxts'):WaitForChild('net'):WaitForChild('out'):WaitForChild('_NetManaged'):WaitForChild('ProjectileFire')
	end)

	task.spawn(function()
		task.wait()
		local _remotes = getgenv().remotes or remotes
		pcall(function()
			projectileRemote = bedwars.Client:Get(_remotes.FireProjectile).instance
			AttackRemote = bedwars.Client:Get(_remotes.AttackEntity).instance
		end)
	end)

	local function getKnitControllers()
		local missing = getgenv().NYXMissingModule
		local kc = bedwars.KnitClient
		local ctrls = kc and kc.Controllers
		if ctrls ~= nil and ctrls ~= missing then return ctrls end
		local kn = bedwars.Knit
		local knc = kn and kn.Controllers
		if knc ~= nil and knc ~= missing then return knc end
		return ctrls or knc
	end

	local function quantize240(value)
		return math.ceil(value / (1 / 240)) * (1 / 240)
	end

	local function updatePreciseClock()
		local now = tick()
		if now - preciseTimestamp >= 0.25 then
			preciseRemainder = 0
			preciseTimestamp = now
		end
		local elapsed = now - preciseTimestamp
		local steps = math.floor(elapsed / (1 / 240))
		preciseRemainder = math.max(preciseRemainder, steps * (1 / 240))
		return preciseRemainder
	end

	local function getAttackDelay(meta)
		local mode = (HitregMode and HitregMode.Value) or 'Consistent'
		if mode == 'Stealth Mode' then mode = 'Consistent'
		elseif mode == 'Advanced Mode' then mode = 'High Hit Reg'
		elseif mode == 'Dynamic' then mode = 'Legit' end
		local dynDelay = (DynamicDelaySlider and DynamicDelaySlider.Value) or 100
		local Speed = meta.sword and meta.sword.attackSpeed or 0.3
		local Budget = 0
		local Hits = 36
		
		-- Advanced Mode: 48.55, Stealth Mode: 50, Dynamic: slider value
		local effectiveDelay
		if mode == 'Legit' then
			effectiveDelay = dynDelay
		elseif mode == 'High Hit Reg' then
			effectiveDelay = 20
		else
			effectiveDelay = 25
		end
		
		-- This decouples hit registration from animation speed
		local Spacing = SwordTiming.Calculate(Speed, 'Dynamic', effectiveDelay, Budget, Hits)
		return quantize240(Spacing)
	end

	local function markAttackResult(success)
		-- No-op: kept for compatibility
	end

	-- ONLY supported Use Kits are registered here
	local supportedKits = {
		['card'] = 'Fortuna',
		['fortuna'] = 'Fortuna',
		['dragon_slayer'] = 'Kaliyah',
		['kaliyah'] = 'Kaliyah',
		['ice_queen'] = 'Freiya',
		['freiya'] = 'Freiya',
		['void_hunter'] = 'Skoll',
		['skoll'] = 'Skoll',
		['regent'] = 'Void Regent',
		['void_regent'] = 'Void Regent',
		['hannah'] = 'Hannah',
		['spirit_assassin'] = 'Evelynn',
		['evelynn'] = 'Evelynn',
		['evelyn'] = 'Evelynn',
		['midnight'] = 'Nyx',
		['nyx'] = 'Nyx'
	}

	local function getSupportedKitDisplayName(rawKit)
		if not rawKit or rawKit == 'none' or rawKit == '' then return nil end
		local lower = tostring(rawKit):lower()
		for key, display in pairs(supportedKits) do
			if lower:find(key) then
				return display
			end
		end
		return nil
	end

	local function notifyKit(kitDisplayName)
		local title = 'Killaura Kit Detector'
		local msg = 'Detected Ability of --> : ' .. tostring(kitDisplayName)
		if warningNotification then
			warningNotification(title, msg, 3)
		elseif vape and vape.CreateNotification then
			vape:CreateNotification(title, msg, 3)
		end
	end

	local function FireAttackRemote(weapon, entityInstance, selfPos, targetPos)
		local delta = (targetPos - selfPos).Magnitude
		if delta < 0.01 then return false end

		local dir = CFrame.lookAt(selfPos, targetPos).LookVector
		local pos = selfPos + dir * math.max(delta - 14.399, 0)

		local payload = {
			weapon = weapon,
			chargedAttack = {chargeRatio = 0},
			lastSwingServerTimeDelta = kaLastSend > 0 and math.max(workspace:GetServerTimeNow() - kaLastSend, 0.01) or 0.35,
			entityInstance = entityInstance,
			validate = {
				raycast = {
					cameraPosition = {value = pos},
					cursorDirection = {value = dir}
				},
				targetPosition = {value = targetPos},
				selfPosition = {value = pos}
			}
		}

		-- the server drops SwordHit fired on the raw remote; it has to go through the net client like the game's own swing
		if not store.kaAttackNet then
			pcall(function()
				local net = bedwars.Client:Get((getgenv().remotes or remotes).AttackEntity)
				if net and type(net.SendToServer) == 'function' then
					store.kaAttackNet = net
				end
			end)
		end
		local net = store.kaAttackNet
		if net then
			local previous = store.kaSending
			store.kaSending = true
			local ok = pcall(net.SendToServer, net, payload)
			store.kaSending = previous
			if ok then return true end
		end

		if not AttackRemote then return false end
		AttackRemote:FireServer(payload)
		return true
	end

	local function isOnTinker()
		local ok, mounted = pcall(function()
			local controllers = getKnitControllers()
			return controllers and controllers.TinkerKitController and controllers.TinkerKitController.mounted
		end)
		return ok and mounted == true
	end

	local _lastTinkerSwing = 0
	local function playTinkerSwing()
		local now = workspace:GetServerTimeNow()
		if now - _lastTinkerSwing < 0.35 then return end
		_lastTinkerSwing = now
		pcall(function()
			local controllers = getKnitControllers()
			local controller = controllers and controllers.TinkerKitController
			if not controller then return end
			local model = controller.userMap[lplr]
			if not model then return end
			local mac = controllers.MountAnimationController
			if not mac then return end
			local animId = bedwars.AnimationType and bedwars.AnimationType.TINKER_ATTACK
			mac:playAnimationInMount(model, animId, 1.85)
		end)
	end

	local _adCacheSword = nil
	local _adCacheMeta = nil
	local _adCacheTime = 0

	local function findItemMeta(toolName)
		local itemMeta = bedwars.ItemMeta
		if not itemMeta or type(itemMeta) ~= 'table' or not toolName then return nil end
		local direct = itemMeta[toolName]
		if direct then return direct end
		local lower = toolName:lower()
		local underscored = lower:gsub('[%s%-]+', '_')
		for key, meta in pairs(itemMeta) do
			if type(key) == 'string' and (key:lower() == lower or key:lower() == underscored or key:lower():gsub('[%s%-]+', '_') == underscored) then
				return meta
			end
		end
		return nil
	end

	local function isMeleeWeapon(toolName)
		if not toolName then return false end
		local lower = toolName:lower()
		if lower:find('frosty_hammer') or lower:find('tinker') or lower:find('chainsaw') or lower:find('sword') or lower:find('blade') or lower:find('scythe') or lower:find('dagger') or lower:find('hammer') or lower:find('axe') then
			return true
		end
		local meta = findItemMeta(toolName)
		return meta and (meta.sword ~= nil or meta.tinkerChainsaw ~= nil or meta.tinkerMech ~= nil)
	end

	local function computeAttackData()
		store.kaDataBlock = nil
		if not entitylib.isAlive then store.kaDataBlock = 'dead' return false end

		local casting = lplr:GetAttribute('IsCasting')
		if casting ~= nil and casting ~= false and casting ~= 0 and casting ~= '' then
			if casting == true then store.kaDataBlock = 'casting' return false end
			if type(casting) == 'number' and casting > workspace:GetServerTimeNow() then store.kaDataBlock = 'casting' return false end
		end

		if bedwars.SwordController and bedwars.SwordController.disableSwingState then store.kaDataBlock = 'swing-disabled' return false end

		local stunned = lplr.Character and lplr.Character:GetAttribute('StunnedUntilTime')
		if stunned and stunned > workspace:GetServerTimeNow() then store.kaDataBlock = 'stunned' return false end

		if AttackCheck and AttackCheck.Enabled then
			if kitChecks then
				for _, check in pairs(kitChecks) do
					local ok, res = pcall(check)
					if ok and res then store.kaDataBlock = 'kitcheck' return false end
				end
			end
		end

		if tick() - (store.silasAbilityTime or 0) < 2.2 then store.kaDataBlock = 'silas-cd' return false end
		if tick() - (store.terraStompTime or 0) < 0.7 then store.kaDataBlock = 'terra-stomp' return false end
		if tick() - (store.terraKickTime or 0) < 0.5 then store.kaDataBlock = 'terra-kick' return false end

		local sword = store.hand
		if not sword or not sword.tool or not isMeleeWeapon(sword.tool.Name) then
			sword = (Limit and Limit.Enabled) and nil or store.tools.sword
		end
		if not sword or not sword.tool then store.kaDataBlock = 'no-sword-tool' return false end

		local itemMeta = bedwars.ItemMeta
		local meta = itemMeta and (itemMeta[sword.tool.Name] or findItemMeta(sword.tool.Name))
		if not meta then store.kaDataBlock = 'no-itemmeta:' .. tostring(sword.tool and sword.tool.Name) return false end

		if Limit and Limit.Enabled then
			if not isMeleeWeapon(sword.tool.Name) or (bedwars.DaoController and bedwars.DaoController.chargingMaid) then
				store.kaDataBlock = 'limit-block'
				return false
			end
		end

		if LegitAura and LegitAura.Enabled then
			local lastSwing = bedwars.SwordController and bedwars.SwordController.lastSwing
			if not lastSwing or (tick() - lastSwing) > 0.25 then store.kaDataBlock = 'legit-swing-wait' return false end
		end

		return sword, meta
	end

	local function getAttackData()
		local now = os.clock()
		if now - _adCacheTime < 0.02 and _adCacheSword then
			return _adCacheSword, _adCacheMeta
		end
		_adCacheTime = now
		local sword, meta = computeAttackData()
		_adCacheSword = sword
		_adCacheMeta = meta
		return sword, meta
	end

	local function resetSwordCooldown()
		if bedwars.SwordController then
			bedwars.SwordController.lastAttack = 0
			bedwars.SwordController.lastSwing = 0
			if bedwars.SwordController.lastChargedAttackTimeMap then
				for weaponName in pairs(bedwars.SwordController.lastChargedAttackTimeMap) do
					bedwars.SwordController.lastChargedAttackTimeMap[weaponName] = 0
				end
			end
		end
	end

	local function getWeaponAttackSpeed(sword, meta)
		if not sword or not sword.tool then return HIT_PERIOD end
		local toolName = sword.tool.Name:lower()

		if toolName:find('frosty_hammer') then
			local speedLvl = lplr:GetAttribute('speed') or sword.tool:GetAttribute('speed') or 0
			if speedLvl == 3 then
				return 0.25
			elseif speedLvl == 2 then
				return 0.28
			elseif speedLvl == 1 then
				return 0.32
			else
				return 0.35
			end
		end

		if meta and meta.sword and meta.sword.attackSpeed then
			return meta.sword.attackSpeed
		end

		return HIT_PERIOD
	end

	-- Play First-Person & Viewmodel Swing Animation (Supports All Hephaestus Chainsaw Tiers & Standard Swords)
	local function triggerFirstPersonSwing(meta)
		pcall(function()
			local tool = store.hand and store.hand.tool
			local toolName = tool and tool.Name:lower() or ""

			-- 1. Fire ClientSyncEvent SwordSwing
			local syncEvents = bedwars.ClientSyncEvents or (bedwars.Client and bedwars.Client:GetNamespace('Default'))
			if syncEvents and syncEvents:Get('SwordSwing') then
				syncEvents:Get('SwordSwing'):Fire({
					player = lplr
				})
			end

			-- 2. Play Sword Effect if meta is available (pass false to prevent forcing weapon-speed animation reset)
			if bedwars.SwordController and meta then
				bedwars.SwordController:playSwordEffect(meta, false)
			end

			-- 3. Force Viewmodel & Arm Swing for Wood/Base Chainsaw & All Tiers
			if bedwars.ViewmodelController and bedwars.ViewmodelController.playAnimation then
				if toolName:find('chainsaw') or toolName:find('tinker') or toolName:find('wood') then
					bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.SWORD_SWING or bedwars.AnimationType.FP_USE_ITEM or 15)
				elseif bedwars.AnimationType and bedwars.AnimationType.SWORD_SWING then
					bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.SWORD_SWING)
				end
			end
		end)
	end

	-- REAL-TIME USE KITS ENGINE
	local lastNotifiedKit = nil
	local skollMarked = false
	local skollMarkedTarget = nil
	local skollMarkedTime = 0
	local regentBusy = false
	local useKitLoop = nil
	local lastFortunaTime = 0
	local lastHannahTime = 0
	local lastEvelynnTime = 0
	local lastNyxTime = 0

	task.spawn(function()
		local ClientSyncEvents = bedwars.ClientSyncEvents or (bedwars.Client and bedwars.Client:GetNamespace('Default'))
		if ClientSyncEvents then
			pcall(function()
				connectSignal(ClientSyncEvents:Get('VoidHunter_TargetMarked'), function(data)
					skollMarked = true
					skollMarkedTime = tick()
					if data and data.target then
						skollMarkedTarget = data.target
					end
				end)
				connectSignal(ClientSyncEvents:Get('VoidHunter_TargetMarkedRemoved'), function()
					skollMarked = false
					skollMarkedTarget = nil
				end)
			end)
		end
	end)

	local function getCurrentKit()
		return store.equippedKit or lplr:GetAttribute('BedwarsKit') or 'none'
	end

	local function findVoidAxeSlot()
		for slot, entry in store.inventory.hotbar or {} do
			local item = entry and entry.item
			local tool = item and item.tool
			if (item and item.itemType == 'void_axe') or (tool and tool.Name == 'void_axe') then
				return slot - 1
			end
		end
		return nil
	end

	local function isInCombatWithTarget(target, maxDist)
		if not target or not target.RootPart or not entitylib.isAlive then return false end
		local myRoot = entitylib.character and entitylib.character.RootPart
		if not myRoot then return false end
		local dist = (target.RootPart.Position - myRoot.Position).Magnitude
		if dist > (maxDist or AttackRange.Value) then return false end

		if Attacking then return true end
		if LegitAura and LegitAura.Enabled then
			local lastSwing = bedwars.SwordController and bedwars.SwordController.lastSwing
			if lastSwing and (tick() - lastSwing) <= 0.35 then
				return true
			end
		end
		return (tick() - lastAttackTime) < 1.0 or (tick() - lastTargetTime) < 0.4
	end

	local function executeKitAbilities()
		if not UseKits or not UseKits.Enabled or not entitylib.isAlive then return end
		local rawKit = getCurrentKit()
		local supportedName = getSupportedKitDisplayName(rawKit)
		if not supportedName then return end

		local kit = tostring(rawKit):lower()
		local myRoot = entitylib.character and entitylib.character.RootPart
		if not myRoot then return end
		local myPos = myRoot.Position
		local target = store.KillauraTarget
		local controllers = getKnitControllers()

		-- 1. Fortuna (Card Throw)
		if kit:find('card') or kit:find('fortuna') then
			if target and target.Character and isInCombatWithTarget(target, 60) then
				if tick() - lastFortunaTime > 0.4 then
					lastFortunaTime = tick()
					if controllers and controllers.FortunaController then
						controllers.FortunaController.target = target.Character
					end
					pcall(function()
						if bedwars.AbilityController and bedwars.AbilityController:canUseAbility('CARD_THROW') then
							bedwars.AbilityController:useAbility('CARD_THROW')
						end
						local rem = replicatedStorage:FindFirstChild('events-@easy-games/game-core:shared/game-core-networking@getEvents.Events')
						if rem and rem:FindFirstChild('useAbility') then
							rem.useAbility:FireServer('CARD_THROW')
						end
						local _remotes = getgenv().remotes or remotes
						if _remotes and _remotes.AttemptCardThrow then
							bedwars.Client:Get(_remotes.AttemptCardThrow).instance:FireServer({ targetEntityInstance = target.Character })
						end
					end)
				end
			end

		-- 2. Kaliyah (dragon_slayer)
		elseif kit:find('dragon_slayer') or kit:find('kaliyah') then
			if bedwars.AbilityController and bedwars.AbilityController:canUseAbility('dragon_slayer_punch', {disableBlockedAbilityAlert = true}) then
				local requiredStacks = 3
				if bedwars.DragonSlayerController and bedwars.DragonSlayerController.dragonEmblems then
					for emblemTarget, v in pairs(bedwars.DragonSlayerController.dragonEmblems) do
						if v.stackCount >= requiredStacks and emblemTarget.PrimaryPart and (emblemTarget.PrimaryPart.Position - myPos).Magnitude <= 18 then
							bedwars.AbilityController:useAbility('dragon_slayer_punch')
							break
						end
					end
				end
			end

		-- 3. Freiya (ice_queen)
		elseif kit:find('ice_queen') or kit:find('freiya') then
			if bedwars.AbilityController and bedwars.AbilityController:canUseAbility('ice_queen', {disableBlockedAbilityAlert = true}) then
				for _, v in pairs(entitylib.List) do
					if v.Targetable and v.Character and (v.Character:GetAttribute('IceQueenStacks') or 0) >= 3 and v.RootPart and (v.RootPart.Position - myPos).Magnitude <= 40 then
						bedwars.AbilityController:useAbility('ice_queen')
						break
					end
				end
			end

		-- 4. Skoll (void_hunter)
		elseif kit:find('void_hunter') or kit:find('skoll') then
			if not skollMarked then
				if target and target.RootPart and isInCombatWithTarget(target, 22) then
					local targetPos = target.RootPart.Position
					local dir = (targetPos - myPos).Unit
					pcall(function()
						if bedwars.AbilityController then
							bedwars.AbilityController:useAbility('void_hunter_mark')
						elseif controllers and controllers.SelectItemController then
							controllers.SelectItemController:useMarkAbility(dir)
						end
					end)
				end
			else
				local shouldDetonate = false
				if skollMarkedTarget and skollMarkedTarget.Parent and skollMarkedTarget:FindFirstChild('HumanoidRootPart') then
					local tPos = skollMarkedTarget.HumanoidRootPart.Position
					if (tPos - myPos).Magnitude >= 35 then
						shouldDetonate = true
					end
				elseif (tick() - skollMarkedTime) > 5 then
					shouldDetonate = true
				end

				if shouldDetonate and bedwars.AbilityController then
					pcall(function() bedwars.AbilityController:useAbility('void_hunter_detonate') end)
				end
			end

		-- 5. Void Regent (void_axe)
		elseif kit:find('void_regent') or kit:find('regent') then
			if not regentBusy and bedwars.VoidAxeController and bedwars.AbilityController and bedwars.AbilityController:canUseAbility('void_axe_jump', {disableBlockedAbilityAlert = true}) then
				if target and target.RootPart and isInCombatWithTarget(target, 16) then
					local axeSlot = findVoidAxeSlot()
					if axeSlot ~= nil then
						regentBusy = true
						local oldSlot = store.inventory.hotbarSlot
						bedwars.Store:dispatch({type = 'InventorySelectHotbarSlot', slot = axeSlot})
						task.wait(0.02)
						if entitylib.isAlive then
							bedwars.VoidAxeController:useVoidAxe()
						end
						task.delay(0.2, function()
							if oldSlot ~= nil and entitylib.isAlive then
								bedwars.Store:dispatch({type = 'InventorySelectHotbarSlot', slot = oldSlot})
							end
							regentBusy = false
						end)
					end
				end
			end

		-- 6. Hannah (Blood For Blood Execution)
		elseif kit:find('hannah') then
			if target and target.Character and (tick() - lastHannahTime) > 0.2 then
				if (target.RootPart.Position - myPos).Magnitude <= 16 then
					local icon = target.Character:FindFirstChild('Hannah Execution Icon')
					local hasTag = collectionService:HasTag(target.Character, 'HannahExecuteInteraction')
					if icon or hasTag then
						lastHannahTime = tick()
						pcall(function()
							local _remotes = getgenv().remotes or remotes
							if _remotes and _remotes.HannahPromptTrigger then
								bedwars.Client:Get(_remotes.HannahPromptTrigger):CallServer({
									user = lplr,
									victimEntity = target.Character
								})
							end
						end)
					end
				end
			end

		-- 7. Evelynn (Spirit Assassin / Orb Auto-Consume via SpiritAssassinController)
		elseif kit:find('spirit_assassin') or kit:find('evelynn') or kit:find('evelyn') then
			if (tick() - lastEvelynnTime) > 0.15 then
				pcall(function()
					local evelynnController = bedwars.SpiritAssassinController or (controllers and controllers.SpiritAssassinController)
					for _, obj in ipairs(collectionService:GetTagged('EvelynnSoul')) do
						local part = obj:IsA('Model') and obj.PrimaryPart or (obj:IsA('BasePart') and obj)
						if part and (part.Position - myPos).Magnitude <= 40 then
							lastEvelynnTime = tick()
							if evelynnController and evelynnController.useSpirit then
								evelynnController:useSpirit(lplr, obj)
							else
								local _remotes = getgenv().remotes or remotes
								if _remotes and _remotes.SpiritAssassinUseSpirit then
									bedwars.Client:Get(_remotes.SpiritAssassinUseSpirit):CallServer({ spiritInstance = obj })
								end
							end
							break
						end
					end
				end)
			end

		-- 8. Nyx (Midnight Ability)
		elseif kit:find('midnight') or kit:find('nyx') then
			if target and isInCombatWithTarget(target, 20) and (tick() - lastNyxTime) > 0.5 then
				lastNyxTime = tick()
				pcall(function()
					if bedwars.AbilityController then
						if bedwars.AbilityController:canUseAbility('midnight', {disableBlockedAbilityAlert = true}) then
							bedwars.AbilityController:useAbility('midnight')
						elseif bedwars.AbilityController:canUseAbility('nyx_ability', {disableBlockedAbilityAlert = true}) then
							bedwars.AbilityController:useAbility('nyx_ability')
						else
							local rem = replicatedStorage:FindFirstChild('events-@easy-games/game-core:shared/game-core-networking@getEvents.Events')
							if rem and rem:FindFirstChild('useAbility') then
								rem.useAbility:FireServer('midnight')
							end
						end
					end
				end)
			end
		end
	end

	local function startUseKitsLoop()
		if useKitLoop then return end
		local initOk, activeKit = pcall(getCurrentKit)
		local supportedName = initOk and getSupportedKitDisplayName(activeKit) or nil
		if supportedName then
			lastNotifiedKit = supportedName
			pcall(notifyKit, supportedName)
		else
			lastNotifiedKit = nil
		end

		useKitLoop = task.spawn(function()
			local lastKitError = 0
			while UseKits and UseKits.Enabled do
				local ok, err = pcall(function()
					local currentKit = getCurrentKit()
					local currentSupported = getSupportedKitDisplayName(currentKit)
					if currentSupported and currentSupported ~= lastNotifiedKit then
						lastNotifiedKit = currentSupported
						notifyKit(currentSupported)
					elseif not currentSupported then
						lastNotifiedKit = nil
					end
					executeKitAbilities()
				end)
				if not ok and (tick() - lastKitError) >= 5 then
					lastKitError = tick()
					warn('[Killaura] kit loop error: ' .. tostring(err))
				end
				task.wait(0.08)
			end
			useKitLoop = nil
		end)
	end

	local function stopUseKitsLoop()
		if useKitLoop then
			pcall(task.cancel, useKitLoop)
			useKitLoop = nil
		end
		lastNotifiedKit = nil
	end

	-- FAST HITS & PROJECTILES
	local FireRates: {[string]: number} = {}
	local LastShot = 0.095
	local FastHitPending = false
	local fhShotSeq = 0

	local function getAmmo(check)
		for _, item in store.inventory.inventory.items do
			if check.ammoItemTypes and table.find(check.ammoItemTypes, item.itemType) then
				return item.itemType
			end
		end
	end

	local _projectilesCache = {}
	local _projectilesCacheTime = 0
	local function getProjectiles()
		if not Arrows or not Arrows.Enabled then return {} end
		local now = tick()
		if now - _projectilesCacheTime < 0.5 and #_projectilesCache > 0 then
			return _projectilesCache
		end
		_projectilesCacheTime = now
		table.clear(_projectilesCache)
		for _, item in store.inventory.inventory.items do
			local meta = bedwars.ItemMeta[item.itemType]
			if not meta then continue end
			local proj = meta.projectileSource
			if not proj or not proj.projectileType then continue end
			local ammo = getAmmo(proj)
			if not ammo then continue end
			local projType = proj.projectileType(ammo)
			local pmeta = projType and bedwars.ProjectileMeta[projType]
			if pmeta and pmeta.arrow and pmeta.launchVelocity then
				table.insert(_projectilesCache, {item, ammo, projType, proj})
			end
		end
		return _projectilesCache
	end

	local function canShoot(proj)
		return tick() > (FireRates[proj[1].itemType] or 0) and tick() > LastShot and not FastHitPending
	end

	local sharedFastHitsRayParams = RaycastParams.new()
	sharedFastHitsRayParams.FilterType = Enum.RaycastFilterType.Exclude

	local fhBusy = false

	local function fhInAngle(v)
		if not AngleSlider or AngleSlider.Value >= 360 then return true end
		if not v or not v.RootPart then return false end
		local root = entitylib.character and entitylib.character.RootPart
		if not root then return false end
		local look = root.CFrame.LookVector
		local flatLook = look * Vector3.new(1, 0, 1)
		if flatLook.Magnitude < 0.001 then return true end
		local flat = (v.RootPart.Position - root.Position) * Vector3.new(1, 0, 1)
		if flat.Magnitude <= 1 then return true end
		return math.acos(math.clamp(flatLook.Unit:Dot(flat.Unit), -1, 1)) <= math.rad(AngleSlider.Value) / 2
	end

	local function fhAwaitHand(tool, timeout)
		local name = tool.Name
		local deadline = tick() + timeout
		while tick() < deadline do
			local hand = store.hand and store.hand.tool
			if hand and (hand == tool or hand.Name == name) then return true end
			task.wait()
		end
		return false
	end

	local function fhSwapTimeout()
		return math.clamp(netPing() * 2 + 0.05, 0.1, 0.6)
	end

	-- The server only accepts the shot if its own hand already holds the tool, so wait for the
	-- equip round trip instead of firing after a fixed sleep.
	local fhHubTool = nil
	local fhLegitShot = false
	local function fhEquipAwait(tool)
		if not tool or not tool.Parent then return false end
		local check = lplr.Character and lplr.Character:FindFirstChild('HandInvItem')
		local handNow = store.hand and store.hand.tool
		if check and check.Value == tool and handNow and (handNow == tool or handNow.Name == tool.Name) then return true end
		local switchedNow = false
		pcall(function() switchedNow = switchItem(tool, 0) == true end)
		if not switchedNow then return false end
		fhHubTool = tool
		local timeout = fhSwapTimeout()
		if fhAwaitHand(tool, timeout) then return true end
		pcall(function() bedwars.Client:Get(remotes.EquipItem):CallServerAsync({hand = tool}) end)
		return fhAwaitHand(tool, math.min(timeout, 0.2))
	end

	local fhRestoreToken = 0
	local function fhRestoreSword()
		if fhLegitShot then return end
		local sw = store.tools.sword
		if not sw or not sw.tool or not sw.tool.Parent then return end
		local check = lplr.Character and lplr.Character:FindFirstChild('HandInvItem')
		if not check then return end
		-- If the player picked something else while the shot was in flight, that is their hand now.
		if fhHubTool and check.Value and check.Value ~= fhHubTool and check.Value.Parent then
			fhHubTool = nil
			return
		end
		fhHubTool = nil
		fhRestoreToken = fhRestoreToken + 1
		local token = fhRestoreToken
		check.Value = sw.tool
		task.spawn(function()
			pcall(function() bedwars.Client:Get(remotes.EquipItem):CallServerAsync({hand = sw.tool}) end)
			for _ = 1, 3 do
				task.wait(0)
				if token ~= fhRestoreToken then return end
				if not sw.tool.Parent then return end
				if not Killaura or not Killaura.Enabled then return end
				if isProjectileTool(liveHandTool()) then return end
				if check.Value ~= sw.tool or (store.hand and store.hand.tool ~= sw.tool) then
					check.Value = sw.tool
					pcall(function() bedwars.Client:Get(remotes.EquipItem):CallServerAsync({hand = sw.tool}) end)
				else
					return
				end
			end
		end)
	end

	local _fhVelHistory = {}
	local _fhPing = 0.1
	local _fhPingClock = 0
	local _fhIdChars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'

	local function fhGenId()
		local out = table.create(8)
		for i = 1, 8 do
			local n = math.random(1, #_fhIdChars)
			out[i] = _fhIdChars:sub(n, n)
		end
		return table.concat(out)
	end

	local function getFHPing()
		if tick() - _fhPingClock < 1 then return _fhPing end
		_fhPingClock = tick()
		-- Use store.ping.total for direct ping measurement (more accurate than game stats)
		local val = (store.ping and store.ping.total) or 0
		_fhPing = math.clamp(val, 0.02, 1)
		return _fhPing
	end

	local function smoothedVelocity(ent, targetPart)
		local rawVel = targetPart.AssemblyLinearVelocity or targetPart.Velocity or Vector3.zero
		local key = tostring(ent)
		if not _fhVelHistory[key] then
			_fhVelHistory[key] = rawVel
		else
			_fhVelHistory[key] = _fhVelHistory[key]:Lerp(rawVel, 0.35)
		end
		return _fhVelHistory[key], rawVel
	end

	local function targetGravity(ent)
		local playerGravity = workspace.Gravity
		local balloons = ent.Character and ent.Character:GetAttribute('InflatedBalloons')
		if balloons and balloons > 0 then
			playerGravity = workspace.Gravity * (1 - (balloons >= 4 and 1.2 or balloons >= 3 and 1 or 0.975))
		end
		if ent.Character and ent.Character.PrimaryPart and ent.Character.PrimaryPart:FindFirstChild('rbxassetid://8200754399') then
			playerGravity = 6
		end
		if ent.Player and ent.Player:GetAttribute('IsOwlTarget') then
			local _owls = collectionService:GetTagged('Owl')
			if #_owls > 0 then
				local _uid = ent.Player.UserId
				for _, owl in ipairs(_owls) do
					if owl:GetAttribute('Target') == _uid and owl:GetAttribute('Status') == 2 then
						playerGravity = 0
						break
					end
				end
			end
		end
		return playerGravity
	end

	local function shootProjectile(item, ammo, projectile, itemMeta, selfPos, ent, ignoreSwitch)
		local meta = bedwars.ProjectileMeta[projectile]
		if not meta then return false end

		local switched = false
		if not ignoreSwitch then
			fhBusy = true
			store._fhBusySince = workspace:GetServerTimeNow()
			if not fhEquipAwait(item.tool) then
				fhRestoreSword()
				fhBusy = false
				return false
			end
			switched = true
			local root = entitylib.character and entitylib.character.RootPart
			if not root then
				fhRestoreSword()
				fhBusy = false
				return false
			end
			selfPos = root.Position
		end

		local gravity = tonumber(meta.gravitationalAcceleration) or 196.2
		if gravity < 1 then gravity = 0 end
		local targetPart = ent.RootPart
		local playerGravity = targetGravity(ent)

		local maxCharge = tonumber(itemMeta.maxStrengthChargeSec) or 0
		local chargePct = ArrowCharge / 100
		local drawTime = maxCharge * chargePct
		local multiAt = tonumber(itemMeta.multiShotChargeTime)
		if multiAt and chargePct >= 1 then
			drawTime = math.max(drawTime, multiAt)
		end
		local minScalar = tonumber(itemMeta.minStrengthScalar) or 1
		local chargeRatio = maxCharge > 0 and math.clamp(drawTime / maxCharge, 0, 1) or 1
		local projSpeed = meta.launchVelocity * (minScalar + (1 - minScalar) * chargeRatio)

		local ping = getFHPing()
		local smoothVel, rawVel = smoothedVelocity(ent, targetPart)
		smoothVel = Vector3.new(smoothVel.X, rawVel.Y, smoothVel.Z)
		local hip = ent.HipHeight or 2
		local aimPart = targetPart
		local aimOffset = hip * 0.15
		do
			local itype = tostring(item.itemType)
			local head = ent.Character and ent.Character:FindFirstChild('Head')
			local speed = tonumber(meta.launchVelocity) or 0
			local grav = tonumber(meta.gravitationalAcceleration) or 196.2
			local dist = (targetPart.Position - selfPos).Magnitude

			if itype:find('headhunter') then
				local hspeed = Vector3.new(smoothVel.X, 0, smoothVel.Z).Magnitude
				if head and dist < 90 and hspeed < 28 and math.abs(smoothVel.Y) < 30 then
					aimPart = head
					aimOffset = -0.35
				else
					aimOffset = hip * 0.15
				end
			elseif itype:find('bomb') or itype:find('grenade') or itype:find('santa') or itype:find('impulse') then
				aimOffset = -hip * 0.5
			elseif itype:find('rocket') or itype:find('launcher') or itype:find('firework') then
				aimOffset = 0
			elseif meta.arrow then
				if grav <= 40 and speed >= 200 and dist < 60 and head then
					aimPart = head
					aimOffset = 0
				else
					aimOffset = hip * 0.15
				end
			elseif itype:find('snowball') or itype:find('chakram') or itype:find('spell') then
				aimOffset = hip * 0.3
			end
		end
		local leadPos = aimPart.Position + Vector3.new(0, aimOffset, 0)
		local netLead = math.clamp(ping, 0.02, 0.12)
		local vy = smoothVel.Y
		local dropY = vy * netLead
		if vy < -12 or vy > 12 then
			dropY = dropY - 0.5 * playerGravity * netLead * netLead
		end
		leadPos = leadPos + Vector3.new(smoothVel.X * netLead, dropY, smoothVel.Z * netLead)

		sharedFastHitsRayParams.FilterDescendantsInstances = {lplr.Character, gameCamera, ent.Character}

		local originPos
		do
			local handle = item.tool and item.tool:FindFirstChild('Handle')
			local bo = handle and handle:FindFirstChild('BulletOrigin')
			if bo and bo:IsA('Attachment') then
				originPos = bo.WorldPosition
			else
				local char = entitylib.character and entitylib.character.Character
				local hand = char and (char:FindFirstChild('RightHand') or char:FindFirstChild('Right Arm'))
				if hand then
					originPos = hand.Position
				else
					local pp = entitylib.character and entitylib.character.RootPart
					originPos = pp and (pp.Position + Vector3.new(0, 1.5, 0)) or gameCamera.CFrame.Position
				end
			end
		end

		local calc, flightTime = prediction.SolveTrajectory(
			originPos, projSpeed, gravity, leadPos, smoothVel,
			playerGravity, ent.HipHeight or 2,
			ent.Jumping and 42.6 or nil, sharedFastHitsRayParams
		)

		local lifetime = tonumber(meta.predictionLifetimeSec) or tonumber(meta.lifetimeSec) or (projSpeed > 0 and math.min(3, 120 / projSpeed) or 3)
		if not calc or (flightTime and flightTime > lifetime) then
			if switched then
				fhRestoreSword()
				fhBusy = false
			end
			return false
		end

		local shootPos = originPos
		if meta.arrow then
			shootPos = (CFrame.new(originPos, calc) * CFrame.new(Vector3.new(-(bedwars.BowConstantsTable.RelX or 0), -(bedwars.BowConstantsTable.RelY or 0), -(bedwars.BowConstantsTable.RelZ or 0)))).Position
		end
		do
			local myRoot = entitylib.character and entitylib.character.RootPart
			if myRoot then
				local away = (calc - shootPos)
				if away.Magnitude > 0.01 then
					shootPos = shootPos + away.Unit * 2
				end
				local flat = (shootPos - myRoot.Position) * Vector3.new(1, 0, 1)
				if flat.Magnitude < 0.5 then
					shootPos = shootPos + Vector3.new(0, 0.5, 0)
				end
			end
		end
		local dir = CFrame.lookAt(shootPos, calc).LookVector
		local id = fhGenId()
		local shotMeta = {
			shotId = fhGenId(),
			drawDurationSec = drawTime,
			drawDurationSeconds = drawTime
		}

		targetinfo.Targets[ent] = tick() + 1
		FireRates[item.itemType] = tick() + (tonumber(itemMeta.fireDelaySec) or 0.095)
		LastShot = tick() + (FireRate and FireRate.Value or 0.05)

		bedwars.ProjectileController:createLocalProjectile(
			meta, ammo, projectile, shootPos, id, dir * projSpeed,
			{drawDurationSec = drawTime, drawDurationSeconds = drawTime}
		)

		FastHitPending = true
		fhShotSeq = fhShotSeq + 1
		local shotSeq = fhShotSeq
		task.spawn(function()
			-- The bow stays in hand until the server has taken the shot, then the sword comes back.
			local ok, res = pcall(projectileRemote.InvokeServer, projectileRemote,
				item.tool, ammo, projectile, shootPos, selfPos,
				dir * projSpeed, id, shotMeta,
				workspace:GetServerTimeNow() - 0.05
			)
			FastHitPending = false
			if shotSeq == fhShotSeq then
				if switched and not fhLegitShot then
					pcall(fhRestoreSword)
					local deadline = tick() + math.min(getFHPing() * 0.6, 0.2)
					while tick() < deadline do
						local hand = store.hand and store.hand.tool
						if hand and not isProjectileTool(hand) then break end
						task.wait()
					end
				end
				fhBusy = false
			end
			if ok and res then
				pcall(function() res.Parent = replicatedStorage end)
				local sound = itemMeta.launchSound
				sound = sound and sound[math.random(1, #sound)] or nil
				if sound and bedwars.SoundManager then
					pcall(function() bedwars.SoundManager:playSound(sound) end)
				end
				lastProjectileTime = workspace:GetServerTimeNow()
			end
		end)
		-- Never leave the auras gated if the remote never answers.
		task.delay(0.45, function()
			if shotSeq == fhShotSeq and fhBusy then
				if switched and not fhLegitShot then pcall(fhRestoreSword) end
				fhBusy = false
			end
		end)

		return true
	end

	local function getGloopItem()
		for _, item in store.inventory.inventory.items do
			if item.itemType == 'glue_projectile' then
				return item
			end
		end
		return nil
	end

	local function getFireballItem()
		for _, item in store.inventory.inventory.items do
			if item.itemType == 'fireball' then
				return item
			end
		end
		return nil
	end

	local function isGlooped(ent)
		local char = ent and ent.Character
		if not char then return false end
		local val = char:GetAttribute('GlueSlow')
		return val ~= nil and val ~= 0
	end



	local function shootGloop(item, ent)
		-- Strict check: throw Gloops ONLY on real players (not NPCs)
		if not ent or not ent.RootPart or not ent.Player then return false end
		local key = tostring(ent)
		local now = tick()
		local tracked = gloopTracker[key]

		if tracked and tracked.target == ent then
			if tracked.gloopedUntil and now < tracked.gloopedUntil then return false end
			if tracked.lastShot and (now - tracked.lastShot) < (GloopCooldown and GloopCooldown.Value or 6) then return false end
		end

		if isGlooped(ent) then
			gloopTracker[key] = {target = ent, lastShot = now, gloopedUntil = now + 8}
			return false
		end

		local myRoot = entitylib.character and entitylib.character.RootPart
		if not myRoot then return false end
		if (ent.RootPart.Position - myRoot.Position).Magnitude > 45 then return false end

		local selfPos = entitylib.character.RootPart.Position
		local targetPart = ent.RootPart

		local gmeta = bedwars.ProjectileMeta.glue_trap
		local gSpeed = tonumber(gmeta and gmeta.launchVelocity) or 100
		local gGrav = tonumber(gmeta and gmeta.gravitationalAcceleration) or 85
		if gGrav < 1 then gGrav = 0 end

		local gitem = bedwars.ItemMeta[item.itemType]
		local gMax = tonumber(gitem and gitem.maxStrengthChargeSec) or 0
		local gMin = tonumber(gitem and gitem.minStrengthScalar) or 1
		local gPct = ArrowCharge / 100
		local gRatio = gMax > 0 and math.clamp(gPct, 0, 1) or 1
		gSpeed = gSpeed * (gMin + (1 - gMin) * gRatio)

		local ping = getFHPing()
		local smoothVel, rawVel = smoothedVelocity(ent, targetPart)
		smoothVel = Vector3.new(smoothVel.X, rawVel.Y, smoothVel.Z)
		local playerGravity = targetGravity(ent)

		local aimPos = targetPart.Position - Vector3.new(0, (ent.HipHeight or 2) * 0.6, 0)
		local netLead = math.clamp(ping, 0.02, 0.12)
		local dropY = smoothVel.Y * netLead
		if smoothVel.Y < -12 or smoothVel.Y > 12 then
			dropY = dropY - 0.5 * playerGravity * netLead * netLead
		end
		aimPos = aimPos + Vector3.new(smoothVel.X * netLead, dropY, smoothVel.Z * netLead)

		sharedFastHitsRayParams.FilterDescendantsInstances = {lplr.Character, gameCamera, ent.Character}

		local originPos = selfPos + Vector3.new(0, 1.5, 0)
		local calc, gFlight = prediction.SolveTrajectory(
			originPos, gSpeed, gGrav, aimPos, smoothVel,
			playerGravity, ent.HipHeight or 2,
			ent.Jumping and 42.6 or nil, sharedFastHitsRayParams
		)
		local gLife = tonumber(gmeta and gmeta.predictionLifetimeSec) or 2
		if not calc or (gFlight and gFlight > gLife) then return false end

		local dir = CFrame.lookAt(originPos, calc).LookVector

		fhBusy = true
		store._fhBusySince = workspace:GetServerTimeNow()
		if not fhEquipAwait(item.tool) then
			fhRestoreSword()
			fhBusy = false
			return false
		end

		pcall(function()
			glueRemote:InvokeServer(
				replicatedStorage.Inventories[lplr.Name].glue_projectile,
				'glue_projectile',
				'glue_trap',
				originPos,
				selfPos,
				dir * gSpeed,
				httpService:GenerateGUID(true):sub(1, 8):upper(),
				{shotId = httpService:GenerateGUID(true):sub(1, 8):upper(), drawDurationSec = 0.05},
				workspace:GetServerTimeNow() - 0.0475
			)
			lastProjectileTime = workspace:GetServerTimeNow()
		end)

		gloopTracker[key] = {target = ent, lastShot = now}
		task.wait(0.05)
		fhRestoreSword()
		fhBusy = false
		return true
	end

	local function shootFireball(item, ent)
		-- Strict check: throw Fireballs ONLY on real players (not NPCs)
		if not ent or not ent.RootPart or not ent.Player then return false end
		local key = tostring(ent)
		local now = tick()
		local tracked = fireballTracker[key]

		if tracked and tracked.lastShot and (now - tracked.lastShot) < (FireballCooldown and FireballCooldown.Value or 8) then
			return false
		end

		local myRoot = entitylib.character and entitylib.character.RootPart
		if not myRoot then return false end
		if (ent.RootPart.Position - myRoot.Position).Magnitude > 60 then return false end

		local selfPos = entitylib.character.RootPart.Position
		local targetPart = ent.RootPart

		local fmeta = bedwars.ProjectileMeta.fireball or {launchVelocity = 80, gravitationalAcceleration = 0}
		local fSpeed = tonumber(fmeta.launchVelocity) or 80
		local fGrav = tonumber(fmeta.gravitationalAcceleration) or 0

		local ping = getFHPing()
		local smoothVel, rawVel = smoothedVelocity(ent, targetPart)
		smoothVel = Vector3.new(smoothVel.X, rawVel.Y, smoothVel.Z)

		local aimPos = targetPart.Position
		local netLead = math.clamp(ping, 0.02, 0.12)
		aimPos = aimPos + Vector3.new(smoothVel.X * netLead, smoothVel.Y * netLead, smoothVel.Z * netLead)

		sharedFastHitsRayParams.FilterDescendantsInstances = {lplr.Character, gameCamera, ent.Character}

		local originPos = selfPos + Vector3.new(0, 1.5, 0)
		local calc = prediction.SolveTrajectory(
			originPos, fSpeed, fGrav, aimPos, smoothVel,
			workspace.Gravity, ent.HipHeight or 2,
			ent.Jumping and 42.6 or nil, sharedFastHitsRayParams
		)
		if not calc then calc = aimPos end

		local dir = CFrame.lookAt(originPos, calc).LookVector

		fhBusy = true
		store._fhBusySince = workspace:GetServerTimeNow()
		if not fhEquipAwait(item.tool) then
			fhRestoreSword()
			fhBusy = false
			return false
		end

		pcall(function()
			projectileRemote:InvokeServer(
				item.tool,
				'fireball',
				'fireball',
				originPos,
				selfPos,
				dir * fSpeed,
				httpService:GenerateGUID(true):sub(1, 8):upper(),
				{shotId = httpService:GenerateGUID(true):sub(1, 8):upper(), drawDurationSec = 0.05},
				workspace:GetServerTimeNow() - 0.0475
			)
			lastProjectileTime = workspace:GetServerTimeNow()
		end)

		fireballTracker[key] = {target = ent, lastShot = now}
		task.wait(0.05)
		fhRestoreSword()
		fhBusy = false
		return true
	end

	local fhStage = 1
	local fhUsageIndex = 1
	local function doFastHitsNEW(ent)
		if not ent or not ent.RootPart or not entitylib.isAlive then return end
		local selfPos = entitylib.character.RootPart.Position

		local anyOn = (Gloops and Gloops.Enabled) or (Fireballs and Fireballs.Enabled) or (Arrows and Arrows.Enabled)
		if not anyOn then return end

		for _ = 1, 3 do
			if fhStage == 1 then
				fhStage = 2
				if Gloops and Gloops.Enabled then
					local gloopItem = getGloopItem()
					if gloopItem and shootGloop(gloopItem, ent) then return end
				end
			elseif fhStage == 2 then
				fhStage = 3
				if Fireballs and Fireballs.Enabled then
					local fireballItem = getFireballItem()
					if fireballItem and shootFireball(fireballItem, ent) then return end
				end
			else
				fhStage = 1
				if Arrows and Arrows.Enabled then
					local projectiles = getProjectiles()
					if projectiles and #projectiles > 0 then
						for _i = 1, #projectiles do
							fhUsageIndex = fhUsageIndex % #projectiles + 1
							local p = projectiles[fhUsageIndex]
							if canShoot(p) then
								local item, ammo, projectile, itemMeta = unpack(p)
								if shootProjectile(item, ammo, projectile, itemMeta, selfPos, ent, false) then return end
								break
							end
						end
					end
				end
			end
		end
	end

	local function doFastHitsLegitSwitch(ent)
		if not ent or not ent.RootPart or not entitylib.isAlive then return end

		local selfPos = entitylib.character.RootPart.Position

		if Gloops and Gloops.Enabled then
			local gloopItem = getGloopItem()
			if gloopItem and shootGloop(gloopItem, ent) then return end
		end

		if Fireballs and Fireballs.Enabled then
			local fireballItem = getFireballItem()
			if fireballItem and shootFireball(fireballItem, ent) then return end
		end

		local projectiles = getProjectiles()
		if not projectiles or #projectiles == 0 then return end

		local readyProj
		for _, proj in projectiles do
			if canShoot(proj) then
				readyProj = proj
				break
			end
		end
		if not readyProj then return end

		local item, ammo, projectile, itemMeta = unpack(readyProj)
		local bowSlot, swordSlot
		local originalSlot = store.inventory.hotbarSlot
		local hotbar = store.inventory.hotbar
		for i = 1, #hotbar do
			local hv = hotbar[i]
			if hv and hv.item and hv.item.itemType then
				if hv.item.itemType == item.itemType and not bowSlot then
					bowSlot = i - 1
				end
				if isMeleeWeapon(hv.item.itemType) and not swordSlot then
					swordSlot = i - 1
				end
			end
		end
		if not bowSlot then return end

		fhBusy = true
		store._fhBusySince = workspace:GetServerTimeNow()
		local handReady = false
		fhLegitShot = true
		local shotOk, shotErr = pcall(function()
			if hotbarSwitch(bowSlot) then
				handReady = fhAwaitHand(item.tool, fhSwapTimeout())
			end
			-- Firing before the server sees the bow swap gets the shot rejected.
			if handReady then
				shootProjectile(item, ammo, projectile, itemMeta, selfPos, ent, true)
				task.wait(0.02)
			end
		end)
		fhLegitShot = false

		-- Restore the exact slot selected before the projectile switch.
		if originalSlot ~= nil then
			local restoreOk, restoreErr = pcall(hotbarSwitch, originalSlot)
			if not restoreOk then
				warn('[aerov4] FastHits hotbar restore failed: ' .. tostring(restoreErr))
			end
		end
		fhBusy = false
		if not shotOk then
			warn('[aerov4] FastHits projectile switch failed: ' .. tostring(shotErr))
		end
	end

	local function doFastHits()
		if not FastHits or not FastHits.Enabled then return end
		if not Killaura or not Killaura.Enabled then return end
		if not entitylib.isAlive then return end

		local selfRoot = entitylib.character and entitylib.character.RootPart
		if not selfRoot then return end

		local ent = store.KillauraTarget
		if not ent or not ent.RootPart then return end
		if not fhInAngle(ent) then return end
		if (ent.RootPart.Position - selfRoot.Position).Magnitude > SwingRange.Value then return end

		if not FastHitPending then
			if LegitSwitch and LegitSwitch.Enabled then
				doFastHitsLegitSwitch(ent)
			else
				doFastHitsNEW(ent)
			end
		end
	end

	local function startAutoShootLoop()
		if autoShootLoop then return end
		if not FireRates then FireRates = {} end
		fhUsageIndex = 1
		fhStage = 1
		table.clear(FireRates)
		LastShot = 0
		FastHitPending = false

		autoShootLoop = task.spawn(function()
			while Killaura and Killaura.Enabled and FastHits and FastHits.Enabled do
				pcall(doFastHits)
				task.wait(0.05)
			end
			fhBusy = false
			autoShootLoop = nil
		end)
	end

	local function stopAutoShootLoop()
		if autoShootLoop then
			pcall(task.cancel, autoShootLoop)
			autoShootLoop = nil
		end
		if FireRates then table.clear(FireRates) end
		table.clear(_fhVelHistory)
		table.clear(gloopTracker)
		table.clear(fireballTracker)
		fhUsageIndex = 1
		fhStage = 1
		fhBusy = false
		LastShot = 0
		FastHitPending = false
	end

	local killauraFireLoop
	local _graceTarget = nil
	local _graceUntil = 0
	local _fastAcqTime = 0
	local _fastAcqRes = nil

	local function withinAngle(v)
		if not AngleSlider or AngleSlider.Value >= 360 then return true end
		if not v or not v.RootPart then return false end
		local root = entitylib.character and entitylib.character.RootPart
		if not root then return true end
		local flatLV = root.CFrame.LookVector * Vector3.new(1, 0, 1)
		local facing = flatLV.Magnitude > 0.001 and flatLV.Unit or root.CFrame.RightVector
		local flat = (v.RootPart.Position - root.Position) * Vector3.new(1, 0, 1)
		if flat.Magnitude <= 1 then return true end
		return math.acos(math.clamp(facing:Dot(flat.Unit), -1, 1)) <= math.rad(AngleSlider.Value) / 2
	end

	local function inReach(v)
		local root = entitylib.character and entitylib.character.RootPart
		if not root or not v or not v.RootPart then return false end
		return (v.RootPart.Position - root.Position).Magnitude <= (AttackRange.Value + 0)
	end

	local function aliveTarget(v)
		if not v or not v.RootPart then return false end
		local char = v.Character
		if not char or not char.Parent then return false end
		if v.Health ~= nil and v.Health <= 0 then return false end
		return true
	end

	task.spawn(function()
		pcall(function()
			local missing = getgenv().NYXMissingModule
			local function hasSend(sc)
				if sc == nil or sc == missing then return false end
				local f = sc.sendServerRequest
				return f ~= nil and f ~= missing
			end
			local sc
			for _ = 1, 100 do
				sc = bedwars.SwordController
				if hasSend(sc) then break end
				task.wait(0.2)
			end
			if not hasSend(sc) then warn('[KA] SwordController.sendServerRequest not found') return end
		end)
	end)

	local function resolveTarget()
		local v = store.KillauraTarget
		if aliveTarget(v) and withinAngle(v) and inReach(v) then
			_graceTarget = v
			_graceUntil = tick() + 0.4
			return v
		end
		if _graceTarget and tick() < _graceUntil then
			local g = _graceTarget
			if aliveTarget(g) and inReach(g) then
				return g
			end
		end
		-- Walls are raycast only for the angled candidates we actually consider, in sort order,
		-- instead of once per entity inside AllPosition. Same result, far fewer rays per attempt.
		local walls = Targets.Walls.Enabled
		local list = entitylib.AllPosition({
			Range = AttackRange.Value + 0,
			Part = 'RootPart',
			Players = Targets.Players.Enabled,
			NPCs = Targets.NPCs.Enabled,
			Limit = 8,
			Sort = sortmethods[Sort.Value] or sortmethods['Distance']
		})
		local root = entitylib.character and entitylib.character.RootPart
		local resolved = nil
		for _, ent in list do
			if withinAngle(ent) then
				if walls and root and entitylib.Wallcheck(root.Position, ent.RootPart.Position, nil, ent) then continue end
				resolved = ent
				break
			end
		end
		return resolved
	end

	local function attemptFire()
		store.kaBlock = 'start'
		-- A sword hit while a bow/other projectile is in hand cancels the shot; the player
		-- picked that item on purpose, so the aura stands down until they switch back.
		if handIsProjectile() and tick() - (store.lastToolUpdate or 0) > 0.5 then store.kaBlock = 'projectile-hand' return false end
		if fhBusy and (workspace:GetServerTimeNow() - (store._fhBusySince or 0)) < 0.10 then store.kaBlock = 'fh-busy' return false end
		
		-- Add small delay after FastHits to prevent ghosting sword hits
		if lastProjectileTime > 0 and (workspace:GetServerTimeNow() - lastProjectileTime) < 0.075 then
			store.kaBlock = 'proj-cooldown'
			return false
		end
		
		local v = resolveTarget()
		if not v then store.kaBlock = 'no-target' return false end

		local sword, meta = getAttackData()
		if not sword then store.kaBlock = 'no-sword' return false end
		if not meta then store.kaBlock = 'no-meta' return false end

		local weaponInst = sword.tool
		pcall(function()
			local inv = replicatedStorage:FindFirstChild('Inventories')
			local mine = inv and inv:FindFirstChild(lplr.Name)
			local w = mine and mine:FindFirstChild(sword.tool.Name)
			if w then weaponInst = w end
		end)

		local char = lplr.Character
		if not char or not char.PrimaryPart then store.kaBlock = 'no-char' return false end
		local tchar = v.Character
		if not tchar or not tchar.Parent then store.kaBlock = 'no-tchar' return false end
		local selfPos = entitylib.character.RootPart.Position
		local targetPos = v.RootPart and v.RootPart.Position
		if not selfPos or not targetPos then store.kaBlock = 'no-pos' return false end
		local dist = (targetPos - selfPos).Magnitude
		if dist > AttackRange.Value + 0 then store.kaBlock = 'out-of-range' return false end

		if AirHit and AirHit.Enabled and AirHitsChance and AirHitsChance.Value < 100 then
			local hum = tchar:FindFirstChildOfClass('Humanoid')
			if hum then
				local inAir = hum.FloorMaterial == Enum.Material.Air
				if not inAir then
					local st = hum:GetState()
					inAir = st == Enum.HumanoidStateType.Jumping or st == Enum.HumanoidStateType.Freefall
				end
				if not inAir then
					local root = tchar.PrimaryPart
					local vy = root and root.AssemblyLinearVelocity.Y or 0
					inAir = math.abs(vy) > 3
				end
				if inAir then
					if math.random(1, 100) > AirHitsChance.Value then store.kaBlock = 'airhit-roll' return false end
				end
			end
		end

		if sword.tool.Name:find('summoner_claw') then
			pcall(function() KaidaController:request(tchar) end)
			store.kaBlock = 'summoner-claw'
			return false
		end

		if not FireAttackRemote(weaponInst, tchar, selfPos, targetPos) then
			store.kaBlock = 'fire-fail'
			markAttackResult(false)
			return false
		end

		pcall(function()
			local syncEvents = bedwars.ClientSyncEvents or (bedwars.Client and bedwars.Client:GetNamespace('Default'))
			local ev = syncEvents and syncEvents.Get and syncEvents:Get('SwordSwing')
			if ev and ev.Fire then ev:Fire({player = lplr}) end
		end)

		local srvNow = workspace:GetServerTimeNow()

		lastAttackTime = tick()
		store.attackReach = (dist * 100) // 1 / 100
		store.attackReachUpdate = tick() + 1

		-- Mark attack as successful for dynamic delay system
		markAttackResult(true)

		kaLastSend = srvNow
		store.kaSent = (store.kaSent or 0) + 1
		store.kaTrackChar = tchar
		local trackHum = tchar:FindFirstChildOfClass('Humanoid')
		store.kaTrackHP = trackHum and trackHum.Health or nil
		store.kaSentWindow = store.kaSentWindow or {n = 0, t = srvNow}
		if srvNow - store.kaSentWindow.t >= 5 then
			local rate = store.kaSentWindow.n / (srvNow - store.kaSentWindow.t)
			store.kaSentWindow = {n = 0, t = srvNow}
			-- diagnostics removed: console stays clean
		end
		store.kaSentWindow.n = store.kaSentWindow.n + 1
		if kaLastSrv > 0 then
			kaLastSrv = kaLastSrv + kaPeriod
			if kaLastSrv < srvNow then
				kaLastSrv = srvNow
			end
		else
			kaLastSrv = srvNow
		end
		kaNextFire = 0

		if bedwars.SwordController then
			bedwars.SwordController.lastAttack = srvNow
		end
		return true
	end

	local function startKillauraFireLoop()
		if killauraFireLoop then return end

		kaPeriod = HIT_PERIOD
		animPeriod = NORMAL_SWORD_SWING_SPEED
		kaNextFire = 0
		kaLastSrv = workspace:GetServerTimeNow() - kaPeriod
		kaLastSend = 0

		-- Diagnostic only: throttle repeated attemptFire errors without changing attack logic.
		local lastAttemptFireError = 0

		killauraFireLoop = task.spawn(function()
			while Killaura and Killaura.Enabled do
				runService.Heartbeat:Wait()

				local updateOk, updateErr = pcall(function()
					local sword, meta = getAttackData()
					if sword and meta then
						kaPeriod = getAttackDelay(meta)
					else
						kaPeriod = HIT_PERIOD
					end
					animPeriod = NORMAL_SWORD_SWING_SPEED
					updatePreciseClock()
					local tc = store.kaTrackChar
					if tc and tc.Parent then
						local hum = tc:FindFirstChildOfClass('Humanoid')
						local hp = hum and hum.Health
						if hp and store.kaTrackHP and hp < store.kaTrackHP - 0.5 then
							store.kaHits = (store.kaHits or 0) + 1
						end
						if hp then store.kaTrackHP = hp end
					else
						store.kaTrackChar = nil
						store.kaTrackHP = nil
					end
				end)
				if not updateOk and (tick() - lastAttemptFireError) >= 2 then
					lastAttemptFireError = tick()
					warn('[Killaura] timing update error: ' .. tostring(updateErr))
				end

				local heartbeatDt = 1 / 60
				local target = kaPeriod - math.min(heartbeatDt * 0.5, kaPeriod * 0.06)
				if (workspace:GetServerTimeNow() - kaLastSrv) >= target then
					local ok, err = pcall(attemptFire)
					if not ok and (tick() - lastAttemptFireError) >= 2 then
						lastAttemptFireError = tick()
						warn('[Killaura] attemptFire error: ' .. tostring(err))
					end
				end
				-- blocker diagnostics removed: console stays clean
			end
		end)
	end

	local function stopKillauraFireLoop()
		if killauraFireLoop then
			pcall(task.cancel, killauraFireLoop)
			killauraFireLoop = nil
		end
		_graceTarget = nil
		_graceUntil = 0
		_fastAcqTime = 0
		_fastAcqRes = nil
		kaNextFire = 0
			kaSync = 0
		kaSyncSrv = 0
		animPeriod = NORMAL_SWORD_SWING_SPEED
	end

	local function getKillauraWrist()
		local camera = gameCamera or workspace.CurrentCamera
		local viewmodel = camera and camera:FindFirstChild('Viewmodel')
		local rightHand = viewmodel and viewmodel:FindFirstChild('RightHand')
		return rightHand and rightHand:FindFirstChild('RightWrist')
	end

	Killaura = vape.Categories.Blatant:CreateModule({
		Name = 'Killaura',
		Function = function(callback)
			if callback then
				lastAttackTime = 0
				lastTargetTime = 0
				lastAnimTime = 0
				store.kaHits = 0
				store.kaSent = 0
				store.kaTrackChar = nil
				store.kaTrackHP = nil
				resetSwordCooldown()
				preciseRemainder = 0
				preciseTimestamp = tick()

				if inputService.TouchEnabled and not preserveSwordIcon then
					pcall(function()
						lplr.PlayerGui.MobileUI['2'].Visible = Limit and Limit.Enabled
					end)
				end

				if FastHits and FastHits.Enabled then
					startAutoShootLoop()
				end

				if UseKits and UseKits.Enabled then
					startUseKitsLoop()
				end

				startKillauraFireLoop()

				if Animation and Animation.Enabled and not (identifyexecutor and table.find({'Argon', 'Delta'}, ({identifyexecutor()})[1])) then
					task.spawn(function()
						local started = false
						repeat
							local wrist = getKillauraWrist()
							local mode = AnimationMode and AnimationMode.Value
							local sequence = mode and anims[mode]
							if not wrist or type(sequence) ~= 'table' or #sequence == 0 then
								if AnimTween then pcall(AnimTween.Destroy, AnimTween) AnimTween = nil end
								if wrist and armC0 then wrist.C0 = armC0 end
								started = false
								task.wait(0.1)
								continue
							end
							if Attacking and not (LegitAura and LegitAura.Enabled) then
								if not armC0 then armC0 = wrist.C0 end
								local first = not started
								started = true
								if mode == 'Random' then
									anims.Random = {{CFrame = CFrame.Angles(math.rad(math.random(1, 360)), math.rad(math.random(1, 360)), math.rad(math.random(1, 360))), Time = 0.12}}
									sequence = anims.Random
								end
								for _, v in sequence do
									if AnimTween then pcall(AnimTween.Destroy, AnimTween) AnimTween = nil end
									local speed = math.max(tonumber(AnimationSpeed and AnimationSpeed.Value) or 1, 0.1)
									AnimTween = tweenService:Create(wrist, TweenInfo.new(first and (AnimationTween and AnimationTween.Enabled and 0.001 or 0.1) or (v.Time / speed), Enum.EasingStyle.Linear), {
										C0 = armC0 * v.CFrame
									})
									local activeTween = AnimTween
									activeTween:Play()
									local waitOk = pcall(function()
										activeTween.Completed:Wait()
									end)
									if not waitOk or AnimTween ~= activeTween or not wrist.Parent then
										break
									end
									first = false
									if (not Killaura.Enabled) or (not Attacking) then break end
								end
							elseif started then
								started = false
								if AnimTween then pcall(AnimTween.Destroy, AnimTween) AnimTween = nil end
								if armC0 then
									AnimTween = tweenService:Create(wrist, TweenInfo.new(AnimationTween and AnimationTween.Enabled and 0.001 or 0.3, Enum.EasingStyle.Exponential), {
										C0 = armC0
									})
									AnimTween:Play()
								end
							end
							if not started then task.wait(1 / 3.5) end
						until (not Killaura.Enabled) or (not Animation.Enabled)
						local wrist = getKillauraWrist()
						if AnimTween then pcall(AnimTween.Destroy, AnimTween) AnimTween = nil end
						if wrist and armC0 then wrist.C0 = armC0 end
					end)
				end

				local _gatherCache = nil
				local _gatherCacheTime = 0
				local function gatherTargets()
					if _gatherCache and (tick() - _gatherCacheTime) < 0.05 then
						return _gatherCache[1], _gatherCache[2]
					end

					local walls = Targets.Walls.Enabled or nil
					local players = Targets.Players.Enabled
					local npcs = Targets.NPCs.Enabled
					local sort = sortmethods[Sort.Value]

					local function buildList(range)
						return entitylib.AllPosition({Range = range, Wallcheck = walls, Part = 'RootPart', Players = players, NPCs = npcs, Limit = 1, Sort = sort})
					end

					local attackPlrs = buildList(AttackRange.Value)
					local swingPlrs = AttackRange.Value == SwingRange.Value and attackPlrs or buildList(SwingRange.Value)
					_gatherCache = {swingPlrs, attackPlrs}
					_gatherCacheTime = tick()
					return swingPlrs, attackPlrs
				end

				local _cachedSwordType = nil
				local _cachedIsClaw = false

				repeat
					-- Update 240Hz precise clock for consistent timing
					updatePreciseClock()

					if AttackCheck and AttackCheck.Enabled then
						local triggered = false
						local stunTime = lplr.Character and lplr.Character:GetAttribute('StunnedUntilTime')
						if stunTime and stunTime > workspace:GetServerTimeNow() then triggered = true end
						if not triggered and kitChecks then
							for _, check in pairs(kitChecks) do
								local ok, res = pcall(check)
								if ok and res then triggered = true break end
							end
						end
						if triggered then
							Attacking = false
							getgenv().Attacking = false
							store.KillauraTarget = nil
							_graceUntil = 0
							task.wait(0.3)
							continue
						end
					end

					local sword, meta = getAttackData()
					if not sword then
						if Attacking then
							Attacking = false
							getgenv().Attacking = false
							store.KillauraTarget = nil
						end
						task.wait(0.05)
						continue
					end

					if vapeTargetInfo and vapeTargetInfo.Targets then
						vapeTargetInfo.Targets.Killaura = nil
					end

					if sword then
						local swordName = sword.tool.Name
						if swordName ~= _cachedSwordType and not fhBusy then
							_cachedSwordType = swordName
							_cachedIsClaw = swordName:find('summoner_claw') ~= nil
							resetSwordCooldown()
						end
						local isClaw = _cachedIsClaw

						local selfRoot = entitylib.character and entitylib.character.RootPart
						if not selfRoot or not selfRoot.Parent then
							Attacking = false
							getgenv().Attacking = false
							store.KillauraTarget = nil
							_graceTarget = nil
							_graceUntil = 0
							task.wait(0.1)
							continue
						end
						local selfpos = selfRoot.Position
						local flatLV = selfRoot.CFrame.LookVector * Vector3.new(1, 0, 1)
						local localfacing = flatLV.Magnitude > 0.001 and flatLV.Unit or selfRoot.CFrame.RightVector
						local maxAngle = math.rad(AngleSlider.Value) / 2
						local swingPlrs, attackPlrs = gatherTargets()

						local function passesAngle(v)
							if AngleSlider.Value >= 360 then return true end
							local flat = (v.RootPart.Position - selfpos) * Vector3.new(1, 0, 1)
							if flat.Magnitude <= 1.0 then return true end
							return math.acos(math.clamp(localfacing:Dot(flat.Unit), -1, 1)) <= maxAngle
						end

						local hasValidSwingTargets = false
						local hasValidAttackTargets = false
						local chosen = nil

						for _, v in swingPlrs do
							if passesAngle(v) then
								hasValidSwingTargets = true
								break
							end
						end

						for _, v in attackPlrs do
							if passesAngle(v) then
								hasValidAttackTargets = true
								chosen = v
								break
							end
						end

						if hasValidSwingTargets or hasValidAttackTargets then
							lastTargetTime = tick()
						end

						if not hasValidSwingTargets and not hasValidAttackTargets and Attacking then
							Attacking = false
							getgenv().Attacking = false
							store.KillauraTarget = nil
						end

						local shouldSwing = hasValidSwingTargets or hasValidAttackTargets
						local isLegitAura = LegitAura and LegitAura.Enabled

						if shouldSwing or isLegitAura then
							if not fhBusy and not regentBusy and store.hand and store.hand.tool ~= sword.tool and (tick() - (store._kaSwitch or 0)) > 0.25 then
								store._kaSwitch = tick()
								switchItem(sword.tool, 0)
							end

							if chosen then
								if not Attacking then
									Attacking = true
									getgenv().Attacking = true
								end
								store.KillauraTarget = chosen
								targetinfo.Targets[chosen] = tick() + 1

								if vapeTargetInfo and vapeTargetInfo.Targets then
									vapeTargetInfo.Targets.Killaura = {
										Humanoid = {Health = chosen.Health, MaxHealth = chosen.MaxHealth},
										Player = chosen.Player
									}
								end
							end

							if not isClaw and (tick() - lastAnimTime) >= animPeriod then
								local allowSwingAnim = not (LegitAura and LegitAura.Enabled)
								if allowSwingAnim then
									-- Fixed animation period to prevent stuttering/doubling
									local swingSpeed = (SwingTime and SwingTime.Enabled)
										and math.max(SwingTimeSlider.Value, 0.11)
										or animPeriod
									lastAnimTime = tick()
									AnimDelay = tick() + swingSpeed
									if isOnTinker() then
										playTinkerSwing()
									end
									triggerFirstPersonSwing(meta)
									if vape.ThreadFix and setthreadidentity then
										pcall(setthreadidentity, 8)
									end
								end
							end
						end
					end

					task.wait()
				until not Killaura.Enabled
			else
				stopAutoShootLoop()
				stopKillauraFireLoop()
				stopUseKitsLoop()
				store.KillauraTarget = nil
				if inputService.TouchEnabled then
					pcall(function() lplr.PlayerGui.MobileUI['2'].Visible = true end)
				end
				Attacking = false
				getgenv().Attacking = false
				if vapeTargetInfo and vapeTargetInfo.Targets then
					vapeTargetInfo.Targets.Killaura = nil
				end
				if AnimTween then pcall(AnimTween.Destroy, AnimTween) AnimTween = nil end
				local wrist = getKillauraWrist()
				if wrist and armC0 then
					pcall(function()
						local restoreTween = tweenService:Create(wrist, TweenInfo.new(AnimationTween and AnimationTween.Enabled and 0.001 or 0.3, Enum.EasingStyle.Exponential), {
							C0 = armC0
						})
						restoreTween:Play()
					end)
				end
				armC0 = nil
			end
		end,
	})

	pcall(function()
		local PSI = Killaura:CreateToggle({
			Name = 'Preserve Sword Icon',
			Function = function(callback)
				preserveSwordIcon = callback
			end,
			Default = true
		})
		PSI.Object.Visible = inputService.TouchEnabled
	end)

	Targets = Killaura:CreateTargets({
		Players = true,
		NPCs = true
	})

	SwingRange = Killaura:CreateSlider({
		Name = 'Swing range',
		Min = 1,
		Max = 40,
		Default = 22,
		Suffix = function(val) return val == 1 and 'stud' or 'studs' end
	})
	AttackRange = Killaura:CreateSlider({
		Name = 'Attack range',
			Min = 1,
			Max = 22,
			Default = 22,
			Suffix = function(val) return val == 1 and 'stud' or 'studs' end
	})
	AngleSlider = Killaura:CreateSlider({
		Name = 'Max angle',
		Min = 1,
		Max = 360,
		Default = 360
	})
	Sort = Killaura:CreateDropdown({
		Name = 'Target Mode',
		List = {'Cursor', 'Angle'}
	})
	SwingTime = Killaura:CreateToggle({
		Name = 'Custom Swing Time',
		Function = function(callback)
			if SwingTimeSlider then
				SwingTimeSlider.Object.Visible = callback
			end
		end,
		Tooltip = 'change ur swing time'
	})
	SwingTimeSlider = Killaura:CreateSlider({
		Name = 'Custom Swing Speed',
		Min = 0,
		Max = 1,
		Default = 0,
		Decimal = 100,
		Visible = false
	})
	Animation = Killaura:CreateToggle({
		Name = 'Custom Animation',
		Function = function(callback)
			if AnimationMode then AnimationMode.Object.Visible = callback end
			if AnimationTween then AnimationTween.Object.Visible = callback end
			if AnimationSpeed then AnimationSpeed.Object.Visible = callback end
			if Killaura.Enabled then
				Killaura:Toggle()
				Killaura:Toggle()
			end
		end
	})
	local animnames = {}
	for i in anims do table.insert(animnames, i) end
	AnimationMode = Killaura:CreateDropdown({
		Name = 'Animation Mode',
		List = animnames,
		Darker = true,
		Visible = false
	})
	AnimationSpeed = Killaura:CreateSlider({
		Name = 'Animation Speed',
		Min = 0.1,
		Max = 2,
		Default = 1,
			Decimal = 10,
		Darker = true,
		Visible = false
	})
	AnimationTween = Killaura:CreateToggle({Name = 'No Tween', Darker = true, Visible = false})

	Limit = Killaura:CreateToggle({
		Name = 'Limit to items',
		Function = function(callback)
			if inputService.TouchEnabled and Killaura.Enabled then
				pcall(function() lplr.PlayerGui.MobileUI['2'].Visible = callback end)
			end
		end,
		Tooltip = 'checks if you got sword held out'
	})
	LegitAura = Killaura:CreateToggle({
		Name = 'Swing only',
		Tooltip = 'only swings when yu swing manually'
	})
	AirHit = Killaura:CreateToggle({
		Name = 'Air Hits',
		Default = true,
		Tooltip = 'hit people in the air',
		Function = function(callback)
			if AirHitsChance then
				AirHitsChance.Object.Visible = callback
			end
		end
	})
	AirHitsChance = Killaura:CreateSlider({
		Name = 'Air Hits Chance',
		Min = 0,
		Max = 100,
		Default = 100,
		Suffix = '%',
		Decimal = 5,
		Darker = true,
		Visible = false
	})

	local _watchersActive = true
	Killaura:Clean(function()
		_watchersActive = false
	end)

	task.spawn(function()
		local wasAvailable = false
		local availSince = 0
		while _watchersActive and vape.Loaded do
			task.wait(0.05)
			if bedwars.AbilityController then
				local ok, nowAvailable = pcall(bedwars.AbilityController.canUseAbility, bedwars.AbilityController, 'rebellion_shield')
				if ok then
					nowAvailable = nowAvailable == true
					if nowAvailable and not wasAvailable then
						availSince = tick()
					end
					if wasAvailable and not nowAvailable and availSince > 0 and (tick() - availSince) > 1 then
						store.silasAbilityTime = tick()
					end
					wasAvailable = nowAvailable
				end
			end
		end
	end)

	task.spawn(function()
		local wasStomp, wasKick = false, false
		local stompSince, kickSince = 0, 0
		while _watchersActive and vape.Loaded do
			task.wait(0.05)
			if bedwars.AbilityController then
				local ok1, nowStomp = pcall(bedwars.AbilityController.canUseAbility, bedwars.AbilityController, 'BLOCK_STOMP')
				local ok2, nowKick = pcall(bedwars.AbilityController.canUseAbility, bedwars.AbilityController, 'BLOCK_KICK')
				if ok1 then
					nowStomp = nowStomp == true
					if nowStomp and not wasStomp then stompSince = tick() end
					if wasStomp and not nowStomp and stompSince > 0 and (tick() - stompSince) > 1 then
						store.terraStompTime = tick()
					end
					wasStomp = nowStomp
				end
				if ok2 then
					nowKick = nowKick == true
					if nowKick and not wasKick then kickSince = tick() end
					if wasKick and not nowKick and kickSince > 0 and (tick() - kickSince) > 1 then
						store.terraKickTime = tick()
					end
					wasKick = nowKick
				end
			end
		end
	end)

	kitChecks = {
		['Sigrid'] = function() return entitylib.isAlive and lplr.Character and lplr.Character:FindFirstChild('elk') ~= nil end,
	}

	AttackCheck = Killaura:CreateToggle({
		Name = 'Attack Check',
		Tooltip = 'checks if attacking ina legit way',
		Default = false
	})

	HitregMode = Killaura:CreateDropdown({
		Name = 'Hitreg Mode',
		List = {'Consistent', 'High Hit Reg', 'Legit'},
		Default = 'Consistent',
		Function = function(val)
			if DynamicDelaySlider and DynamicDelaySlider.Object then
				DynamicDelaySlider.Object.Visible = (val == 'Legit' or val == 'Dynamic')
			end
		end
	})

	DynamicDelaySlider = Killaura:CreateSlider({
		Name = 'Dynamic Delay',
			Min = 1,
			Max = 100,
			Default = 100,
			Suffix = '%',
		Darker = true,
		Visible = false,
		Tooltip = 'Controls hit spacing dynamically (1-100%) when Legit mode is selected'
	})

	UseKits = Killaura:CreateToggle({
		Name = 'Use Kits',
		Default = true,
		Tooltip = 'Automatically detects kit and uses abilities in combat',
		Function = function(callback)
			if callback then
				if Killaura.Enabled then
					startUseKitsLoop()
				end
			else
				stopUseKitsLoop()
			end
		end
	})

	FastHits = Killaura:CreateToggle({
		Name = 'Fast Hits',
		Default = false,
		Tooltip = 'use projectiles mid pvp',
		Function = function(call)
			if FireRate then FireRate.Object.Visible = call end
			if LegitSwitch then LegitSwitch.Object.Visible = call end
			if Arrows then Arrows.Object.Visible = call end
			if Gloops then Gloops.Object.Visible = call end
			if GloopCooldown then GloopCooldown.Object.Visible = call and (Gloops and Gloops.Enabled) end
			if Fireballs then Fireballs.Object.Visible = call end
			if FireballCooldown then FireballCooldown.Object.Visible = call and (Fireballs and Fireballs.Enabled) end
			if call then
				if Killaura and Killaura.Enabled then
					startAutoShootLoop()
				end
			else
				stopAutoShootLoop()
			end
		end
})
	FireRate = Killaura:CreateSlider({
		Name = 'Fire rate',
		Suffix = 'seconds',
		Min = 0,
		Max = 2,
		Decimal = 100,
		Darker = true,
		Visible = false,
		Default = 0.05,
		Tooltip = 'Cooldown between FastHits shots'
	})
	LegitSwitch = Killaura:CreateToggle({
		Name = 'Legit Switch',
		Default = false,
		Darker = true,
		Visible = false,
		Tooltip = 'switches to projectiles to lok legit'
	})
	Arrows = Killaura:CreateToggle({
		Name = 'Arrows',
		Default = true,
		Darker = true,
			Visible = false,
		Tooltip = 'use projectile items that uses arrows'
	})
	Gloops = Killaura:CreateToggle({
		Name = 'Gloops',
		Default = false,
		Darker = true,
			Visible = false,
		Tooltip = 'auto gloops real players in combat',
		Function = function(callback)
			if GloopCooldown then
				GloopCooldown.Object.Visible = callback
			end
		end
	})
	GloopCooldown = Killaura:CreateSlider({
		Name = 'Gloop Cooldown',
		Min = 1,
		Max = 15,
		Default = 10,
		Suffix = 's',
		Darker = true,
		Visible = false
	})
	Fireballs = Killaura:CreateToggle({
		Name = 'Fireballs',
		Default = false,
		Darker = true,
		Visible = false,
		Tooltip = 'auto throws fireballs at targets in combat',
		Function = function(callback)
			if FireballCooldown then
				FireballCooldown.Object.Visible = callback
			end
		end
	})
	FireballCooldown = Killaura:CreateSlider({
		Name = 'Fireball Cooldown',
		Min = 1,
			Max = 20,
		Default = 8,
		Suffix = 's',
		Darker = true,
		Visible = false
	})

	task.defer(function()
		if AirHit and AirHit.Enabled and AirHitsChance and AirHitsChance.Object then
			AirHitsChance.Object.Visible = true
		end
		if FastHits and FastHits.Enabled then
			if FireRate then FireRate.Object.Visible = true end
			if LegitSwitch then LegitSwitch.Object.Visible = true end
			if Arrows then Arrows.Object.Visible = true end
			if Gloops then Gloops.Object.Visible = true end
			if GloopCooldown then GloopCooldown.Object.Visible = (Gloops and Gloops.Enabled) end
			if Fireballs then Fireballs.Object.Visible = true end
			if FireballCooldown then FireballCooldown.Object.Visible = (Fireballs and Fireballs.Enabled) end
		end
	end)
end)
run(function()
	local BedPatcher
	local Mode
	local Whitelist
	local PlaceRange
	local Radius
	local Wool
	local Switch
	local NoAnimation
	local Limit
	local Layout, Adjacent = {}, {}
	local PlaceAnimation = 0
	pcall(function()
		PlaceAnimation = bedwars.BlockController:getAnimationController():getAssetId(0)
	end)
	local Placing, Old = false

	local function bedPosition(bed)
		if bed:IsA('BasePart') then
			return bed.Position
		end
		local ok, pivot = pcall(bed.GetPivot, bed)
		return ok and pivot and pivot.Position or nil
	end

	for _, v in Enum.NormalId:GetEnumItems() do
		table.insert(Adjacent, Vector3.FromNormalId(v) * 3)
	end

	local function getPlacedBlock(position)
		if not position then return end
		local rounded = bedwars.BlockController:getBlockPosition(position)
		local ok, block = pcall(function()
			return bedwars.BlockController:getStore():getBlockAt(rounded)
		end)
		return ok and block or nil, rounded
	end

	local function getBedNear()
		local root = entitylib.isAlive and entitylib.character and entitylib.character.RootPart or nil
		local localPosition = root and root.Position or Vector3.zero
		local best, bestDist
		for _, v in collectionService:GetTagged('bed') do
			local bedPos = bedPosition(v)
			if bedPos then
				local dist = (localPosition - bedPos).Magnitude
				if dist < (PlaceRange.Value + Radius.Value) and (not bestDist or dist < bestDist)
					and v:GetAttribute('Team'..(lplr:GetAttribute('Team') or -1)..'NoBreak') then
					best, bestDist = v, dist
				end
			end
		end
		return best
	end

	local function getBlock(itemType)
		if Limit.Enabled then
			local hand = store.hand and store.hand.toolType == 'block' and store.hand.tool or nil
			if hand and (not Wool.Enabled or hand.Name:find('wool')) and table.find(Whitelist.ListEnabled, hand.Name:find('wool') and 'wool' or hand.Name) then
				return hand.Name, hand
			end
			return nil
		end

		local inv = store.inventory and store.inventory.inventory
		if not inv then return nil end
		local best, health
		for _, v in inv.items do
			local block = bedwars.ItemMeta[v.itemType] and bedwars.ItemMeta[v.itemType].block
			if not block or (Wool.Enabled and not v.itemType:find('wool')) then continue end
			if not table.find(Whitelist.ListEnabled, v.itemType:find('wool') and 'wool' or v.itemType) then continue end
			if v.itemType == itemType then
				return v.itemType, v.tool
			end
			if not health or (block.health or 0) > health then
				best, health = v, block.health or 0
			end
		end
		return best and best.itemType or nil, best and best.tool or nil
	end

	local function scanBed(bed)
		table.clear(Layout)
		local center = bedPosition(bed)
		if not center then
			return
		end
		for _, v in store.blocks do
			if v:IsA('BasePart') and not v:HasTag('bed') and (v.Position - center).Magnitude <= Radius.Value then
				Layout[v.Position] = v.Name
			end
		end

		local holes = {}
		for position, name in Layout do
			for _, offset in Adjacent do
				local cell = position + offset
				if Layout[cell] or holes[cell] or getPlacedBlock(cell) then
					continue
				end

				local walls = 0
				for _, side in Adjacent do
					if Layout[cell + side] then
						walls += 1
					end
				end

				if walls >= 4 then
					holes[cell] = name
				end
			end
		end

		for position, name in holes do
			Layout[position] = name
		end
	end

	BedPatcher = vape.Categories.World:CreateModule({
		Name = 'BedPatcher',
		Function = function(callback)
			if callback then
				local bed
				Old = bedwars.AnimationUtil.playAnimation
				bedwars.AnimationUtil.playAnimation = function(self, player, assetId, config)
					if Placing and NoAnimation.Enabled and assetId == PlaceAnimation then
						return
					end
					return Old(self, player, assetId, config)
				end

				BedPatcher:Clean(collectionService:GetInstanceAddedSignal('block'):Connect(function(block)
					local bedPos = bed and bedPosition(bed) or nil
					if bedPos and block:IsA('BasePart') and not block:HasTag('bed') and (block.Position - bedPos).Magnitude <= Radius.Value then
						Layout[block.Position] = block.Name
					end
				end))

				BedPatcher:Clean(vapeEvents.BreakBlockEvent.Event:Connect(function(blockTable)
					local player = blockTable.player
					if player and (player == lplr or player:GetAttribute('Team') == lplr:GetAttribute('Team')) then
						local ref = blockTable.blockRef and blockTable.blockRef.blockPosition
						if ref then
							local world = ref * 3
							if not Layout[world] and Layout[ref] then
								world = ref
							end
							Layout[world] = nil
						end
					end
				end))

				local lastScan, failures = 0, 0
				repeat
					local found = getBedNear()
					if found ~= bed then
						bed = found
						failures = 0
						if bed then
							scanBed(bed)
							lastScan = tick()
						else
							table.clear(Layout)
						end
					end

					if bed and entitylib.isAlive then
						local root = entitylib.character and entitylib.character.RootPart or nil
						if not root then
							task.wait()
							continue
						end
						local localPosition = root.Position
						local holes = {}

						for position, name in Layout do
							if (localPosition - position).Magnitude <= PlaceRange.Value and not getPlacedBlock(position) then
								table.insert(holes, {position, name})
							end
						end

						table.sort(holes, function(a, b)
							return (a[1] - localPosition).Magnitude < (b[1] - localPosition).Magnitude
						end)

						for _, v in holes do
							if not BedPatcher.Enabled then break end
							local position, itemType = unpack(v)
							if getPlacedBlock(position) then
								continue
							end

							local item, tool = getBlock(itemType)
							if not item then
								break
							end

							if Switch.Enabled and tool and switchItem(tool, 0) then
								task.wait()
							end

							Placing = true
							local ok = pcall(bedwars.placeBlock, position, item)
							Placing = false
							if ok then
								failures = 0
							else
								failures += 1
							end
							task.wait(1 / (bedwars.SharedConstants.BLOCK_PLACE_CPS or 50))
						end

						if failures >= 5 then
							failures = 0
							scanBed(bed)
							lastScan = tick()
						end
					elseif not bed and Mode.Value == 'On Key' then
						notif('BedPatcher', 'Unable to locate bed', 5)
						BedPatcher:Toggle()
						break
					end

					if bed and tick() - lastScan > 4 then
						scanBed(bed)
						lastScan = tick()
					end

					task.wait(0.25)
					if Mode.Value == 'On Key' then
						BedPatcher:Toggle()
						break
					end
				until not BedPatcher.Enabled
			else
				bedwars.AnimationUtil.playAnimation = Old
				Placing = false
			end
		end,
		Tooltip = 'Puts back the blocks an enemy broke out of your bed defense.'
	})
	Mode = BedPatcher:CreateDropdown({
		Name = 'Mode',
		List = {'Toggle', 'On Key'}
	})
	Whitelist = BedPatcher:CreateTextList({
		Name = 'Whitelist',
		Default = {'wool', 'obsidian'}
	})
	PlaceRange = BedPatcher:CreateSlider({
		Name = 'Place Range',
		Min = 1,
		Max = 60,
		Default = 15
	})
	Radius = BedPatcher:CreateSlider({
		Name = 'Defense Radius',
		Min = 3,
		Max = 30,
		Default = 15,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end,
		Tooltip = 'How far out from the bed still counts as your defense'
	})
	Wool = BedPatcher:CreateToggle({Name = 'Wool only', Tooltip = 'Only uses wools to patch.'})
	Switch = BedPatcher:CreateToggle({Name = 'Auto Switch'})
	NoAnimation = BedPatcher:CreateToggle({
		Name = 'No Animation',
		Tooltip = 'Hides the arm swing every patched block would otherwise play'
	})
	Limit = BedPatcher:CreateToggle({Name = 'Limit to item'})
end)

run(function()
	local ProjectileAura
	local Targets
	local Range
	local List
	local HandCheck
	local FireSpeed
    local rayCheck = cloneRaycast()
	local projectileRemote = {InvokeServer = function() end}
	local FireDelays = {}
	task.spawn(function()
		projectileRemote = replicatedStorage:WaitForChild('rbxts_include'):WaitForChild('node_modules'):WaitForChild('@rbxts'):WaitForChild('net'):WaitForChild('out'):WaitForChild('_NetManaged'):WaitForChild('ProjectileFire')
	end)
	
	local function getAmmo(check)
		for _, item in store.inventory.inventory.items do
			if check.ammoItemTypes and table.find(check.ammoItemTypes, item.itemType) then
				return item.itemType
			end
		end
	end
	
	local function getProjectiles()
		local items = {}
		for _, item in store.inventory.inventory.items do
			local proj = bedwars.ItemMeta[item.itemType].projectileSource
			local ammo = proj and getAmmo(proj)
			if ammo and table.find(List.ListEnabled, ammo) then
				table.insert(items, {
					item,
					ammo,
					proj.projectileType(ammo),
					proj
				})
			end
		end
		return items
	end
	
	ProjectileAura = vape.Categories.Blatant:CreateModule({
		Name = 'ProjectileAura',
		Function = function(callback)
			if callback then
				repeat
					local holdingCrossbow = store.hand and store.hand.tool and store.hand.tool.Name:find('crossbow')
					local holdingBow = store.hand and store.hand.tool and store.hand.tool.Name:find('bow')
					
					if HandCheck.Enabled and not holdingCrossbow and not holdingBow then
						task.wait(0.1)
						continue
					end
					
					if (workspace:GetServerTimeNow() - bedwars.SwordController.lastAttack) > 0.5 then
						local ent = entitylib.EntityPosition({
							Part = 'RootPart',
							Range = Range.Value,
							Players = Targets.Players.Enabled,
							NPCs = Targets.NPCs.Enabled,
							Wallcheck = Targets.Walls.Enabled
						})
	
						if ent then
							local pos = entitylib.character.RootPart.Position
							for _, data in getProjectiles() do
								local item, ammo, projectile, itemMeta = unpack(data)
								if (FireDelays[item.itemType] or 0) < tick() then
									rayCheck.FilterDescendantsInstances = {workspace.Map}
									local meta = bedwars.ProjectileMeta[projectile]
									local projSpeed, gravity = meta.launchVelocity, meta.gravitationalAcceleration or 196.2
									local lifetime = tonumber(meta.predictionLifetimeSec) or tonumber(meta.lifetimeSec) or (projSpeed > 0 and math.min(3, 120 / projSpeed) or 3)
									local entGravity = workspace.Gravity
									local balloons = ent.Character and ent.Character:GetAttribute('InflatedBalloons')
									if balloons and balloons > 0 then
										entGravity = balloonGravity(balloons, ent.Character)
									end
									local entVel = ent.RootPart.AssemblyLinearVelocity or ent.RootPart.Velocity or Vector3.zero
									local entAirborne = (ent.Humanoid and ent.Humanoid.FloorMaterial == Enum.Material.Air) or math.abs(entVel.Y) > 0.01
									local origin = pos + Vector3.new(0, 1.5, 0)
									local myChar = lplr.Character
									local hand = myChar and (myChar:FindFirstChild('RightHand') or myChar:FindFirstChild('Right Arm'))
									if hand then
										origin = hand.Position
									end
									local charge = tonumber(itemMeta and itemMeta.maxStrengthChargeSec) or 1
									local calc = prediction.SolveTrajectory(origin, projSpeed, gravity, ent.RootPart.Position, entVel, entGravity, ent.HipHeight, ent.Jumping and 42.6 or nil, rayCheck, entAirborne, ent.RootPart.Position, ent.RootPart, nil, true)
									if calc then
										targetinfo.Targets[ent] = tick() + 1
										local switched = switchItem(item.tool)
	
										task.spawn(function()
											local bow = bedwars.BowConstantsTable or {}
											local dir = (calc - origin).Unit
											local shootPosition = (CFrame.new(origin, origin + dir) * CFrame.new(-(bow.RelX or 0.8), -(bow.RelY or -0.6), -(bow.RelZ or 0))).Position + dir * 2
											local id = httpService:GenerateGUID(true)

											-- The server drops a shot whose tool it has not equipped yet, so wait
											-- for the inventory to confirm the hand instead of a fixed sleep.
											if switched then
												local deadline = tick() + 0.35
												while tick() < deadline do
													local handTool = store.hand and store.hand.tool
													if handTool and (handTool == item.tool or handTool.Name == item.tool.Name) then break end
													task.wait()
												end
											end
											
											if holdingCrossbow then
												bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_CROSSBOW_FIRE)
												bedwars.GameAnimationUtil:playAnimation(lplr, bedwars.AnimationType.CROSSBOW_FIRE)
											elseif holdingBow then
												bedwars.ViewmodelController:playAnimation(bedwars.AnimationType.FP_CROSSBOW_FIRE)
												bedwars.GameAnimationUtil:playAnimation(lplr, bedwars.AnimationType.BOW_FIRE)
											else
												local shootAnim = bedwars.ItemMeta[item.tool.Name].thirdPerson and bedwars.ItemMeta[item.tool.Name].thirdPerson.shootAnimation
												if shootAnim then
													bedwars.GameAnimationUtil:playAnimation(lplr, shootAnim)
												end
											end
											
											bedwars.ProjectileController:createLocalProjectile(meta, ammo, projectile, shootPosition, id, dir * projSpeed, {drawDurationSec = charge, drawDurationSeconds = charge})
											local res = projectileRemote:InvokeServer(item.tool, ammo, projectile, shootPosition, pos, dir * projSpeed, id, {drawDurationSec = charge, drawDurationSeconds = charge, shotId = httpService:GenerateGUID(false)}, workspace:GetServerTimeNow() - 0.045)
											if not res then
												FireDelays[item.itemType] = tick()
											else
												pcall(prediction.trackShot, ent.RootPart)
												local shoot = itemMeta.launchSound
												shoot = shoot and shoot[math.random(1, #shoot)] or nil
												if shoot then
													bedwars.SoundManager:playSound(shoot)
												end
											end
										end)
	
										FireDelays[item.itemType] = tick() + ((tonumber(itemMeta.fireDelaySec) or 0.5) / FireSpeed.Value)
										if switched then
											task.wait(0.05)
										end
									end
								end
							end
						end
					end
					task.wait(0.05)
				until not ProjectileAura.Enabled
			end
		end,
		Tooltip = 'Shoots people around you with viewmodel animations'
	})
	Targets = ProjectileAura:CreateTargets({
		Players = true,
		Walls = true
	})
	List = ProjectileAura:CreateTextList({
		Name = 'Projectiles',
		Default = {'arrow', 'snowball'}
	})
	Range = ProjectileAura:CreateSlider({
		Name = 'Range',
		Min = 1,
		Max = 50,
		Default = 50,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	FireSpeed = ProjectileAura:CreateSlider({
		Name = 'Fire Speed',
		Min = 0.5,
		Max = 3,
		Default = 1,
		Decimal = 10,
	})
	HandCheck = ProjectileAura:CreateToggle({
		Name = 'Hand Check',
		Default = false,
		Tooltip = 'Only shoot when holding a bow or crossbow'
	})
end)

run(function()
	local Speed
	local Mode
	local Value
	local WallCheck
	local AutoJump
	local AlwaysJump
	local savedImpulseTime
	local rayCheck = cloneRaycast()
	rayCheck.RespectCanCollide = true
	rayCheck.FilterDescendantsInstances = {lplr.Character, gameCamera}
	
	Speed = vape.Categories.Blatant:CreateModule({
		Name = 'Speed',
		Function = function(callback)
			frictionTable.Speed = callback or nil
			updateVelocity()
			pcall(function()
				debug.setconstant(bedwars.WindWalkerController.updateSpeed, 7, callback and 'constantSpeedMultiplier' or 'moveSpeedMultiplier')
			end)
	
			if callback then
				if savedImpulseTime == nil then
					local sekc = bedwars.StatefulEntityKnockbackController
					savedImpulseTime = sekc and sekc.lastImpulseTime
				end
				Speed:Clean(function()
					pcall(function()
						bedwars.StatefulEntityKnockbackController.lastImpulseTime = (savedImpulseTime ~= nil and savedImpulseTime ~= math.huge) and savedImpulseTime or time()
					end)
					savedImpulseTime = nil
					pcall(function()
						if entitylib.isAlive then
							local root = entitylib.character.RootPart
							root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
						end
					end)
					pcall(function()
						bedwars.SprintController:setSpeed(bedwars.SprintController:isSprinting() and 20 or 14)
					end)
				end)
				Speed:Clean(runService.PreSimulation:Connect(function(dt)
					if not Speed.Enabled then return end
					local sekc = bedwars.StatefulEntityKnockbackController
					if sekc then sekc.lastImpulseTime = math.huge end
					if entitylib.isAlive then
						if not (Fly and Fly.Enabled) and not (LongJump and LongJump.Enabled) then
							bedwars.SprintController:setSpeed(Mode.Value == 'CFrame' and 20 or Value.Value)
							if Mode.Value == 'CFrame' then
								local state = entitylib.character.Humanoid:GetState()
								if state == Enum.HumanoidStateType.Climbing then return end
			
								local root, velo = entitylib.character.RootPart, getSpeed()
								local moveDirection = AntiFallDirection or entitylib.character.Humanoid.MoveDirection
								local destination = (moveDirection * math.max(Value.Value - velo, 0) * dt)
			
								if WallCheck.Enabled then
									rayCheck.CollisionGroup = root.CollisionGroup
									local ray = workspace:Raycast(root.Position, destination, rayCheck)
									if ray then
										destination = ((ray.Position + ray.Normal) - root.Position)
									end
								end
			
								root.CFrame += destination
								root.AssemblyLinearVelocity = (moveDirection * velo) + Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
								if AutoJump.Enabled and (state == Enum.HumanoidStateType.Running or state == Enum.HumanoidStateType.Landed) and moveDirection ~= Vector3.zero and (Attacking or AlwaysJump.Enabled) then
									entitylib.character.Humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
								end
							end
						end
					end
				end))
			else
				pcall(function()
					bedwars.StatefulEntityKnockbackController.lastImpulseTime = (savedImpulseTime ~= nil and savedImpulseTime ~= math.huge) and savedImpulseTime or time()
				end)
				savedImpulseTime = nil
				pcall(function()
					if entitylib.isAlive then
						local root = entitylib.character.RootPart
						root.AssemblyLinearVelocity = Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
					end
				end)
				pcall(function()
					bedwars.SprintController:setSpeed(bedwars.SprintController:isSprinting() and 20 or 14)
				end)
			end
		end,
		ExtraText = function()
			return 'Heatseeker'
		end,
		Tooltip = 'increases your movement with various methods.'
	})
	Mode = Speed:CreateDropdown({
		Name = 'Method',
		List = {'Bedwars', 'CFrame'},
		Default = 'CFrame'
	})
	Value = Speed:CreateSlider({
		Name = 'Speed',
		Min = 1,
		Max = 23,
		Default = 23,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	WallCheck = Speed:CreateToggle({
		Name = 'Wall Check',
		Default = true
	})
	AutoJump = Speed:CreateToggle({
		Name = 'AutoJump',
		Function = function(callback)
			AlwaysJump.Object.Visible = callback
		end
	})
	AlwaysJump = Speed:CreateToggle({
		Name = 'Always Jump',
		Visible = false,
		Darker = true
	})
end)

run(function()
    local BCR
    local Value
    local Tables
    local oldCPS = 12

    -- Every copy of the constant the client placer might read, so a cached or duplicated table
    -- does not keep the old pace alive.
    local function collectTables()
        local found, seen = {}, {}
        local function add(t)
            if type(t) == 'table' and not seen[t] then
                seen[t] = true
                table.insert(found, t)
            end
        end
        local ok, constants = pcall(function()
            return require(replicatedStorage.TS['shared-constants'])
        end)
        if ok and type(constants) == 'table' then
            add(constants.CpsConstants)
        end
        add(bedwars.CpsConstants)
        add(bedwars.SharedConstants)
        add(bedwars.SharedConstants and bedwars.SharedConstants.CpsConstants)
        return found
    end

    local function wantedCPS()
        return Value.Value == 0 and 9e9 or Value.Value
    end

    local function applyCPS(cps)
        if not Tables then
            Tables = collectTables()
            if #Tables == 0 then
                Tables = nil
                return false
            end
            oldCPS = tonumber(Tables[1].BLOCK_PLACE_CPS) or oldCPS
        end
        for _, t in Tables do
            t.BLOCK_PLACE_CPS = cps
        end
        return true
    end

    BCR = vape.Categories.Blatant:CreateModule({
        Name = "BlockCPSRemover",
        Function = function(callback)
            if callback then
                if not applyCPS(wantedCPS()) then
                    task.spawn(function()
                        for _ = 1, 20 do
                            task.wait(0.25)
                            if not BCR.Enabled then return end
                            if applyCPS(wantedCPS()) then break end
                        end
                    end)
                end

                if isMobile then
                    for _, v in {'2', '5'} do
                        pcall(function()
                            BCR:Clean(lplr.PlayerGui.MobileUI[v].MouseButton1Down:Connect(function()
                                applyCPS(wantedCPS())
                            end))
                        end)
                    end
                end

                task.spawn(function()
                    while BCR.Enabled do
                        if Tables then
                            local want = wantedCPS()
                            for _, t in Tables do
                                if t.BLOCK_PLACE_CPS ~= want then
                                    t.BLOCK_PLACE_CPS = want
                                end
                            end
                        else
                            applyCPS(wantedCPS())
                        end
                        task.wait(0.3)
                    end
                end)
            else
                applyCPS(oldCPS or 12)
            end
        end,
        Tooltip = 'Raises the block place limit so fast building stops eating clicks; 0 on the slider removes it'
    })

    Value = BCR:CreateSlider({
        Name = "CPS Limit",
        Suffix = function(v)
            return v == 0 and 'CPS (unlimited)' or 'CPS'
        end,
        Default = 0,
        Min = 0,
        Max = 100,
        Function = function()
            if BCR.Enabled then
                applyCPS(wantedCPS())
            end
        end,
    })
end)

run(function()
	local Value
	local CameraDir
	local start
	local JumpTick, JumpSpeed, Direction = tick(), 0
	local projectileRemote = {InvokeServer = function() end}
	task.spawn(function()
		projectileRemote = replicatedStorage:WaitForChild('rbxts_include'):WaitForChild('node_modules'):WaitForChild('@rbxts'):WaitForChild('net'):WaitForChild('out'):WaitForChild('_NetManaged'):WaitForChild('ProjectileFire')
	end)
	local handGunRemote = {InvokeServer = function() end}
	task.spawn(function()
		handGunRemote = game:GetService("ReplicatedStorage"):WaitForChild("rbxts_include"):WaitForChild("node_modules"):WaitForChild("@rbxts"):WaitForChild("net"):WaitForChild("out"):WaitForChild("_NetManaged"):WaitForChild("HandGunFireRequest")
	end)
	
	local function launchProjectile(item, pos, proj, speed, dir)
		if not pos then return end
	
		pos = pos - dir * 0.1
		local shootPosition = (CFrame.lookAlong(pos, Vector3.new(0, -speed, 0)) * CFrame.new(Vector3.new(-bedwars.BowConstantsTable.RelX, -bedwars.BowConstantsTable.RelY, -bedwars.BowConstantsTable.RelZ)))
		switchItem(item.tool, 0)
		task.wait(0.1)
		bedwars.ProjectileController:createLocalProjectile(bedwars.ProjectileMeta[proj], proj, proj, shootPosition.Position, '', shootPosition.LookVector * speed, {drawDurationSeconds = 1})
		if projectileRemote:InvokeServer(item.tool, proj, proj, shootPosition.Position, pos, shootPosition.LookVector * speed, httpService:GenerateGUID(true), {drawDurationSeconds = 1}, workspace:GetServerTimeNow() - 0.045) then
			local shoot = bedwars.ItemMeta[item.itemType].projectileSource.launchSound
			shoot = shoot and shoot[math.random(1, #shoot)] or nil
			if shoot then
				bedwars.SoundManager:playSound(shoot)
			end
		end
	end
	
	local LongJumpMethods = {
		cannon = function(_, pos, dir)
			pos = pos - Vector3.new(0, (entitylib.character.HipHeight + (entitylib.character.RootPart.Size.Y / 2)) - 3, 0)
			local rounded = Vector3.new(math.round(pos.X / 3) * 3, math.round(pos.Y / 3) * 3, math.round(pos.Z / 3) * 3)
			bedwars.placeBlock(rounded, 'cannon', false)
	
			task.delay(0, function()
				local block, blockpos = getPlacedBlock(rounded)
				if block and block.Name == 'cannon' and (entitylib.character.RootPart.Position - block.Position).Magnitude < 20 then
					local breaktype = bedwars.ItemMeta[block.Name].block.breakType
					local tool = store.tools[breaktype]
					if tool then
						switchItem(tool.tool)
					end
	
					bedwars.Client:Get(remotes.CannonAim):SendToServer({
						cannonBlockPos = blockpos,
						lookVector = dir
					})
	
					local broken = 0.1
					if bedwars.BlockController:calculateBlockDamage(lplr, {blockPosition = blockpos}) < block:GetAttribute('Health') then
						broken = 0.4
						bedwars.breakBlock(block, true, true)
					end
	
					task.delay(broken, function()
						for _ = 1, 4 do
							local call = bedwars.Client:Get(remotes.CannonLaunch):CallServer({cannonBlockPos = blockpos})
							if call then
								bedwars.breakBlock(block, true, true)
								JumpSpeed = 5.25 * Value.Value
								JumpTick = tick() + 2.3
								Direction = Vector3.new(dir.X, 0, dir.Z).Unit
								break
							end
							task.wait(0.1)
						end
					end)
				end
			end)
		end,
		cat = function(_, _, dir)
			LongJump:Clean(vapeEvents.CatPounce.Event:Connect(function()
				JumpSpeed = 4 * Value.Value
				JumpTick = tick() + 2.5
				Direction = Vector3.new(dir.X, 0, dir.Z).Unit
				entitylib.character.RootPart.Velocity = Vector3.zero
			end))
	
			if not bedwars.AbilityController:canUseAbility('CAT_POUNCE') then
				repeat task.wait() until bedwars.AbilityController:canUseAbility('CAT_POUNCE') or not LongJump.Enabled
			end
	
			if bedwars.AbilityController:canUseAbility('CAT_POUNCE') and LongJump.Enabled then
				bedwars.AbilityController:useAbility('CAT_POUNCE')
			end
		end,
		fireball = function(item, pos, dir)
			launchProjectile(item, pos, 'fireball', 60, dir)
		end,
		grappling_hook = function(item, pos, dir)
			launchProjectile(item, pos, 'grappling_hook_projectile', 140, dir)
		end,
		jade_hammer = function(item, _, dir)
			if not bedwars.AbilityController:canUseAbility(item.itemType..'_jump') then
				repeat task.wait() until bedwars.AbilityController:canUseAbility(item.itemType..'_jump') or not LongJump.Enabled
			end
	
			if bedwars.AbilityController:canUseAbility(item.itemType..'_jump') and LongJump.Enabled then
				bedwars.AbilityController:useAbility(item.itemType..'_jump')
				JumpSpeed = 1.4 * Value.Value
				JumpTick = tick() + 2.5
				Direction = Vector3.new(dir.X, 0, dir.Z).Unit
			end
		end,
		tnt = function(item, pos, dir)
			pos = pos - Vector3.new(0, (entitylib.character.HipHeight + (entitylib.character.RootPart.Size.Y / 2)) - 3, 0)
			local rounded = Vector3.new(math.round(pos.X / 3) * 3, math.round(pos.Y / 3) * 3, math.round(pos.Z / 3) * 3)
			start = Vector3.new(rounded.X, start.Y, rounded.Z) + (dir * (item.itemType == 'pirate_gunpowder_barrel' and 2.6 or 0.2))
			bedwars.placeBlock(rounded, item.itemType, false)
		end,
		wood_dao = function(item, pos, dir)
			if (lplr.Character:GetAttribute('CanDashNext') or 0) > workspace:GetServerTimeNow() or not bedwars.AbilityController:canUseAbility('dash') then
				repeat task.wait() until (lplr.Character:GetAttribute('CanDashNext') or 0) < workspace:GetServerTimeNow() and bedwars.AbilityController:canUseAbility('dash') or not LongJump.Enabled
			end
	
			if LongJump.Enabled then
				if not (LegitAura and LegitAura.Enabled) then
					bedwars.SwordController.lastAttack = workspace:GetServerTimeNow()
				end
				switchItem(item.tool, 0.1)
				replicatedStorage['events-@easy-games/game-core:shared/game-core-networking@getEvents.Events'].useAbility:FireServer('dash', {
					direction = dir,
					origin = pos,
					weapon = item.itemType
				})
				JumpSpeed = 4.5 * Value.Value
				JumpTick = tick() + 2.4
				Direction = Vector3.new(dir.X, 0, dir.Z).Unit
			end
		end
	}
	for _, v in {'stone_dao', 'iron_dao', 'diamond_dao', 'emerald_dao'} do
		LongJumpMethods[v] = LongJumpMethods.wood_dao
	end
	LongJumpMethods.void_axe = LongJumpMethods.jade_hammer
	LongJumpMethods.siege_tnt = LongJumpMethods.tnt
	LongJumpMethods.pirate_gunpowder_barrel = LongJumpMethods.tnt
	
	LongJump = vape.Categories.Blatant:CreateModule({
		Name = 'LongJump',
		Function = function(callback)
			frictionTable.LongJump = callback or nil
			updateVelocity()
			if callback then
				LongJump:Clean(vapeEvents.EntityDamageEvent.Event:Connect(function(damageTable)
					if damageTable.entityInstance == lplr.Character and damageTable.fromEntity == lplr.Character and (not damageTable.knockbackMultiplier or not damageTable.knockbackMultiplier.disabled) then
						local knockbackBoost = bedwars.KnockbackUtil.calculateKnockbackVelocity(Vector3.one, 1, {
							vertical = 0,
							horizontal = (damageTable.knockbackMultiplier and damageTable.knockbackMultiplier.horizontal or 1)
						}).Magnitude * 1.1
	
						if knockbackBoost >= JumpSpeed then
							local pos = damageTable.fromPosition and Vector3.new(damageTable.fromPosition.X, damageTable.fromPosition.Y, damageTable.fromPosition.Z) or damageTable.fromEntity and damageTable.fromEntity.PrimaryPart.Position
							if not pos then return end
							local vec = (entitylib.character.RootPart.Position - pos)
							JumpSpeed = knockbackBoost
							JumpTick = tick() + 2.5
							Direction = Vector3.new(vec.X, 0, vec.Z).Unit
						end
					end
				end))
				LongJump:Clean(vapeEvents.GrapplingHookFunctions.Event:Connect(function(dataTable)
					if dataTable.hookFunction == 'PLAYER_IN_TRANSIT' then
						local vec = entitylib.character.RootPart.CFrame.LookVector
						JumpSpeed = 2.5 * Value.Value
						JumpTick = tick() + 2.5
						Direction = Vector3.new(vec.X, 0, vec.Z).Unit
					end
				end))
	
				start = entitylib.isAlive and entitylib.character.RootPart.Position or nil
				LongJump:Clean(runService.PreSimulation:Connect(function(dt)
					local root = entitylib.isAlive and entitylib.character.RootPart or nil
	
					if root and isnetworkowner(root) then
						if JumpTick > tick() then
							root.AssemblyLinearVelocity = Direction * (getSpeed() + ((JumpTick - tick()) > 1.1 and JumpSpeed or 0)) + Vector3.new(0, root.AssemblyLinearVelocity.Y, 0)
							if entitylib.character.Humanoid.FloorMaterial == Enum.Material.Air and not start then
								root.AssemblyLinearVelocity += Vector3.new(0, dt * (workspace.Gravity - 23), 0)
							else
								root.AssemblyLinearVelocity = Vector3.new(root.AssemblyLinearVelocity.X, 15, root.AssemblyLinearVelocity.Z)
							end
							start = nil
						else
							if start then
								root.CFrame = CFrame.lookAlong(start, root.CFrame.LookVector)
							end
							root.AssemblyLinearVelocity = Vector3.zero
							JumpSpeed = 0
						end
					else
						start = nil
					end
				end))

				if store.hand and store.hand.tool and LongJumpMethods[store.hand.tool.Name] then
					task.spawn(LongJumpMethods[store.hand.tool.Name], getItem(store.hand.tool.Name), start, (CameraDir.Enabled and gameCamera or entitylib.character.RootPart).CFrame.LookVector)
					return
				end
				
				local foundItem = false
				for i, v in LongJumpMethods do
					local item = getItem(i)
					if item or store.equippedKit == i then
						foundItem = true
						task.spawn(v, item, start, (CameraDir.Enabled and gameCamera or entitylib.character.RootPart).CFrame.LookVector)
						break
					end
				end
				if not foundItem then
					notif("LongJump", "unable to find tool to use Long Jump with gng", 3)
					LongJump:Toggle()
					return
				end
			else
				JumpTick = tick()
				Direction = nil
				JumpSpeed = 0
			end
		end,
		ExtraText = function()
			return 'Heatseeker'
		end,
		Tooltip = 'lets you jump farther'
	})
	Value = LongJump:CreateSlider({
		Name = 'Speed',
		Min = 1,
		Max = 37,
		Default = 37,
		Suffix = function(val)
			return val == 1 and 'stud' or 'studs'
		end
	})
	CameraDir = LongJump:CreateToggle({
		Name = 'Camera Direction'
	})
end)

